  insert into public.subjects (slug, name_ar, name_en, grade, semester, description, icon, theme, sort_order, status, source_label)
  insert into public.units (subject_id, number, title, sort_order, status)
  insert into public.lessons (subject_id, unit_id, legacy_id, number, title, page_start, page_end, sort_order, status)
insert into _legacy_q values
('rv8.u1.l1.1', 'u1-l1', 'ما معنى أنّ القرآن الكريم نزل مُنجَّمًا؟', 'تذكّر أن نزوله استمرّ سنواتٍ طويلة، ولم يكن دفعة واحدة.', 'نزل القرآن مُنجَّمًا أي مُفرَّقًا على مدى سنوات النبوة، لا جملةً واحدة.', 1, 4, 1, false, ''),
('rv8.u1.l1.2', 'u1-l1', 'في كم سنة نزل القرآن الكريم على النبي ﷺ؟', 'المدة تشمل الفترة المكية والفترة المدنية معًا.', 'نزل القرآن على النبي ﷺ مُنجَّمًا في ٢٣ سنة.', 1, 4, 2, false, ''),
('rv8.u1.l1.3', 'u1-l1', 'ما الحكمة من نزول القرآن الكريم مُنجَّمًا؟', 'فكّر في أثر نزوله شيئًا فشيئًا على قلب النبي ﷺ وعلى الحفظ والفهم.', 'نزل القرآن مُنجَّمًا لتثبيت فؤاد النبي ﷺ وتيسير حفظه وفهمه وتدبّره، كما في قوله تعالى: ﴿كذلك لنثبت به فؤادك ورتلناه ترتيلا﴾.', 2, 4, 3, false, ''),
('rv8.u1.l1.4', 'u1-l1', 'ما أول ما نزل من القرآن الكريم؟', 'أول ما نزل يدعو إلى القراءة.', 'أول ما نزل من القرآن الكريم قوله تعالى: ﴿اقرأ باسم ربك الذي خلق﴾.', 1, 4, 4, false, ''),
('rv8.u1.l1.5', 'u1-l1', 'تنقسم آيات القرآن الكريم باعتبار سبب النزول إلى قسمين، هما:', 'التقسيم هنا مبنيّ على وجود سببٍ للنزول أو عدم وجوده.', 'باعتبار سبب النزول: قسمٌ نزل ابتداءً دون سبب لهداية الخلق إلى الحق، وقسمٌ نزل بسبب حادثة وقعت أو سؤال وُجّه إلى النبي ﷺ.', 1, 4, 5, false, ''),
('rv8.u1.l1.5-ex1', 'u1-l1', 'أيٌّ مما يأتي من أمثلة ما نزل ابتداءً دون سبب؟', 'ما نزل ابتداءً جاء لهداية الخلق، ولم يكن جوابًا عن سؤال أو تعقيبًا على حادثة.', 'من أمثلة ما نزل ابتداءً: قضايا الإيمان بالله، وقصص الأنبياء، وأخبار الأمم السابقة والمواعظ، ووصف الجنة والنار.', 2, 4, 6, false, ''),
('rv8.u1.l1.5-ex2', 'u1-l1', 'معظم الآيات التي نزلت بسبب حادثة أو سؤال تتحدث عن:', 'هذه الآيات تبيّن ما يتصل بالحادثة أو تجيب عن السؤال، فماذا يحتاج الناس غالبًا؟', 'ما نزل بسبب حادثة أو سؤال تنزل فيه الآيات ببيان ما يتصل بالحادثة أو بجواب السؤال، ومعظمه عن التشريع والأحكام.', 2, 4, 7, false, ''),
('rv8.u1.l1.5-ex3', 'u1-l1', 'نزلت سورة ﴿تبت يدا أبي لهب وتب﴾ بسبب:', 'تذكّر ما حدث بعد نزول قوله تعالى: ﴿وأنذر عشيرتك الأقربين﴾.', 'لما نزل قوله تعالى: ﴿وأنذر عشيرتك الأقربين﴾ صعد النبي ﷺ الصفا ودعا قومه، فقال أبو لهب: تبًّا لك، فنزلت السورة؛ فهي مما نزل بسبب حادثة وقعت.', 2, 4, 8, false, ''),
('rv8.u1.l1.note-1', 'u1-l1', 'ما وقع قبل عهد النبي ﷺ من أحداث، أو ما سيقع بعد وفاته كأحوال يوم القيامة:', 'سبب النزول مرتبط بوقت نزول الآيات نفسه.', 'سبب النزول ما نزل بشأنه قرآنٌ وقت وقوعه، لذلك لا يُعدّ ما وقع قبل عهد النبي ﷺ أو بعد وفاته سببًا للنزول وإن تحدثت عنه الآيات.', 2, 5, 9, false, ''),
('rv8.u1.l1.6', 'u1-l1', 'لماذا يُعدّ علم أسباب النزول من علوم القرآن المهمة؟', 'فكّر في الصورة التي يرسمها لنا هذا العلم عن الزمان والمكان والمجتمع وقت النزول.', 'علم أسباب النزول يكشف الظرفين الزماني والمكاني والسياق التاريخي والاجتماعي للآيات، فيوضح أحوال البداوة والحضارة والسلم والحرب وسعة الرزق والجوع.', 2, 5, 10, false, ''),
('rv8.u1.l1.7', 'u1-l1', 'ما الطريق الوحيد لمعرفة أسباب النزول؟', 'من الذين شاهدوا نزول الوحي بأنفسهم؟', 'لا سبيل لمعرفة أسباب النزول إلا بالنقل الصحيح عن الصحابة رضي الله عنهم؛ ولذلك لا تُعرف بالاجتهاد والرأي.', 1, 5, 11, false, ''),
('rv8.u1.l1.8', 'u1-l1', 'لماذا لا سبيل لمعرفة أسباب النزول إلا بالنقل الصحيح عن الصحابة رضوان الله عليهم؟', 'ما الذي يميّز الصحابة عن غيرهم بالنسبة إلى زمن نزول الوحي؟', 'الصحابة رضوان الله عليهم عاصروا الوحي والتنزيل، وسمعوا من النبي ﷺ، ووقفوا على الأحوال والأسباب والمناسبات التي اقترنت بنزول الآيات.', 2, 5, 12, false, ''),
('rv8.u1.l1.9', 'u1-l1', 'علامَ يدلّ قول ابن مسعود رضي الله عنه: «ما من كتاب الله سورة إلا أنا أعلم حيث نزلت، وما من آية إلا أنا أعلم فيما أُنزلت»؟', 'ابن مسعود يتحدث عن معرفته بمكان النزول وسببه.', 'يدل قول ابن مسعود رضي الله عنه على علم الصحابة رضوان الله عليهم بأسباب النزول.', 2, 5, 13, false, ''),
('rv8.u1.l1.10', 'u1-l1', 'ما تعريف سبب النزول؟', 'التعريف يربط بين أمرٍ وقع ونزول القرآن في وقته.', 'سبب النزول: ما نزل بشأنه قرآنٌ وقت وقوعه، كحادثة أو سؤال.', 1, 5, 14, false, ''),
('rv8.u1.l1.11', 'u1-l1', 'أيٌّ مما يأتي ليس من فوائد معرفة أسباب النزول؟', 'تذكّر القاعدة: «العبرة بعموم اللفظ لا بخصوص السبب».', 'من فوائد معرفة أسباب النزول: معرفة من نزلت فيه الآية، ومعرفة الحكمة من التشريع، وفهم الآية وإزالة الإشكال، وتسهيل الحفظ. أما الحكم فلا يقتصر على من نزلت فيه.', 2, 5, 15, false, ''),
('rv8.u1.l1.12a', 'u1-l1', 'معرفة سبب نزول قوله تعالى: ﴿وكلوا واشربوا حتى يتبين لكم الخيط الأبيض من الخيط الأسود من الفجر﴾ تفيد في:', 'بعض الناس فهموا «الخيط» فهمًا غير مقصود.', 'سبب نزول هذه الآية يزيل الإشكال في فهم المقصود بالخيط الأبيض والخيط الأسود، فالفائدة: فهم الآية وإزالة الإشكال.', 2, 6, 16, false, ''),
('rv8.u1.l1.12b', 'u1-l1', 'معرفة سبب نزول قوله تعالى: ﴿يوصيكم الله في أولادكم للذكر مثل حظ الأنثيين﴾ تفيد في:', 'الآية تتحدث عن حكمٍ شرعي في الميراث.', 'معرفة سبب نزول آية الميراث تبيّن الحكمة من التشريع.', 2, 6, 17, false, ''),
('rv8.u1.l1.13', 'u1-l1', 'فيمن نزل قوله تعالى: ﴿ومن الناس من يشري نفسه ابتغاء مرضات الله والله رءوف بالعباد﴾؟', 'صحابيٌّ لحقه المشركون عند هجرته فأعطاهم ماله.', 'نزلت في الصحابي صهيب بن سنان الرومي عند هجرته؛ لحقه المشركون فأعطاهم ما لديه من مال فخلّوا سبيله.', 2, 6, 18, false, ''),
('rv8.u1.l1.14', 'u1-l1', 'فيمن نزل قوله تعالى: ﴿يوصيكم الله في أولادكم للذكر مثل حظ الأنثيين﴾؟', 'امرأةٌ جاءت إلى الرسول ﷺ بابنتين أخذ عمّهما ميراثهما.', 'نزلت في امرأة سعد بن الربيع التي جاءت إلى الرسول ﷺ بابنتين لها تشتكي عمّهما الذي أخذ ميراثهما.', 2, 6, 19, false, ''),
('rv8.u1.l1.15', 'u1-l1', 'ما معنى قاعدة «العبرة بعموم اللفظ لا بخصوص السبب»؟', 'انتبه إلى كلمة «عموم»: هل يتوقف الحكم عند الحادثة الأولى؟', 'إذا نزلت الآية بسبب واقعة في زمن الرسول ﷺ وكان لفظها عامًّا، فإن حكمها لا يقتصر على تلك الواقعة، بل يكون عامًّا لكل ما شابهها؛ لأن أحكام القرآن عامة لكل زمان ومكان.', 3, 6, 20, false, ''),
('rv8.u1.l1.16a', 'u1-l1', 'ما سبب نزول قوله تعالى: ﴿إن الله يأمركم أن تؤدوا الأمانات إلى أهلها﴾؟', 'الحادثة وقعت يوم فتح مكة وتتعلق بالكعبة.', 'نزلت الآية في عثمان بن طلحة رضي الله عنه عندما أخذ منه الرسول ﷺ مفتاح الكعبة يوم الفتح.', 2, 6, 21, false, ''),
('rv8.u1.l1.16b', 'u1-l1', 'ما الحكم الذي تضمّنه قوله تعالى: ﴿إن الله يأمركم أن تؤدوا الأمانات إلى أهلها﴾؟', 'تذكّر أن العبرة بعموم اللفظ لا بخصوص السبب.', 'تضمنت الآية وجوب أداء الأمانة إلى أهلها من المسلمين وغيرهم، والحكم عام يجب على الجميع في كل زمان ومكان.', 2, 6, 22, false, ''),
('rv8.u1.l1.17a', 'u1-l1', 'الآيات الكريمة التي تناولت قصة موسى عليه السلام مع فرعون:', 'قصص الأنبياء من أي القسمين؟', 'قصص الأنبياء ومنها قصة موسى عليه السلام مع فرعون من الآيات التي نزلت ابتداءً بدون سبب.', 1, 7, 23, false, ''),
('rv8.u1.l1.17b', 'u1-l1', 'معاصرة سبب النزول لنزول الآيات تُعدّ:', 'تذكّر تعريف سبب النزول: ما نزل بشأنه قرآنٌ «وقت وقوعه».', 'معاصرة سبب النزول للآيات شرط لقبول رواية سبب النزول.', 2, 7, 24, false, ''),
('rv8.u1.l1.17c', 'u1-l1', 'من شروط اعتبار الحادثة سببًا للنزول أن تكون قد وقعت:', 'الأحداث التي سبقت البعثة لا تُعدّ أسبابًا للنزول.', 'يُشترط أن تكون الحادثة قد وقعت أثناء عصر النبي ﷺ؛ فما وقع قبل عهده أو بعد وفاته لا يُعدّ سببًا للنزول.', 2, 7, 25, false, ''),
('rv8.u1.l1.18-1', 'u1-l1', 'صنّف قوله تعالى: ﴿ألم تر كيف فعل ربك بأصحاب الفيل﴾ من حيث سبب النزول:', 'متى وقعت حادثة أصحاب الفيل بالنسبة إلى البعثة؟', 'حادثة أصحاب الفيل وقعت قبل بعثة النبي ﷺ، فلا تُعدّ سببًا للنزول، والآية مما نزل ابتداءً.', 3, 7, 26, false, ''),
('rv8.u1.l1.18-2', 'u1-l1', 'صنّف قوله تعالى: ﴿يسألونك عن الأهلة قل هي مواقيت للناس والحج﴾ من حيث سبب النزول:', 'انظر إلى أول كلمة في الآية.', 'الآية جواب عن سؤال وُجّه للنبي ﷺ، فهي مما نزل بسبب.', 1, 7, 27, false, ''),
('rv8.u1.l1.18-3', 'u1-l1', 'صنّف قوله تعالى: ﴿إن المتقين في جنات وعيون﴾ من حيث سبب النزول:', 'وصف الجنة والنار من أي القسمين؟', 'الآية حديث عن اليوم الآخر (الجنة)، ووصف الجنة والنار مما نزل ابتداءً.', 2, 7, 28, false, ''),
('rv8.u1.l1.18-4', 'u1-l1', 'صنّف قوله تعالى: ﴿عبس وتولى أن جاءه الأعمى﴾ من حيث سبب النزول:', 'الآية تتحدث عن موقفٍ حدث فعلًا مع رجلٍ أعمى.', 'نزلت الآيات بسبب حادثة وقعت في عهد النبي ﷺ.', 2, 7, 29, false, ''),
('rv8.u1.l1.20a', 'u1-l1', 'ما سبب نزول قوله تعالى: ﴿ولله المشرق والمغرب فأينما تولوا فثم وجه الله﴾؟', 'الآية تتحدث عن جهة الصلاة في أحوالٍ خاصة.', 'نزلت في نافلة السفر في أثناء السفر على الراحلة، أو فيمن لم يعرف القبلة وصلى باجتهاده.', 3, 8, 30, false, ''),
('rv8.u1.l1.21', 'u1-l1', 'ما الإشكال الذي أزاله قوله تعالى: ﴿من الفجر﴾ في آية الخيط الأبيض والخيط الأسود؟', 'كان بعض الرجال يربطون خيطين في أرجلهم حتى يتبيّن لهم لونهما.', 'كان الرجال إذا أرادوا الصوم ربط أحدهم في رجله خيطًا أبيض وخيطًا أسود، فأنزل الله ﴿من الفجر﴾ فعلموا أنه يعني الليل والنهار.', 2, 8, 31, false, ''),
('rv8.u1.l2.1', 'u1-l2', 'لماذا بدأت سورة الحجرات بأول نداء واستجاشة للقلوب بـ ﴿يا أيها الذين آمنوا﴾؟', 'فكّر في أثر مناداة الإنسان بأحبّ صفاته إليه.', 'النداء بـ ﴿يا أيها الذين آمنوا﴾ تشريف وتكريم للمؤمنين، وتنبيه لهم إلى الصفة التي تربطهم بالله سبحانه وتعالى وهي الإيمان.', 2, 9, 1, false, ''),
('rv8.u1.l2.2', 'u1-l2', 'ما التوجيه الرباني للمؤمنين في قوله تعالى: ﴿يا أيها الذين آمنوا لا تقدموا بين يدي الله ورسوله﴾؟', 'معنى «لا تقدّموا»: لا تسبقوا.', 'يأمر الله تعالى المؤمنين بحسن الأدب معه ومع الرسول ﷺ بعدم التقدم بقول أو فعل حتى يعلموا حكم الله تعالى ورسوله فيه.', 2, 9, 2, false, ''),
('rv8.u1.l2.3', 'u1-l2', 'لماذا نهى الله تعالى المؤمنين عن التقدّم على الرسول ﷺ بقولٍ أو فعل؟', 'الأمر يتعلق بمصدر الأحكام وطريقة تلقّيها.', 'لأن ذلك منهج في التلقي والتنفيذ وأصل من أصول التشريع، فلا ينبغي للمؤمن أن يتقدم حكم الله تعالى ورسوله ﷺ.', 2, 9, 3, false, ''),
('rv8.u1.l2.4', 'u1-l2', 'أيٌّ مما يأتي ليس من الآداب التي يجب على المؤمن الالتزام بها مع النبي ﷺ كما في الآيات؟', 'من الآداب ترك أمرٍ في طريقة مناداته ﷺ.', 'من الآداب: عدم التقدم بين يدي الرسول ﷺ، وعدم رفع الصوت فوق صوته، وعدم مناداته باسمه مجرّدًا.', 1, 9, 4, false, ''),
('rv8.u1.l2.5', 'u1-l2', 'ماذا أعدّ الله تعالى للمتأدّبين مع رسوله ﷺ بخفض الصوت؟', 'جزاء الأدب مع النبي ﷺ جزاءٌ حسن.', 'بشّر الله تعالى المتأدبين مع رسوله ﷺ بخفض الصوت بالمغفرة والأجر العظيم.', 1, 9, 5, false, ''),
('rv8.u1.l2.6', 'u1-l2', 'يظن بعض الناس أن التأدب مع الرسول ﷺ يكون في مجلسه وحياته فقط. ما الصواب؟', 'حرمته ﷺ حيًّا كحرمته ميتًا.', 'التأدب مع الرسول ﷺ يكون في حضرته وغيابه وعند قبره، وكذلك عند قراءة حديثه، فلا يُرفع الصوت فوق صوت قارئ الحديث بقصد الاعتراض.', 2, 9, 6, false, ''),
('rv8.u1.l2.7', 'u1-l2', 'ما النتيجة المترتبة على عدم الالتزام بأدب الحديث مع رسول الله ﷺ؟', 'الآية تختم بقوله: ﴿وأنتم لا تشعرون﴾.', 'إساءة الأدب مع النبي ﷺ تؤدي إلى حبوط العمل وضياع الثواب من حيث لا يشعر الإنسان.', 1, 10, 7, false, ''),
('rv8.u1.l2.8', 'u1-l2', 'ماذا استنكر قوله تعالى: ﴿إن الذين ينادونك من وراء الحجرات أكثرهم لا يعقلون﴾؟', 'الحجرات هي بيوت النبي ﷺ.', 'استنكرت الآية تصرف بعض الأعراب المنافي لأصول الأدب واللباقة، فلا ينبغي الصياح على النبي ﷺ وهو في خلوته في بيته، وكان الأولى لهم الصبر والانتظار حتى يخرج إليهم.', 2, 10, 8, false, ''),
('rv8.u1.l2.9c', 'u1-l2', 'ما المعنى التربوي الذي يدل عليه ذمّ الذين ينادون النبي ﷺ من وراء الحجرات؟', 'الآيات تمدح من يغضّون أصواتهم.', 'من المعاني التربوية في الآيات: اعتياد خفض الصوت ولين الجانب في التعامل دليل على التقوى.', 2, 10, 9, false, ''),
('rv8.u1.l2.9d', 'u1-l2', 'ما المعنى التربوي في قوله تعالى: ﴿ولو أنهم صبروا حتى تخرج إليهم لكان خيرا لهم﴾؟', 'انظر إلى ما وصفته الآية بأنه «خير».', 'التحلي بالصبر وعدم الاستعجال في الأمور فيه خيرية للإنسان.', 1, 10, 10, false, ''),
('rv8.u1.l2.10a', 'u1-l2', 'ما الحكم على التدافع ورفع الصوت عند زيارة قبر الرسول ﷺ؟', 'تذكّر أن الأدب مع النبي ﷺ لا يختص بحياته.', 'تصرف خاطئ؛ على المسلم أن يتأدب في حضرة النبي ﷺ، فحرمته حيًّا كحرمته ميتًا.', 1, 10, 11, false, ''),
('rv8.u1.l2.10b', 'u1-l2', 'ما الحكم على مناداة أهل الفضل، مثل المعلّم والمربّي، باسمه مجرّدًا؟', 'الأدب مع النبي ﷺ يعلّمنا أدب مخاطبة كل صاحب مقام.', 'تصرف خاطئ؛ يجب مناداة أهل الفضل بما يناسب مقامهم.', 1, 10, 12, false, ''),
('rv8.u1.l2.10c', 'u1-l2', 'ما الحكم على الإفتاء بغير علم ودون الرجوع إلى مصادر التشريع الإسلامي؟', 'تذكّر النهي عن التقدّم بين يدي الله ورسوله.', 'تصرف خاطئ؛ فيجب أن يكون أهلًا للفتوى، فلا يفتي بغير علم، وعليه الرجوع إلى مصادر التشريع الإسلامي وفي مقدمتها القرآن والسنة.', 2, 11, 13, false, ''),
('rv8.u1.l2.11', 'u1-l2', 'أمر الله تعالى المسلمين عند مخاطبة الأنبياء والعلماء وكل من له مقام بلزوم خفض:', 'الآية الثانية من السورة تنهى عن رفع شيءٍ فوق صوت النبي ﷺ.', 'أمر الله تعالى بلزوم خفض الصوت عند مخاطبة الأنبياء والعلماء وكل من له مقام.', 1, 11, 14, false, ''),
('rv8.u1.l2.12', 'u1-l2', 'خاطب الله تعالى النبي محمدًا ﷺ بـ ﴿يا أيها النبي﴾ و﴿يا أيها الرسول﴾ ولم يخاطبه باسمه مجرّدًا، بينما نادى غيره من الأنبياء بأسمائهم ﴿يا آدم﴾. ما دلالة ذلك؟', 'فكّر في ما يدل عليه اختيار الصفة بدل الاسم.', 'في ذلك تعظيم وتبجيل للنبي ﷺ، وتخصيص له عمّن سواه وبيان لقدره ومكانته، وتعليم للأمة في كيفية التأدب مع مقامه الشريف.', 2, 11, 15, false, ''),
('rv8.u1.l2.13', 'u1-l2', 'ما رأيك في من يزعجون الآخرين بالطرق على الباب حتى يخرجوا إليهم؟', 'تذكّر ما قالته الآيات عن الذين نادوا النبي ﷺ من وراء الحجرات.', 'تصرفهم خاطئ؛ عليهم الاستئذان بلطف دون إزعاج لأهل البيت، مسترشدين بآداب الإسلام في تخيّر الوقت المناسب للزيارة وتجنب إزعاج الناس في خلواتهم ووقت راحتهم.', 1, 11, 16, false, ''),
('rv8.u1.l3.1', 'u1-l3', 'ما دلالة قول النبي ﷺ لابن عباس: «يا غلام»؟', 'فكّر في أسلوب المعلم حين يبدأ بنداءٍ لطيف قبل النصيحة.', 'النداء «يا غلام» يدل على أهمية شدّ انتباه المتعلم وتهيئته لما سيُلقى عليه بلطف العبارة، لما في ذلك من استمالة وترقيق لقلبه لاستقبال العلم والنصح والإرشاد.', 2, 12, 1, false, ''),
('rv8.u1.l3.2', 'u1-l3', 'أين كان ابن عباس رضي الله عنهما عندما أوصاه النبي ﷺ؟', 'يقول ابن عباس في أول الحديث: «كنتُ خلف رسول الله ﷺ يومًا».', 'كان ابن عباس خلف النبي ﷺ رديفًا له على دابته.', 1, 12, 2, false, ''),
('rv8.u1.l3.3', 'u1-l3', 'ما دلالة قول النبي ﷺ: «إني أعلّمك كلمات»؟', 'لماذا قال «كلمات» ولم يقل «دروسًا طويلة»؟', 'عبّر النبي ﷺ بلفظ «كلمات» ليؤذن أنها قليلة الحفظ سهلة الاستيعاب.', 2, 12, 3, false, ''),
('rv8.u1.l3.4a', 'u1-l3', 'ما معنى وصية النبي ﷺ: «احفظ الله يحفظك»؟', 'الجزاء من جنس العمل: حِفظٌ بحِفظ.', 'احفظ الله: بتقواه وحفظ حدوده وامتثال أوامره، فيحفظه الله في دينه ودنياه، ويجده تجاهه في كل أحواله يحوطه ويسدده ويوفقه ويرعاه.', 2, 12, 4, false, ''),
('rv8.u1.l3.4b', 'u1-l3', 'ما معنى وصية النبي ﷺ: «إذا سألت فاسأل الله، وإذا استعنت فاستعن بالله»؟', 'تذكّر قوله تعالى: ﴿إياك نعبد وإياك نستعين﴾.', 'المعنى: سؤال الله تعالى وطلب العون منه واللجوء إليه، والله يحب أن يُسأل، فباب عطائه مفتوح بالليل والنهار وهو النافع والضار.', 2, 12, 5, false, ''),
('rv8.u1.l3.4c', 'u1-l3', 'ما معنى وصية النبي ﷺ: «واعلم أن الأمة لو اجتمعت على أن ينفعوك بشيء لم ينفعوك إلا بشيء قد كتبه الله لك»؟', 'الوصية تتحدث عن القضاء والقدر وتعلّق القلب.', 'المعنى: اليقين بأنه لا يصيب الإنسان إلا ما كتب الله له وقدّره، فعليه أن يترك التعلق بمن سواه.', 2, 12, 6, false, ''),
('rv8.u1.l3.5', 'u1-l3', 'ما أهمية الوصايا الواردة في حديث ابن عباس رضي الله عنهما؟', 'فكّر في موضوعها: تعلّق القلب بالله والتوجه إليه.', 'هي وصايا عظيمة نافعة تحوي قواعد من أهم أمور الدين، وتعد أصلًا في تربية النشء على العقيدة الصحيحة من تعلّق القلب بالله تعالى والصدق معه والتوجه إليه وسؤاله والاستعانة به وتفويض الأمر إليه.', 2, 13, 7, false, ''),
('rv8.u1.l3.6a', 'u1-l3', 'أيّ وصايا الحديث تتفق مع قوله تعالى عن يوسف عليه السلام: ﴿كذلك لنصرف عنه السوء والفحشاء إنه من عبادنا المخلصين﴾؟', 'صرف الله السوء عن يوسف عليه السلام لأنه كان مخلصًا حافظًا لحدود الله.', 'تتفق الآية مع وصية «احفظ الله يحفظك»؛ فقد حفظ الله يوسف عليه السلام وصرف عنه السوء.', 3, 13, 8, false, ''),
('rv8.u1.l3.6b', 'u1-l3', 'أيّ وصايا الحديث تتفق مع قوله تعالى: ﴿قلنا يا نار كوني بردا وسلاما على إبراهيم وأرادوا به كيدا فجعلناهم الأخسرين﴾؟', 'أراد القوم كيدًا بإبراهيم عليه السلام، فهل استطاعوا ضرّه؟', 'اجتمع القوم على الإضرار بإبراهيم عليه السلام فلم يضرّوه، وهذا يتفق مع قوله ﷺ: «ولو اجتمعوا على أن يضروك بشيء لم يضروك إلا بشيء قد كتبه الله عليك».', 3, 13, 9, false, ''),
('rv8.u1.l3.6c', 'u1-l3', 'أيّ وصايا الحديث تتفق مع قوله تعالى: ﴿هنالك دعا زكريا ربه قال رب هب لي من لدنك ذرية طيبة إنك سميع الدعاء﴾؟', 'زكريا عليه السلام يطلب من الله أمرًا.', 'دعاء زكريا عليه السلام ربَّه وطلبه الذرية يتفق مع قوله ﷺ: «إذا سألت فاسأل الله».', 2, 13, 10, false, ''),
('rv8.u1.l3.6d', 'u1-l3', 'أيّ وصايا الحديث تتفق مع قوله تعالى: ﴿قال موسى لقومه استعينوا بالله واصبروا﴾؟', 'انظر إلى الفعل الذي أمر به موسى عليه السلام قومه.', 'أمر موسى عليه السلام قومه بالاستعانة بالله، وهذا يتفق مع قوله ﷺ: «وإذا استعنت فاستعن بالله».', 1, 13, 11, false, ''),
('rv8.u1.l3.7a', 'u1-l3', 'بمَ يُردّ على من يظن أن المواعظ المؤثرة يجب أن تكون طويلة؟', 'تذكّر أن حديث ابن عباس «كلمات» قليلة ومع ذلك عظيم الأثر.', 'تأثير المواعظ ليس بطولها، وإنما بعمق معانيها وأسلوب طرحها بما يستميل القلوب ويحقق الغاية منها.', 2, 13, 12, false, ''),
('rv8.u1.l3.7b', 'u1-l3', 'بمَ يُردّ على من يظن أن النفع والضر بيد العرّافين والمشعوذين؟', 'الحديث يقول: لو اجتمعت الأمة كلها لم تنفعك إلا بما كتبه الله.', 'الله تعالى هو النافع والضار، بيده ملكوت كل شيء، ولا حول ولا قوة للإنسان إلا به، أما ما سواه فلا يستطيعون دفع الضر عن أنفسهم.', 1, 13, 13, false, ''),
('rv8.u1.l3.8a', 'u1-l3', 'يُعدّ حديث ابن عباس رضي الله عنهما من جوامع الكلم؛ لأنه حوى وصايا عظيمة في كلمات:', 'جوامع الكلم: معانٍ كثيرة في ألفاظ ...', 'يعد الحديث من جوامع الكلم؛ لأنه حوى وصايا عظيمة في كلمات قليلة يسيرة.', 1, 13, 14, false, ''),
('rv8.u1.l3.8b', 'u1-l3', 'حفظ الله يكون بالوقوف على أوامره بالامتثال، وعلى نواهيه بـ:', 'ما نهى الله عنه لا نفعله، بل ...', 'حفظ الله يكون بالوقوف على أوامره بالامتثال، وعلى نواهيه بالاجتناب.', 1, 13, 15, false, ''),
('rv8.u1.l3.8c', 'u1-l3', 'يلجأ المؤمن إلى الطبيب؛ لأنه سبب للعلاج والتداوي، لكنه متيقّن أن الشافي هو:', 'الطبيب والدواء أسباب، فمن المسبِّب؟', 'يأخذ المؤمن بالأسباب فيذهب إلى الطبيب، لكنه متيقن أن الشافي هو الله تعالى.', 1, 14, 16, false, ''),
('rv8.u1.l3.9a', 'u1-l3', '«كان رسول الله ﷺ يغتنم الفرص ليحث على الطاعة ويوجّه ويربي». أين تجد ذلك في حديث ابن عباس؟', 'أين كان ابن عباس عندما سمع الوصايا؟', 'اغتنم النبي ﷺ وجود ابن عباس رديفًا له على دابته فألقى إليه وصاياه.', 2, 14, 17, false, ''),
('rv8.u1.l3.10', 'u1-l3', 'ما القاعدة الشرعية المشتركة بين: ﴿فاذكروني أذكركم﴾، ﴿إن تنصروا الله ينصركم﴾، ﴿وأوفوا بعهدي أوف بعهدكم﴾، و«احفظ الله يحفظك»؟', 'انظر كيف يتكرر الفعل نفسه في كل نص: ذِكرٌ بذِكر، نصرٌ بنصر...', 'القاعدة المشتركة بين هذه النصوص: «الجزاء من جنس العمل».', 2, 14, 18, false, ''),
('rv8.u1.l4.1a', 'u1-l4', '«البصير» صفةٌ من الصفات ...... في حقه تعالى.', 'صفات الكمال الثابتة لله تعالى لا يمكن أن تنتفي عنه.', 'البصير صفة من الصفات الواجبة في حقه تعالى.', 1, 15, 1, false, ''),
('rv8.u1.l4.1b', 'u1-l4', 'وصفُه تعالى بالبصير ينفي عنه صفة:', 'ما ضدّ البصر؟', 'وصفه تعالى بالبصير ينفي عنه صفة العمى.', 1, 15, 2, false, ''),
('rv8.u1.l4.2', 'u1-l4', 'ما معنى اسم الله «البصير»؟', 'بصر الله تعالى لا يحدّه شيء.', 'البصير: هو الذي أحاط بصره بجميع الموجودات في عالم الغيب والشهادة، مهما خفيت أو ظهرت، ومهما دقّت أو عظمت.', 2, 15, 3, false, ''),
('rv8.u1.l4.3a', 'u1-l4', 'أيٌّ مما يأتي من صفات بصر الله تعالى؟', 'صفة البصر في حق الله تعالى صفة كمال لا تشبه صفات الخلق.', 'بصر الله تعالى منزّه عن الحدقة والأجفان، وهو صفة كمال، يرى جميع الخلق بلا استثناء، ويرى الظواهر والبواطن، ويحيط بدقائق ذرات الوجود، ويعلم خائنة الأعين وما تخفي الصدور.', 2, 15, 4, false, ''),
('rv8.u1.l4.3b', 'u1-l4', 'أيٌّ مما يأتي من صفات بصر المخلوقات؟', 'بصر الإنسان له حدود مهما كان قويًّا.', 'بصر الخلق محدود يحتاج إلى آلة الإبصار، ولا يبصر ما كان خارج طاقته، ولا يرى دقائق الأشياء، ويبصر ظواهر الأمور دون حقيقتها، ولا يبصر ما في داخل الإنسان من خفايا.', 2, 15, 5, false, ''),
('rv8.u1.l4.4', 'u1-l4', 'ماذا تستنتج من قوله تعالى: ﴿يعلم خائنة الأعين وما تخفي الصدور﴾؟', '«ما تخفي الصدور» أمور داخلية لا يراها الناس.', 'نستنتج أن بصره تعالى لا يحده شيء، فهو يبصر نيات الإنسان وبواعثه وما يخفيه صدره.', 2, 15, 6, false, ''),
('rv8.u1.l4.5-1', 'u1-l4', 'أيٌّ مما يأتي من آثار الإيمان باسم الله البصير على حياة المسلم؟', 'من أيقن أن الله يراه دائمًا، كيف يكون حاله في السر والعلن؟', 'من آثار الإيمان باسم الله البصير: مراقبة النفس في جميع الأحوال، وعدم الإقدام على المعاصي، والراحة والطمأنينة، وإتقان العبادة والعمل، والشعور بمعية الله، والتوكل عليه.', 1, 16, 7, false, ''),
('rv8.u1.l4.5-2', 'u1-l4', 'قال رسول الله ﷺ: «أن تعبد الله كأنك تراه، فإن لم تكن تراه فإنه يراك». أيّ آثار الإيمان باسم الله البصير يرتبط بهذا الحديث؟', 'من استحضر أن الله يراه وهو يعبده، كيف ستكون عبادته؟', 'الحديث مرتبط بإتقان العبادة والعمل؛ لأن المسلم يستحضر أن الله تعالى يراه.', 2, 16, 8, false, ''),
('rv8.u1.l4.6a', 'u1-l4', 'ما الأثر الإيماني لاسم الله البصير المستفاد من قوله تعالى لموسى وهارون: ﴿لا تخافا إنني معكما أسمع وأرى﴾؟', 'انظر إلى كلمة «معكما».', 'تدل الآية على الشعور بمعية الله تعالى.', 2, 16, 9, false, ''),
('rv8.u1.l4.6b', 'u1-l4', 'ما الأثر الإيماني لاسم الله البصير المستفاد من قوله تعالى: ﴿وأفوض أمري إلى الله إن الله بصير بالعباد﴾؟', 'تفويض الأمر إلى الله يعني ...', 'تفويض الأمر إلى الله تعالى يدل على التوكل عليه.', 2, 16, 10, false, ''),
('rv8.u1.l4.6c', 'u1-l4', 'ما الأثر الإيماني لاسم الله البصير المستفاد من قوله تعالى: ﴿وكفى بربك بذنوب عباده خبيرا بصيرا﴾؟', 'الآية تتحدث عن الذنوب.', 'الله تعالى يبصر ذنوب عباده، فيدفع ذلك المسلم إلى مراقبة الله والحياء منه وتجنب المعاصي والذنوب.', 2, 16, 11, false, ''),
('rv8.u1.l4.6d', 'u1-l4', 'ما الأثر الإيماني لاسم الله البصير المستفاد من قوله تعالى: ﴿وما تقدموا لأنفسكم من خير تجدوه عند الله إن الله بما تعملون بصير﴾؟', 'الآية تتحدث عن تقديم الخير.', 'علم المسلم أن الله بصير بعمله وأنه يجد خيره عنده يدفعه إلى الاجتهاد في العمل والمسارعة إليه.', 2, 16, 12, false, ''),
('rv8.u1.l4.6e', 'u1-l4', 'قال النبي ﷺ لأصحابه حين كانوا يكبّرون بأصوات عالية: «إنكم لا تدعون أصمّ ولا غائبًا، ولكن تدعون سميعًا بصيرًا». ما الأثر الإيماني المستفاد؟', 'الحديث عن الدعاء، والمدعوّ ليس غائبًا.', 'يدل الحديث على استشعار قرب الله تعالى واستجابته للدعاء.', 2, 16, 13, false, ''),
('rv8.u1.l4.7a', 'u1-l4', 'يوهم والدته أنه يذاكر دروسه بينما يستخدم الجهاز اللوحي. قيّم هذا التصرف:', 'قد يخفى الأمر عن الوالدة، فهل يخفى عن الله؟', 'تصرف خاطئ؛ عليه استشعار مراقبة الله تعالى له، فالله تعالى بصير يعلم السر وأخفى.', 1, 16, 14, false, ''),
('rv8.u1.l4.7b', 'u1-l4', 'يزيّف نتائج بحث علمي يتعلق بصحة البشر. قيّم هذا التصرف:', 'التزييف قد يخفى على الناس، لكن من الذي يراه ويطّلع عليه؟', 'تصرف خاطئ؛ عليه استشعار مراقبة الله تعالى، وأنه يراها ومطلع عليها، فحياة البشر أمانة ومسؤولية.', 1, 16, 15, false, ''),
('rv8.u1.l4.8a', 'u1-l4', 'الله تعالى يبصر ظواهر الأشياء وبواطنها، بينما الإنسان بعينه المجرّدة يبصر ...... فقط.', 'العين المجرّدة لا ترى ما في داخل الأشياء.', 'الإنسان بعينه المجردة يبصر ظواهرها فقط، أما الله تعالى فيبصر ظواهر الأشياء وبواطنها.', 1, 17, 16, false, ''),
('rv8.u1.l4.8b', 'u1-l4', 'قال تعالى: ﴿يستخفون من الناس ولا يستخفون من الله وهو معهم﴾. تنبّه الآية الإنسان ألا يجعل ...... أهون الناظرين إليه.', 'الآية تذمّ من يستحيي من الناس ولا يستحيي ممّن هو أحق بالحياء.', 'تنبه الآية الإنسان ألا يجعل الله تعالى أهون الناظرين إليه.', 2, 17, 17, false, ''),
('rv8.u1.l4.8c', 'u1-l4', 'يشير قوله تعالى: ﴿الذي يراك حين تقوم﴾ إلى أن استشعار مراقبة الله تعالى يربي في المسلم خُلُق:', 'من استحضر أن الله يراه، لمن يجعل عمله؟', 'استشعار مراقبة الله تعالى يربي في المسلم خلق الإخلاص.', 1, 17, 18, false, ''),
('rv8.u1.l4.9a', 'u1-l4', 'في دعاء موسى عليه السلام: ﴿رب اشرح لي صدري ... إنك كنت بنا بصيرا﴾، كيف استحضر اسم الله البصير؟', 'ختم موسى عليه السلام دعاءه بقوله: «إنك كنت بنا بصيرا».', 'استحضر موسى عليه السلام اسم الله البصير، فأحسن في الدعاء وفي الطلب من ربه، مستعطفًا إياه باسمه البصير.', 2, 17, 19, false, ''),
('rv8.u1.l4.9b', 'u1-l4', 'في قول إبراهيم عليه السلام: ﴿يا أبت لم تعبد ما لا يسمع ولا يبصر ولا يغني عنك شيئا﴾، كيف استحضر اسم الله البصير؟', 'إبراهيم عليه السلام يحاور أباه في عبادة الأصنام.', 'استثمر إبراهيم عليه السلام كون الآلهة عاجزة لا تسمع ولا تبصر ولا تنفع في دعوة والده إلى الله، واستخدمها حجة على أبيه في إثبات أحقية الله بالعبادة.', 2, 17, 20, false, ''),
('rv8.u1.l4.10', 'u1-l4', 'ورد اسم الله البصير في القرآن مقترنًا ببعض الأسماء الحسنى، وأكثر اسم اقترن به هو «السميع». ما دلالة ذلك؟', 'السمع للأقوال، والبصر للأفعال.', 'اقتران السميع بالبصير دلالة على الإحاطة بالخلق، وفي ذلك تنبيه للعاقل وتذكير كي يراقب نفسه وما يصدر عنها من أقوال وأفعال.', 3, 17, 21, false, ''),
('rv8.u1.l5.1', 'u1-l5', 'ما المقصود بمقاصد الشريعة الإسلامية؟', 'كلمة «مقاصد» تعني الأهداف.', 'مقاصد الشريعة الإسلامية: هي الغايات (الأهداف) التي أُنزلت الشريعة لأجل تحقيقها مصلحةً للعباد.', 1, 18, 1, false, ''),
('rv8.u1.l5.2a', 'u1-l5', 'جميع الشرائع التي شرعها الله تعالى للناس تهدف أحكامها إلى مقاصد مردّها إلى:', 'من الذي شرع هذه الأحكام؟', 'مقاصد الشرائع مردّها إلى المشرّع الحكيم وهو الله تعالى.', 1, 18, 2, false, ''),
('rv8.u1.l5.2c', 'u1-l5', 'الهدف من مقاصد الشريعة الإسلامية:', 'الشريعة تراعي مصالح الإنسان في حياتيه.', 'الهدف من مقاصد الشريعة الإسلامية تحقيق السعادة للإنسان في الدنيا والآخرة.', 1, 18, 3, false, ''),
('rv8.u1.l5.2d', 'u1-l5', 'تتنوع المقاصد من حيث اعتبار المصالح التي جاءت الشريعة لحفظها إلى:', 'ثلاثة أقسام مرتبة بحسب شدة الحاجة إليها.', 'تنقسم المقاصد من حيث اعتبار المصالح إلى: الضروريات، والحاجيات، والتحسينات.', 2, 18, 4, false, ''),
('rv8.u1.l5.3a', 'u1-l5', 'المقاصد التي تتوقف عليها حياة الناس الدينية والدنيوية، وإذا فُقدت اختلّت الحياة وشاع الفساد، هي:', 'لا تستقيم الحياة بدونها أبدًا.', 'الضروريات: هي المقاصد التي تتوقف عليها حياة الناس الدينية والدنيوية، ومثالها: الدين، والنفس، والعقل، والمال، والعرض.', 2, 18, 5, false, ''),
('rv8.u1.l5.3b', 'u1-l5', 'قَصر الصلاة الرباعية، والفطر في رمضان للمريض والمسافر، من أمثلة:', 'هذه الأحكام ترفع الحرج والمشقة عن الناس.', 'الحاجيات: هي المقاصد التي يحتاج إليها الناس للتيسير عليهم ورفع الحرج والمشقة، ومن أمثلتها قصر الصلاة الرباعية والفطر للمريض والمسافر.', 2, 18, 6, false, ''),
('rv8.u1.l5.3c', 'u1-l5', 'الأخذ بمحاسن العادات ومكارم الأخلاق، مثل التزيّن باللباس وإظهار حسن الهيئة، من أمثلة:', 'هذه أمور تجمّل تصرفات الناس وتكمّلها.', 'التحسينات: هي المقاصد التي تتحسن بها أحوال الناس وتجمل بها تصرفاتهم وتكتمل.', 2, 18, 7, false, ''),
('rv8.u1.l5.4', 'u1-l5', 'أيٌّ مما يأتي ليس من المقاصد الضرورية التي جاءت الشريعة لحفظها؟', 'المقاصد الضرورية خمسة: الدين، والنفس، والعقل، والعرض، والمال.', 'المقاصد الضرورية: حفظ الدين، وحفظ النفس، وحفظ العقل، وحفظ العرض، وحفظ المال؛ فكل ما يتضمن حفظها فهو مصلحة، وكل ما يفوّتها فهو مفسدة.', 1, 19, 8, false, ''),
('rv8.u1.l5.5', 'u1-l5', 'لماذا قُدِّم حفظ الدين على المقاصد الأخرى؟', 'تذكّر قوله تعالى: ﴿وما خلقت الجن والإنس إلا ليعبدون﴾.', 'قُدّم حفظ الدين لأهميته في حياة الإنسان؛ فالغاية التي خلق الله الخلق لأجلها هي عبادته، ولأن ضياع الدين ضياع لبقية المقاصد وخراب للدنيا بأسرها، وقد شبّه الله الدين بالحياة للأمم.', 2, 19, 9, false, ''),
('rv8.u1.l5.7a', 'u1-l5', 'استنتج ضابط حفظ الدين من قوله تعالى: ﴿فأقم وجهك للدين حنيفا﴾:', 'الدين الحنيف: العقيدة الصحيحة المائلة عن الشرك.', 'الآية تدل على ضابط اتباع العقيدة السليمة.', 2, 19, 10, false, ''),
('rv8.u1.l5.7b', 'u1-l5', 'استنتج ضابط حفظ الدين من قوله تعالى: ﴿ومن أحسن قولا ممن دعا إلى الله وعمل صالحا﴾:', 'انظر إلى عبارة «دعا إلى الله».', 'الآية تدل على ضابط الدعوة إلى الله تعالى.', 1, 19, 11, false, ''),
('rv8.u1.l5.7c', 'u1-l5', 'استنتج ضابط حفظ الدين من حديث: «بُني الإسلام على خمس: شهادة أن لا إله إلا الله وأن محمدًا عبده ورسوله، وإقام الصلاة، وإيتاء الزكاة، وصوم رمضان، وحج البيت»:', 'الحديث يعدّد أركان الإسلام من صلاة وزكاة وصوم وحج.', 'الحديث يدل على ضابط إقامة العبادات المفروضة.', 1, 20, 12, false, ''),
('rv8.u1.l5.7d', 'u1-l5', 'استنتج ضابط حفظ الدين من قوله تعالى: ﴿ومن يرتدد منكم عن دينه فيمت وهو كافر فأولئك حبطت أعمالهم في الدنيا والآخرة﴾:', 'الآية تتحدث عن الارتداد عن الدين.', 'الآية تدل على ضابط سنّ العقوبات للمرتد عن الإسلام.', 2, 19, 13, false, ''),
('rv8.u1.l5.9a', 'u1-l5', 'لماذا تُعدّ النفس البشرية محترمة لذاتها؟', 'فكّر في خالق النفس.', 'النفس محترمة لذاتها لأن الذي خلقها هو الله تعالى، وقد أكد على عظمتها فأقسم بها ﴿ونفس وما سواها﴾، وعدّ التعدي عليها جرمًا عظيمًا.', 2, 20, 14, false, ''),
('rv8.u1.l5.9b', 'u1-l5', 'ما الذي يدل عليه قوله تعالى: ﴿من قتل نفسا بغير نفس أو فساد في الأرض فكأنما قتل الناس جميعا﴾؟', 'قتل نفس واحدة شُبّه بقتل الناس جميعًا.', 'عدّ الله التعدي على النفس جرمًا عظيمًا، فمن قتل نفسًا بغير حق فكأنما قتل الناس جميعًا.', 1, 20, 15, false, ''),
('rv8.u1.l5.10a', 'u1-l5', 'استنتج ضابط حفظ النفس من قوله تعالى: ﴿يا أيها الذين آمنوا كلوا من طيبات ما رزقناكم﴾:', 'الآية تأمر بالأكل.', 'الآية تدل على أن الإسلام أوجب تناول الطعام والشراب حفظًا للنفس.', 1, 20, 16, false, ''),
('rv8.u1.l5.10b', 'u1-l5', 'استنتج ضابط حفظ النفس من قوله تعالى: ﴿ولكم في القصاص حياة يا أولي الألباب﴾:', 'انظر إلى كلمة «القصاص».', 'الآية تدل على ضابط عقوبة القصاص للقاتل حفظًا للنفس.', 1, 20, 17, false, ''),
('rv8.u1.l5.10c', 'u1-l5', 'استنتج ضابط حفظ النفس من قول النبي ﷺ: «تداووا عباد الله»:', 'التداوي يكون من ...', 'الحديث يدل على ضابط الوقاية والتداوي من الأمراض.', 1, 20, 18, false, ''),
('rv8.u1.l5.10d', 'u1-l5', 'استنتج ضابط حفظ النفس من قوله تعالى: ﴿ولا تلقوا بأيديكم إلى التهلكة﴾:', 'التهلكة: الهلاك.', 'الآية تدل على ضابط تجنب كل ما يؤدي بالنفس للهلاك.', 1, 20, 19, false, ''),
('rv8.u1.l5.14a', 'u1-l5', 'مجموعة من الشباب يقفون على حافة صخور البحر وقت ارتفاع الأمواج. قيّم تصرّفهم في ضوء مقصد حفظ النفس:', 'تذكّر: ﴿ولا تلقوا بأيديكم إلى التهلكة﴾.', 'عليهم الابتعاد عن الأماكن الخطرة وعدم تعريض أنفسهم للتهلكة، وعلى ولي الأمر مراقبتهم وتوجيههم، فحفظ النفس من مقاصد الشريعة.', 1, 21, 20, false, ''),
('rv8.u1.l5.14b', 'u1-l5', 'سائق يغترّ بقوة سيارته فيعبر الأودية وقت جريانها. قيّم تصرّفه:', 'قوة السيارة لا تمنع الخطر.', 'عليه ألا يغتر بقوة سيارته، والتهور بعبور الأودية فيه تعريض للنفس للتهلكة.', 1, 21, 21, false, ''),
('rv8.u1.l5.14c', 'u1-l5', 'سائقة تنشغل بالتصوير أثناء القيادة. قيّم تصرّفها:', 'الانشغال أثناء القيادة يضر السائق ومن حوله.', 'عليها التركيز في القيادة وعدم اللهو أو الانشغال بأمر آخر كالتصوير، فهي بذلك تعرّض نفسها والآخرين للخطر.', 1, 21, 22, false, ''),
('rv8.u1.l6.1', 'u1-l6', 'ما سبب إجلاء النبي ﷺ يهود بني النضير؟', 'يرتبط السبب بنقض العهود.', 'أجلى النبي ﷺ يهود بني النضير بسبب خيانتهم وغدرهم.', 1, 22, 1, false, ''),
('rv8.u1.l6.2', 'u1-l6', 'ما سبب غزوة الأحزاب؟', 'بدأ الأمر بعد إجلاء بني النضير من المدينة.', 'بعد إجلاء بني النضير توجّه وفد منهم برئاسة حيي بن أخطب إلى قريش وغطفان وبعض القبائل يدعونهم إلى قتال المسلمين ويعدونهم بالنصر، ووعدوا غطفان بثلث ثمار خيبر.', 2, 22, 2, false, ''),
('rv8.u1.l6.3', 'u1-l6', 'في أي سنة حدثت غزوة الأحزاب؟', 'حدثت بعد إجلاء بني النضير بفترة قصيرة.', 'حدثت غزوة الأحزاب في السنة الخامسة للهجرة.', 1, 22, 3, false, ''),
('rv8.u1.l6.3b', 'u1-l6', 'من الذي ذهب لتحريض قريش وغطفان على قتال المسلمين؟', 'كان رئيس وفد يهود بني النضير.', 'ذهب حيي بن أخطب، رئيس وفد بني النضير، لتحريض قريش وغطفان على قتال المسلمين.', 1, 22, 4, false, ''),
('rv8.u1.l6.4', 'u1-l6', 'لماذا استجابت غطفان لدعوة يهود بني النضير إلى قتال المسلمين؟', 'الإغراء كان ماديًّا.', 'استجابت غطفان لأن يهود بني النضير وعدوهم بثلث ثمار خيبر.', 1, 22, 5, false, ''),
('rv8.u1.l6.5', 'u1-l6', 'لماذا قبلت قريش دعوة يهود بني النضير لقتال المسلمين؟', 'قريش أرادت استعادة سمعتها بعد أن مرّغها المسلمون.', 'أيقنت قريش بعد مصادمات كثيرة أنها لا طاقة لها على قتال المسلمين واستئصال الإسلام، وقد مرّغ المسلمون سمعتها، فوجدت في التحزب فرصة سانحة لرد اعتبارها.', 2, 22, 6, false, ''),
('rv8.u1.l6.6', 'u1-l6', 'ما موقف الرسول ﷺ لما بلغه خبر تجمّع قريش وغطفان وبني النضير والقبائل المجاورة؟', 'كان النبي ﷺ يأخذ بالشورى في أمور الحرب.', 'استشار النبي ﷺ أصحابه في القتال خارج المدينة أم داخلها، فرجح رأي القتال داخل المدينة.', 2, 22, 7, false, ''),
('rv8.u1.l6.7', 'u1-l6', 'فيمَ يتمثل الرأي الجديد في التخطيط العسكري الذي أشار به سلمان الفارسي على النبي ﷺ؟', 'سُمّيت الغزوة باسمٍ آخر نسبةً إلى هذا الرأي.', 'أشار سلمان الفارسي بحفر خندق يحتمي المسلمون خلفه.', 1, 22, 8, false, ''),
('rv8.u1.l6.9', 'u1-l6', 'ما دلالة قبول النبي ﷺ مقترح سلمان الفارسي بحفر الخندق؟', 'سلمان صاحب خبرة من بلاد أخرى.', 'يدل قبوله ﷺ للمقترح على أخذه بالمشورة، والترحيب بالمبادرات، والاستفادة من تجارب الآخرين وخبراتهم.', 2, 22, 9, false, ''),
('rv8.u1.l6.10', 'u1-l6', 'لماذا أمر النبي ﷺ بحفر الخندق في الجهة الشمالية من المدينة المنورة؟', 'فكّر في طبيعة الجهات الأخرى المحيطة بالمدينة.', 'الجهة الشمالية هي الجهة الوحيدة المكشوفة التي يُتوقع أن تدخل منها جيوش الأحزاب، أما باقي الجهات فمحاطة بالجبال.', 2, 23, 10, false, ''),
('rv8.u1.l6.11', 'u1-l6', 'كيف تم تحديد مكان حفر الخندق؟', 'اختيار المكان كان قائمًا على معرفة طبيعة الأرض.', 'تم تحديد مكان الخندق من خلال دراسة النبي ﷺ لجغرافية المدينة المنورة.', 1, 23, 11, false, ''),
('rv8.u1.l6.12', 'u1-l6', '«كان لروح الجماعة والتعاون ومشاركة القائد أثر في نجاح حفر الخندق». أين تجد ذلك في أحداث الغزوة؟', 'تذكّر دور القائد ﷺ أثناء الحفر.', 'قسّم النبي ﷺ العمل بين المهاجرين والأنصار عشرات، وحدد لكل مجموعة مسافة حفر، وشارك الحفر مع صحابته، فكان يفتت ما عجزوا عنه من الصخور، ويبشرهم بالنصر وينشد معهم.', 2, 23, 12, false, ''),
('rv8.u1.l6.13a', 'u1-l6', 'لماذا سُمّيت هذه الغزوة بغزوة الأحزاب؟', 'الاسم يصف حال العدو المجتمع.', 'سُميت بغزوة الأحزاب لأن الأحزاب من قريش وغطفان وبني النضير وبعض القبائل المجاورة تألّبت وتحزّبت لقتال المسلمين.', 1, 23, 13, false, ''),
('rv8.u1.l6.13b', 'u1-l6', 'لماذا سُمّيت غزوة الأحزاب بغزوة الخندق؟', 'الاسم مأخوذ من خطة الدفاع.', 'سُميت بغزوة الخندق لأن المسلمين حفروا خندقًا لصد العدوان.', 1, 23, 14, false, ''),
('rv8.u1.l6.14', 'u1-l6', 'ما هدف المنافقين من انسحابهم بدعوى أن بيوتهم تحصيناتها ضعيفة؟', 'كان عذرهم غير صادق.', 'هدف المنافقين من انسحابهم التثبيط عن القتال والتشكيك في النصر.', 1, 23, 15, false, ''),
('rv8.u1.l6.15', 'u1-l6', 'من قبائل اليهود التي أبقاها الرسول ﷺ في المدينة المنورة:', 'هي القبيلة التي نقضت العهد لاحقًا في هذه الغزوة.', 'من قبائل اليهود التي أبقاها الرسول ﷺ في المدينة: يهود بني قريظة.', 2, 23, 16, false, ''),
('rv8.u1.l6.16', 'u1-l6', 'ما موقف الأحزاب عندما وصلوا إلى الجهة الشمالية من المدينة المنورة؟', 'الخندق كان أمرًا جديدًا لم تعرفه العرب في حروبها.', 'فوجئ الأحزاب بالخندق فلم يكونوا يتوقعونه، ووقعوا في ربكة وحيرة، وفشلت خطتهم، وأخذوا يحومون حوله بحثًا عن نقطة ضعف لاختراقه فلم يجدوا.', 2, 23, 17, false, ''),
('rv8.u1.l6.17', 'u1-l6', 'ماذا فعل المسلمون عندما وصل الأحزاب إلى الخندق؟', 'كان هدف المسلمين منع الأحزاب من عبور الخندق.', 'أخذ المسلمون يرشقون الأحزاب بالنبل ويرمونهم بالحجارة حتى لا يقتحموا الخندق.', 1, 24, 18, false, ''),
('rv8.u1.l6.18', 'u1-l6', 'ما سبب نقض يهود بني قريظة العهد الذي بينهم وبين الرسول ﷺ؟', 'الشخص نفسه الذي حرّض قريشًا وغطفان.', 'أغراهم زعيم بني النضير حيي بن أخطب بالانضمام إلى جيوش الأحزاب، فأخذ يلحّ عليهم ويصوّر لهم أنها نهاية الإسلام والمسلمين.', 2, 24, 19, false, ''),
('rv8.u1.l6.19', 'u1-l6', 'ماذا كان موقف المسلمين عندما علموا بنقض بني قريظة العهد؟', 'وصف القرآن شدة الخوف في تلك اللحظة.', 'عندما وصل الخبر زاغت الأبصار وبلغت القلوب الحناجر.', 2, 24, 20, false, ''),
('rv8.u1.l6.20', 'u1-l6', 'ما موقف الرسول ﷺ بعد نقض بني قريظة العهد؟', 'تذكّر شخصيتين من الأنصار استشارهما النبي ﷺ.', 'فكّر الرسول ﷺ باستمالة قبائل غطفان بإعطائهم ثلث ثمار المدينة على أن يتراجعوا فتضعف قوة الأحزاب، فاستشار زعماء الأنصار فأشاروا بغير ذلك، فأخذ ﷺ بمشورتهم وتراجع عن الأمر.', 2, 24, 21, false, ''),
('rv8.u1.l6.21a', 'u1-l6', 'بمَ وجّه النبي ﷺ الصحابي نُعيم بن مسعود الغطفاني بعد أن أعلن إسلامه سرًّا يوم الأحزاب؟', 'كان إسلامه مخفيًّا عن الأحزاب، فكيف يُستفاد من ذلك؟', 'جاء نُعيم إلى النبي ﷺ يوم الأحزاب سرًّا وأعلن إسلامه، فوجهه النبي ﷺ إلى جيوش الأحزاب ليوقع بينهم.', 2, 24, 22, false, ''),
('rv8.u1.l6.21b', 'u1-l6', 'بمَ أشار نُعيم بن مسعود على يهود بني قريظة؟', 'حذّرهم من انتقام المسلمين إذا انسحبت الأحزاب.', 'ذهب إليهم وكان صديقًا لهم، فحذّرهم من انتقام المسلمين إذا انسحبت جيوش الأحزاب، وأشار عليهم أن يأخذوا رهائن من الأحزاب ضمانًا للالتزام بالعهد.', 2, 24, 23, false, ''),
('rv8.u1.l6.21c', 'u1-l6', 'عندما قرّر الأحزاب الهجوم على المدينة وأرسلوا إلى بني قريظة، لماذا رفض بنو قريظة؟', 'يرتبط السبب بيومٍ له قدسية عند اليهود.', 'رفض بنو قريظة لأن ذلك كان يوم السبت وهو يوم مقدس عندهم، وطلبوا من الأحزاب رهائن شرطًا لمشاركتهم، فتأكد للأحزاب صدق ما قاله نُعيم.', 2, 24, 24, false, ''),
('rv8.u1.l6.21d', 'u1-l6', 'ما نتيجة الحيلة التي قام بها نُعيم بن مسعود بين الأحزاب وبني قريظة؟', 'كان هدف الحيلة التفريق بين الحلفاء.', 'أدت حيلة نُعيم إلى تصدّع تحالف الأحزاب وبني قريظة وسوء العلاقة بينهم.', 1, 24, 25, false, ''),
('rv8.u1.l6.22', 'u1-l6', 'أيٌّ مما يأتي من الأمور التي حدثت وأثّرت في تجمّع الأحزاب؟', 'المقصود ما أضعف تجمّع الأحزاب وفرّقه.', 'من الأمور التي أثّرت في تجمع الأحزاب: تفاجؤهم بالخندق، وقيام نُعيم بن مسعود بالتخذيل والتفريق بينهم، وإرسال الله ريحًا اقتلعت خيامهم وكفأت قدورهم وأطفأت نارهم، ونزول الملائكة لنصرة النبي ﷺ والمؤمنين.', 2, 25, 26, false, ''),
('rv8.u1.l6.23', 'u1-l6', 'في قوله تعالى: ﴿إذ جاءتكم جنود فأرسلنا عليهم ريحا وجنودا لم تروها﴾، ما المقصود بالجنود التي لم يروها؟', 'جنودٌ لا يراها البشر.', 'من أسباب انتصار المسلمين: إرسال الله تعالى الريح، ونزول الملائكة لنصرة النبي ﷺ والمؤمنين، وهم الجنود الذين لم يروهم.', 1, 25, 27, false, ''),
('rv8.u1.l6.24', 'u1-l6', 'انتصر المسلمون في غزوة الأحزاب دون حرب. أيٌّ مما يأتي من المكاسب التي غنموها من هذا الانتصار؟', 'المكاسب هنا معنوية ومادية لصالح المسلمين.', 'ارتفعت معنويات المسلمين، وزادت ثقتهم بأنفسهم، وبرزت هيبتهم بين القبائل وقدرتهم على إدارة الأزمات، وأعطوا درسًا لقريش والأحزاب أنهم دولة وقوة محصنة لا يُستهان بها.', 2, 25, 28, false, ''),
('rv8.u1.l6.25', 'u1-l6', 'ما دلالة قوله ﷺ بعد غزوة الأحزاب: «الآن نغزوهم ولا يغزوننا، نحن نسير إليهم»؟', 'قارن بين حال المسلمين قبل الغزوة وبعدها.', 'تدل على أن هذه الغزوة حولت الغزو عند المسلمين من مرحلة الدفاع إلى مرحلة الهجوم.', 2, 25, 29, false, ''),
('rv8.u1.l6.26a', 'u1-l6', 'اختار النبي ﷺ والصحابة التحصّن في المدينة؛ لأن موقف المدافع المتحصّن أقوى من موقف:', 'عكس المدافع.', 'موقف المدافع المتحصن أقوى من موقف المهاجم، لذلك اختار النبي ﷺ التحصن في المدينة.', 1, 25, 30, false, ''),
('rv8.u1.l6.26b', 'u1-l6', 'عنصر المفاجأة في غزوة الأحزاب تمثّل في:', 'شيءٌ لم تعرفه العرب في حروبها من قبل.', 'تمثّل عنصر المفاجأة في حفر الخندق.', 1, 25, 31, false, ''),
('rv8.u1.l6.26t-1', 'u1-l6', 'كم كان عدد المسلمين وعدد الأحزاب في غزوة الأحزاب؟', 'كان عدد الأحزاب أكثر من ثلاثة أضعاف عدد المسلمين.', 'كان عدد المسلمين ثلاثة آلاف مقاتل، وعدد الأحزاب عشرة آلاف مقاتل.', 2, 26, 32, false, ''),
('rv8.u1.l6.26t-2', 'u1-l6', 'من كان قائد الأحزاب في غزوة الأحزاب؟', 'كان من زعماء قريش آنذاك.', 'كان قائد الأحزاب أبا سفيان.', 2, 26, 33, false, ''),
('rv8.u1.l6.26t-3', 'u1-l6', 'ما دافع المسلمين في غزوة الأحزاب؟', 'كان المسلمون في موقف الدفاع.', 'دافع المسلمين: حماية المدينة والدفاع عن دينهم وأنفسهم، أما الأحزاب فدافعهم الحقد والكراهية والرغبة في القضاء على الإسلام.', 1, 26, 34, false, ''),
('rv8.u1.l6.27a', 'u1-l6', 'ما موقف المؤمنين لما رأوا الأحزاب كما في قوله تعالى: ﴿قالوا هذا ما وعدنا الله ورسوله وصدق الله ورسوله وما زادهم إلا إيمانا وتسليما﴾؟', 'الآية تقول: «وما زادهم إلا إيمانًا».', 'كان موقف المؤمنين التفاؤل بنصر الله تعالى، وتسليم الأمر لله، والثبات في وجه العدو، والأخذ بأسباب النصر.', 1, 26, 35, false, ''),
('rv8.u1.l6.27b', 'u1-l6', 'ما موقف المنافقين يوم الأحزاب كما في قوله تعالى: ﴿ما وعدنا الله ورسوله إلا غرورا ... يقولون إن بيوتنا عورة﴾؟', 'قالوا: «إن بيوتنا عورة» وما هي بعورة.', 'شكّك المنافقون في نصر الله ووعده، وقاموا بتثبيط المسلمين عن القتال، واستأذنوا الرسول ﷺ في الرجوع بعلة أن بيوتهم غير حصينة.', 1, 26, 36, false, ''),
('rv8.u1.l6.29a', 'u1-l6', 'أين يظهر درس «الكفر ملّة واحدة» في أحداث غزوة الأحزاب؟', 'الدرس يتحدث عن اجتماع أعداء الإسلام رغم اختلافهم.', 'يظهر درس «الكفر ملة واحدة» في اجتماع قبائل العرب المشركة مع اليهود على حرب المسلمين.', 2, 26, 37, false, ''),
('rv8.u1.l6.29b', 'u1-l6', 'أين يظهر درس «الحرب خدعة» في أحداث غزوة الأحزاب؟', 'تذكّر الحيلة التي فرّقت بين الحلفاء.', 'يظهر درس «الحرب خدعة» في دور نُعيم بن مسعود رضي الله عنه لتخذيل الأحزاب وزعزعة صفوفهم.', 2, 27, 38, false, ''),
('rv8.u1.l6.29c', 'u1-l6', 'أين يظهر درس «المشاركة الفاعلة للقائد أقوى حافز للتفاني في العمل» في غزوة الأحزاب؟', 'ماذا فعل القائد ﷺ بنفسه أثناء العمل؟', 'نزل النبي ﷺ مع أصحابه في الخندق وشاركهم في الحفر، وأعطاهم الدافعية والأمل في تحقيق النصر بالقول والعمل.', 1, 27, 39, false, ''),
('rv8.u1.l6.31', 'u1-l6', 'لماذا تُعدّ غزوة الأحزاب الغزوة الأكثر خطورة في تاريخ السيرة النبوية؟', 'فكّر في حجم التحالف وهدفه.', 'تعد الأكثر خطورة بسبب تحالف بعض قبائل الجزيرة العربية بقيادة قريش مع اليهود لحرب المسلمين وإنهاء وجودهم ودولتهم.', 2, 27, 40, false, ''),
('rv8.u1.l6.32', 'u1-l6', 'يذكّرنا مشهد مشاركة النبي ﷺ في حفر الخندق بمشاركته في بناء المسجد النبوي. تبرز أهمية حفر الخندق في:', 'بناء المسجد لحفظ الدين، وحفر الخندق لحماية ...', 'تبرز أهمية بناء المسجد النبوي في حفظ الدين، وتبرز أهمية حفر الخندق في حفظ الدولة، وفي كليهما حفظ للإسلام.', 2, 27, 41, false, ''),
('rv8.u1.l6.33', 'u1-l6', 'شاور الرسول ﷺ سعد بن عبادة وسعد بن معاذ في إعطاء غطفان ثلث ثمار المدينة، فأشارا بعدم ذلك وأخذ بقولهما. ما الخُلُق البارز في هذا الموقف؟', 'القائد ﷺ سأل أصحابه وقبل رأيهم.', 'من الأخلاقيات البارزة: المشورة، والاستماع للرأي المخالف، والعزة والرفعة وعدم التنازل عن الحقوق.', 1, 27, 42, false, ''),
('rv8.u1.l7.1', 'u1-l7', 'مِمّ تكوّن جيش سيدنا سليمان عليه السلام؟', 'كان جيشه عجيبًا يضم مخلوقات مختلفة، ومنها الهدهد.', 'تكوّن جيش سليمان عليه السلام من الجن والإنس والطير.', 1, 28, 1, false, ''),
('rv8.u1.l7.2', 'u1-l7', 'ما دلالة افتقاد سيدنا سليمان عليه السلام للهدهد؟', 'تفقّد القائد لجنديٍّ صغير يدل على شيء.', 'يدل على اهتمامه بجميع جنوده من إنس وجن وطير، وعلى أن الهدهد لم يكن طيرًا كبقية الطيور وإلا لما افتقده.', 2, 28, 2, false, ''),
('rv8.u1.l7.3', 'u1-l7', 'بمَ توعّد سيدنا سليمان عليه السلام الهدهد؟', 'التوعّد كان مشروطًا بشيء.', 'توعّده بالعذاب الأليم والذبح إذا لم يأتِ بعذر مقبول يبرر فيه غيابه.', 1, 28, 3, false, ''),
('rv8.u1.l7.4', 'u1-l7', 'ما العذر الذي ساقه الهدهد لغيابه؟', 'جاء الهدهد بنبأ يقين عن قوم في اليمن.', 'أخبر الهدهد أنه كان في رحلة وجد فيها قوم سبأ يسجدون للشمس من دون الله تعالى، ولهم ملكة على عرش عظيم.', 1, 28, 4, false, ''),
('rv8.u1.l7.5', 'u1-l7', 'ما موقف سيدنا سليمان عليه السلام من النبأ الذي ساقه الهدهد؟', 'تذكّر عنوان الدرس: الأناة.', 'تريّث سليمان عليه السلام حتى يتحقق من صحة الخبر وصدق الهدهد، فكتب رسالة إلى ملكة سبأ، وأمر الهدهد أن يلقي بالرسالة إليها، وينتظر ليرى ماذا ستفعل هي وقومها.', 2, 28, 5, false, ''),
('rv8.u1.l7.6', 'u1-l7', 'ما الصفة التي برزت في تعامل سليمان عليه السلام مع الهدهد، إذ لم يقضِ في شأنه حتى يسمع حجته؟', 'سمع حجته قبل الحكم عليه.', 'برزت الأناة في إصدار الأحكام؛ فلم يقضِ في شأن الهدهد قبل أن يسمع حجته ويتبين عذره، والتدرج في إصدار العقوبة حتى وصل إلى العفو الشامل لما أتى الهدهد بحجة مقنعة.', 1, 28, 6, false, ''),
('rv8.u1.l7.7', 'u1-l7', 'ما المقصود بالأناة؟', 'الأناة وسطٌ بين التسرّع والتباطؤ.', 'الأناة: التريّث وعدم العجلة في اتخاذ القرار.', 1, 28, 7, false, ''),
('rv8.u1.l7.8', 'u1-l7', 'الأناة خصلة عظيمة يتصف بها:', 'الأناة دليل على رجاحة العقل.', 'الأناة خصلة عظيمة يتصف بها أصحاب العقول الرزينة وصاحب الحكمة في التصرف.', 1, 28, 8, false, ''),
('rv8.u1.l7.9', 'u1-l7', 'أيٌّ مما يأتي من آثار غياب الأناة في حياة المسلم؟', 'غياب الأناة يعني حضور ضدّها.', 'من آثار غياب الأناة: غياب الإرادة القوية القادرة على ضبط النفس، وعدم القدرة في التحكم بالأمور، والعجز في وضع الأشياء في مواضعها الصحيحة، والتسرع في إصدار الأحكام.', 2, 28, 9, false, ''),
('rv8.u1.l7.10a', 'u1-l7', 'كيف دلّ قوله تعالى: ﴿لا تحرك به لسانك لتعجل به إن علينا جمعه وقرآنه﴾ على أمر الإسلام بالأناة؟', 'الآية تنهى عن العجلة في ترديد الوحي.', 'مدح الله تعالى الأناة وأمر بها نبيه ﷺ عند تلقي الوحي، تطمينًا له وتوجيهًا.', 2, 29, 10, false, ''),
('rv8.u1.l7.10b', 'u1-l7', 'قال النبي ﷺ لأشجّ عبد القيس: «إن فيك خصلتين يحبهما الله». ما هاتان الخصلتان؟', 'إحداهما موضوع هذا الدرس.', 'قال النبي ﷺ لأشج عبد القيس: «إن فيك خصلتين يحبهما الله: الحلم والأناة».', 1, 29, 11, false, ''),
('rv8.u1.l7.11', 'u1-l7', 'هل للأناة مدة زمنية ثابتة؟', 'الأناة مرتبطة بالموقف لا بالساعة.', 'ليس للأناة مدة زمنية ثابتة؛ لأنها مرتبطة بتوقيتها، فمتى استدعت حاجتها طُلب من المسلم التخلّق بها.', 2, 29, 12, false, ''),
('rv8.u1.l7.12a', 'u1-l7', 'علامَ تدلّ العجلة في موضع الأناة؟', 'المستعجل لا يصبر.', 'العجلة في موضع الأناة تدل على قلة الصبر ونقص الحكمة.', 2, 29, 13, false, ''),
('rv8.u1.l7.12b', 'u1-l7', 'علامَ يدلّ التباطؤ في موضع الأناة؟', 'التباطؤ غير الأناة.', 'التباطؤ يدل على ضعف الهمة والإخلاد إلى الراحة والكسل.', 2, 29, 14, false, ''),
('rv8.u1.l7.13', 'u1-l7', 'هدف الأناة:', 'المتأني ينظر إلى ما سيحدث بعد قراره.', 'هدف الأناة: الاستبصار والتأمل والنظر في العواقب.', 1, 29, 15, false, ''),
('rv8.u1.l7.14', 'u1-l7', 'ما فائدة الأناة في الأمور؟', 'المتعجّل كثيرًا ما يندم.', 'من فوائد الأناة أن يأمن الإنسان الندامة في حالة التعجل، ولا يكون ذلك إلا بتدبير الأمور: فإن كانت رشدًا وصوابًا فليمضِ، وإن كانت غيًّا وظنًّا فليقف حتى يتضح له الحق.', 2, 29, 16, false, ''),
('rv8.u1.l7.15', 'u1-l7', 'أيٌّ مما يأتي من صفات من لم يتّصف بالتأنّي؟', 'من لم يتأنَّ يحكم قبل أن يتبيّن.', 'من لم يتصف بالتأني: يشعر بالندم عند معرفة الخبر الصحيح، وتصدر منه ردود أفعال مؤذية، وسوء الظن، والمسارعة في الاتهام. أما المتأني فيأمن العواقب ويحافظ على العلاقات ويحصل على البينة.', 2, 29, 17, false, ''),
('rv8.u1.l7.16', 'u1-l7', 'أيٌّ مما يأتي من الوسائل التي تعين الإنسان على التحلّي بصفة الأناة؟', 'كان النبي ﷺ يدعو: «واهدني لأحسن الأخلاق».', 'من دور الإنسان في التحلي بالأناة: تدريب النفس، والأخذ بالأسباب كمصاحبة أهل الصلاح، والصبر، وطلب الهداية من الله تعالى.', 1, 30, 18, false, ''),
('rv8.u1.l7.17', 'u1-l7', '«التأني مطلوب في كل أمور الدنيا إلا ما تعلّق بالآخرة». ما الحكم على هذه العبارة؟', 'تذكّر قوله تعالى: ﴿أولئك يسارعون في الخيرات﴾.', 'العبارة صحيحة؛ فكل أمور الدنيا مطلوب فيها التأني إلا ما يتعلق بالآخرة، فلا بد فيها من المنافسة والمسابقة والمسارعة، قال رسول الله ﷺ: «التؤدة في كل شيء إلا في عمل الآخرة».', 2, 30, 19, false, ''),
('rv8.u1.l7.19a', 'u1-l7', 'استنتج الموضع الذي ينبغي للمسلم التأني فيه من قوله تعالى: ﴿وعباد الرحمن الذين يمشون على الأرض هونا﴾:', 'انظر إلى الفعل «يمشون».', 'الآية تدل على التأني في المشي.', 1, 30, 20, false, ''),
('rv8.u1.l7.19b', 'u1-l7', 'استنتج الموضع الذي ينبغي للمسلم التأني فيه من قول النبي ﷺ: «كفى بالمرء كذبًا أن يحدّث بكل ما سمع»:', 'الحديث يتحدث عمّن يحدّث بكل ما يسمع.', 'الحديث يدل على التأني في نقل الخبر.', 1, 30, 21, false, ''),
('rv8.u1.l7.19c', 'u1-l7', 'استنتج الموضع الذي ينبغي للمسلم التأني فيه من قول النبي ﷺ: «يُستجاب لأحدكم ما لم يعجل، يقول: دعوت فلم يُستجب لي»:', 'الحديث عن الاستجابة.', 'الحديث يدل على التأني في الدعاء.', 1, 30, 22, false, ''),
('rv8.u1.l7.19d', 'u1-l7', 'عن عائشة رضي الله عنها: «إن رسول الله لم يكن يسرد الحديث كسردكم». ما الموضع الذي يُتأنّى فيه؟', '«يسرد الحديث» أي يتابعه بسرعة.', 'يدل الحديث على التأني في الحديث (الكلام).', 1, 30, 23, false, ''),
('rv8.u1.l7.19e', 'u1-l7', 'قال النبي ﷺ لرجل صلّى بسرعة: «ارجع فصلِّ فإنك لم تصلِّ». ما الموضع الذي يُتأنّى فيه؟', 'الحديث عن الصلاة.', 'يدل الحديث على التأني في أداء العبادات.', 1, 30, 24, false, ''),
('rv8.u1.l7.21a', 'u1-l7', 'الأناة خصلة تُبعد صاحبها عن التسرّع، لكنها لا تعني:', 'هناك فرق بين التأني وتأخير الأعمال بلا سبب.', 'الأناة تبعد صاحبها عن التسرع، لكنها لا تعني التباطؤ والكسل.', 1, 31, 25, false, ''),
('rv8.u1.l7.21b', 'u1-l7', 'الأناة مؤشّر على ...... عقل الإنسان.', 'صاحب الأناة صاحب عقل رزين.', 'الأناة مؤشر على رجاحة عقل الإنسان.', 1, 31, 26, false, ''),
('rv8.u1.l7.21c', 'u1-l7', 'وجّه الإسلام إلى التأني في الاختيار بين الأمور، وأرشد إلى الاستشارة و:', 'صلاة يطلب فيها المسلم من الله الخير في أمره.', 'وجه الإسلام إلى التأني في الاختيار بين الأمور، وأرشد إلى الاستشارة والاستخارة.', 1, 31, 27, false, ''),
('rv8.u1.l7.24', 'u1-l7', 'موظف يتأخر دائمًا في تسليم الأعمال الموكلة إليه بحجة الأناة. ما النصيحة المناسبة له؟', 'تذكّر الفرق بين الأناة والتباطؤ.', 'الأناة لا تعني التباطؤ، فذلك من سوء التدبير، فعليه أن يضبط أموره ولا يتباطأ.', 1, 32, 28, false, ''),
('rv8.u1.l7.25', 'u1-l7', 'قال بعض الحكماء: «إياك والعجلة؛ فإن العرب كانت تكنّيها أمّ الندامة». ما العبرة المستخلصة؟', 'لماذا سمّت العرب العجلة بهذا الاسم؟', 'العبرة: الندم عاقبة العجلة وعدم التأني.', 1, 32, 29, false, ''),
('rv8.u2.l1.info-2', 'u2-l1', 'ما مفهوم الإدغام؟', 'في الإدغام يصبح الحرفان حرفًا واحدًا.', 'الإدغام: إدخال الحرف الساكن في الحرف المتحرك بحيث يصبحان حرفًا واحدًا مشددًا.', 1, 34, 1, false, ''),
('rv8.u2.l1.info-2b', 'u2-l1', 'في الإدغام لا بدّ أن يكون:', 'الساكن هو الذي يدخل في غيره.', 'في الإدغام لا بد أن يكون الحرف الأول ساكنًا والثاني متحركًا.', 1, 34, 2, false, ''),
('rv8.u2.l1.info-3a', 'u2-l1', 'ما المخرج الذي تخرج منه غالبية حروف اللغة العربية؟', 'عضوٌ يتحرك مع أكثر الحروف عند النطق.', 'تخرج غالبية حروف اللغة العربية من اللسان.', 1, 34, 3, false, ''),
('rv8.u2.l1.info-3c1', 'u2-l1', 'ما الرابط بين الحرفين (ب، م) من حيث المخرج؟', 'انطق الحرفين ولاحظ أين يلتقي العضو المشترك.', 'الباء والميم لهما المخرج نفسه من الشفتين.', 1, 34, 4, false, ''),
('rv8.u2.l1.info-3c2', 'u2-l1', 'ما الرابط بين الحرفين (ق، ك) من حيث المخرج؟', 'الحرفان يخرجان من مؤخرة اللسان.', 'القاف والكاف يتقاربان في المخرج من أقصى اللسان.', 2, 34, 5, false, ''),
('rv8.u2.l1.info-4', 'u2-l1', 'ما مفهوم المتجانسين؟', '«متجانسان» من الجنس الواحد، أي المخرج الواحد.', 'المتجانسان: هما الحرفان اللذان اتحدا مخرجًا، واختلفا صفة.', 2, 34, 6, false, ''),
('rv8.u2.l1.info-4a', 'u2-l1', 'كم حالة لإدغام المتجانسين؟', 'عددها مذكور في الدرس بين قوسين.', 'لإدغام المتجانسين سبع حالات فقط.', 1, 34, 7, false, ''),
('rv8.u2.l1.info-4b', 'u2-l1', 'ما الموضع الوحيد الذي يُغنّ فيه إدغام المتجانسين؟', 'الغنّة صفة لازمة لحرف الميم.', 'الموضع الوحيد الذي يُغنّ فيه إدغام المتجانسين قوله تعالى: ﴿اركب معنا﴾ (إدغام الباء في الميم مع الغنة).', 3, 35, 8, false, ''),
('rv8.u2.l1.info-4c', 'u2-l1', 'لماذا يكون إدغام المتجانسين ناقصًا عندما تدخل الطاء في التاء؟', 'يبقى أثرٌ من الحرف الأول في النطق.', 'يكون الإدغام ناقصًا عندما تدخل الطاء في التاء؛ لأن الطاء أقوى من التاء، فتذهب ذات الحرف وتبقى صفته (التفخيم).', 3, 35, 9, false, ''),
('rv8.u2.l1.info-5', 'u2-l1', 'ما مفهوم المتقاربين؟', 'تقارب لا اتحاد.', 'المتقاربان: هما الحرفان اللذان تقاربا في المخرج أو الصفة، أو في أحدهما.', 2, 35, 10, false, ''),
('rv8.u2.l1.info-5b', 'u2-l1', 'لماذا يمتنع إدغام المتقاربين (اللام في الراء) في قوله تعالى: ﴿كلا بل ران على قلوبهم﴾؟', 'في المصحف علامة صغيرة فوق اللام تدل على وقفة لطيفة.', 'يمتنع الإدغام لوجود علامة السكت على اللام، والحكم هنا الإظهار.', 3, 35, 11, false, ''),
('rv8.u2.l1.1', 'u2-l1', 'ما ضابط إدغام المتجانسين والمتقاربين في المصحف الشريف؟', 'انظر كيف يُكتب الإدغام في المصحف: سكونٌ يُحذف وشدّةٌ تظهر.', 'ضابطه في المصحف: حذف علامة السكون من الحرف الأول وتشديد الحرف الثاني، ما عدا إدغام الطاء في التاء فلا يُشدَّد الحرف الثاني.', 2, 36, 12, false, ''),
('rv8.u2.l1.2', 'u2-l1', 'لماذا انتفى الإدغام في المثالين: ﴿أفتطمعون﴾ و﴿قال رب﴾؟', 'تذكّر شرط الإدغام في الحرف الأول.', 'انتفى الإدغام لأن الحرف الأول لم يأتِ ساكنًا.', 2, 36, 13, false, ''),
('rv8.u2.l1.3-1', 'u2-l1', 'صنّف الإدغام في كلمة ﴿عبدتم﴾ من قوله تعالى: ﴿ولا أنا عابد ما عبدتم﴾:', 'الدال والتاء لهما المخرج نفسه.', 'في ﴿عبدتم﴾ إدغام متجانسين؛ فالدال والتاء لهما المخرج نفسه من اللسان.', 2, 36, 14, false, ''),
('rv8.u2.l1.3-3', 'u2-l1', 'صنّف الإدغام في ﴿بل ربكم﴾ من قوله تعالى: ﴿قال بل ربكم رب السماوات والأرض﴾:', 'اللام والراء متقاربان في المخرج.', 'في ﴿بل ربكم﴾ إدغام متقاربين؛ فاللام والراء تتقاربان في المخرج من اللسان.', 2, 36, 15, false, ''),
('rv8.u2.l1.3-5', 'u2-l1', 'صنّف الإدغام في كلمة ﴿أحطت﴾ من قوله تعالى: ﴿فقال أحطت بما لم تحط به﴾:', 'الطاء والتاء من مخرج واحد.', 'في ﴿أحطت﴾ إدغام متجانسين، وهو إدغام ناقص لبقاء صفة الطاء.', 3, 36, 16, false, ''),
('rv8.u2.l1.4a', 'u2-l1', 'الحرفان المتجانسان هما:', 'حرفان يخرجان من مخرج واحد تمامًا.', 'الذال والظاء حرفان متجانسان لهما المخرج نفسه من اللسان.', 2, 36, 17, false, ''),
('rv8.u2.l1.4b', 'u2-l1', 'أحد الأمثلة الآتية فيه إدغام متقاربين:', 'ابحث عن لامٍ ساكنة بعدها راء.', 'في ﴿بل رفعه﴾ إدغام متقاربين: اللام الساكنة في الراء.', 3, 36, 18, false, ''),
('rv8.u2.l1.4c', 'u2-l1', 'حكم الحروف المتقاربة في قوله تعالى: ﴿كلا بل ران على قلوبهم﴾:', 'تذكّر علامة السكت على اللام.', 'الحكم الإظهار لوجود السكت.', 2, 36, 19, false, ''),
('rv8.u2.l2.1', 'u2-l2', 'في من نزل قوله تعالى: ﴿يا أيها الذين آمنوا إن جاءكم فاسق بنبإ فتبينوا﴾؟', 'أرسله النبي ﷺ ليجمع الصدقات من بني المصطلق.', 'نزلت الآية في الوليد بن عقبة بن أبي معيط.', 2, 37, 1, false, ''),
('rv8.u2.l2.2', 'u2-l2', 'لماذا أرسل الرسول ﷺ الوليد بن عقبة إلى بني المصطلق؟', 'مهمة مالية.', 'أرسله الرسول ﷺ ليجمع الصدقات.', 1, 37, 2, false, ''),
('rv8.u2.l2.3', 'u2-l2', 'ما سبب سوء الفهم الذي وقع فيه الوليد بن عقبة؟', 'خرج القوم لتلقيه تعظيمًا لله ولرسوله.', 'كان بينه وبينهم عداوة في الجاهلية، فلما سمع القوم بقدومه خرجوا لتلقيه تعظيمًا لله ولرسوله، فحدّثه الشيطان أنهم يريدون قتله فهابهم ورجع، وقال: إن بني المصطلق منعوا صدقاتهم وأرادوا قتلي.', 2, 37, 3, false, ''),
('rv8.u2.l2.4', 'u2-l2', 'ماذا كان ردّ فعل النبي ﷺ لما بلّغه الوليد بن عقبة خبر بني المصطلق؟', 'كاد الأمر أن يصل إلى القتال لولا نزول الآية.', 'غضب النبي ﷺ وهمّ أن يغزوهم.', 2, 37, 4, false, ''),
('rv8.u2.l2.5', 'u2-l2', 'ما الذي كان سيحلّ ببني المصطلق لو لم يتثبت النبي ﷺ من النبأ الذي ساقه الوليد بن عقبة؟', 'تذكّر ردّ فعل النبي ﷺ الأول.', 'كان من الممكن تعرّضهم للغزو من النبي ﷺ مما يهدد حياتهم.', 1, 37, 5, false, ''),
('rv8.u2.l2.6a', 'u2-l2', 'إلى ماذا يوجّه الله تعالى المؤمنين في قوله: ﴿إن جاءكم فاسق بنبإ فتبينوا﴾؟', '«فتبينوا» أي ...', 'توجه الآية المؤمنين إلى كيفية تلقي الأنباء والتعامل معها، وضرورة تمحيص الأنباء والتثبت من مصادرها.', 1, 37, 6, false, ''),
('rv8.u2.l2.6b', 'u2-l2', 'لماذا خصّ الله تعالى الفاسق في نقل الخبر الكاذب؟', 'الفاسق لا يُؤمن على الصدق.', 'خصّ الله الفاسق لأنه مظنة الكذب.', 2, 37, 7, false, ''),
('rv8.u2.l2.7a', 'u2-l2', 'في قوله تعالى: ﴿واعلموا أن فيكم رسول الله لو يطيعكم في كثير من الأمر لعنتم﴾ ذكّر الله المؤمنين بنعمة عظيمة. ما هي؟', '«أن فيكم رسول الله».', 'النعمة: وجود رسول الله ﷺ بينهم، والغرض منها اتباع أوامره والانقياد له، لما فيه الخير والرحمة للمؤمنين.', 1, 38, 8, false, ''),
('rv8.u2.l2.7b', 'u2-l2', 'ما نتيجة انصياع الرسول ﷺ لرغبات الناس وأهوائهم وترك أوامر الله تعالى كما في قوله: ﴿لعنتم﴾؟', 'العَنَت: المشقة.', 'النتيجة الإصابة بالحرج والمشقة؛ لأنه يفوتهم كثير من الأحكام الإلهية والقوانين العادلة.', 2, 38, 9, false, ''),
('rv8.u2.l2.7c', 'u2-l2', 'دلّ قوله تعالى: ﴿ولكن الله حبب إليكم الإيمان وزينه في قلوبكم﴾ على نعمة عظيمة، هي:', 'الآية تصرّح باسم النعمة.', 'دلت الآية على نعمة الإيمان، ومن آثارها: الوصول إلى الرشد، واقتفاء طريق الهداية، والاستسلام لتوجيه الله تعالى.', 1, 38, 10, false, ''),
('rv8.u2.l2.8a', 'u2-l2', 'ما عاقبة الشقاق بين المؤمنين كما في قوله تعالى: ﴿وإن طائفتان من المؤمنين اقتتلوا﴾؟', 'الآية تذكر أقصى ما يصل إليه الخلاف.', 'الشقاق بين المؤمنين يفضي إلى القتال.', 1, 38, 11, false, ''),
('rv8.u2.l2.8b', 'u2-l2', 'إلى ماذا يوجّه الله تعالى المؤمنين في قوله: ﴿وإن طائفتان من المؤمنين اقتتلوا فأصلحوا بينهما﴾؟', '«فأصلحوا».', 'يوجههم إلى قاعدة تشريعية عملية محكمة وهي الإصلاح برأب الصدع وجمع الكلمة، صيانةً للمجتمع المسلم من الخصام والتفكك.', 1, 38, 12, false, ''),
('rv8.u2.l2.8c', 'u2-l2', 'ما دلالة التعبير القرآني بـ ﴿وإن﴾ في قوله: ﴿وإن طائفتان من المؤمنين اقتتلوا﴾؟', '«إن» تُستعمل للأمر غير المتوقع أو النادر.', 'فيه إشارة إلى أنه لا ينبغي أن يقع قتال بين المؤمنين، وإن وقع فهو نادر؛ لأن الرابطة بينهم الأخوة، والأصل التسامح والتناصح.', 3, 38, 13, false, ''),
('rv8.u2.l2.9', 'u2-l2', 'ما الرابطة التي أكدت عليها الآية الكريمة: ﴿إنما المؤمنون إخوة فأصلحوا بين أخويكم﴾؟', '«إخوة».', 'أكدت الآية على رابطة الأخوة الإيمانية.', 1, 39, 14, false, ''),
('rv8.u2.l2.10a', 'u2-l2', 'أيّ القواعد التشريعية في سورة الحجرات يدل عليها قوله تعالى: ﴿إن جاءكم فاسق بنبإ فتبينوا﴾؟', '«فتبينوا».', 'تدل الآية على قاعدة التثبت من الأخبار.', 1, 39, 15, false, ''),
('rv8.u2.l2.10b', 'u2-l2', 'أيّ القواعد التشريعية في سورة الحجرات يدل عليها قوله تعالى: ﴿وأقسطوا إن الله يحب المقسطين﴾؟', 'القسط هو العدل.', 'تدل الآية على قاعدة تطبيق العدل.', 1, 39, 16, false, ''),
('rv8.u2.l2.11a', 'u2-l2', 'يشير قوله تعالى: ﴿إذ تلقونه بألسنتكم وتقولون بأفواهكم ما ليس لكم به علم وتحسبونه هينا وهو عند الله عظيم﴾ إلى عظيم ذنب نقل الأخبار:', '«ما ليس لكم به علم».', 'تشير الآية إلى عظيم ذنب نقل الأخبار الكاذبة.', 1, 39, 17, false, ''),
('rv8.u2.l2.11b', 'u2-l2', 'في قوله تعالى: ﴿فأصلحوا بينهما بالعدل﴾ يؤكد المنهج القرآني أن الصلح بين المتخاصمين يجب أن يكون:', '«بالعدل».', 'يؤكد المنهج القرآني أن الصلح بين المتخاصمين يجب أن يكون عادلًا.', 1, 39, 18, false, ''),
('rv8.u2.l2.12', 'u2-l2', 'ما دلالة الخطاب بصيغة الجمع للمؤمنين والإفراد للفاسق في قوله: ﴿يا أيها الذين آمنوا إن جاءكم فاسق بنبإ﴾؟', 'قارن بين «الذين آمنوا» (جمع) و«فاسق» (مفرد).', 'تدل على انحسار الفسوق وعدم شيوعه في المجتمع المسلم، وأن غالبية المؤمنين أخبارهم موثوقة صحيحة.', 3, 39, 19, false, ''),
('rv8.u2.l2.13', 'u2-l2', 'انتشرت رسالة تقول إن المدرسة غدًا معطّلة. ما التصرف الصحيح؟', 'تذكّر: ﴿فتبينوا﴾.', 'الأولى التأكد من صحة الخبر قبل اتخاذ القرار؛ لأن القرار ينبغي أن يُبنى على حقائق، وردة الفعل يترتب عليها عواقب قد تكون إيجابية أو سلبية.', 1, 39, 20, false, ''),
('rv8.u2.l2.15', 'u2-l2', 'طالبتان متخاصمتان، وطالبة ثالثة تقول لإحداهما: «لا تسامحيها ولا تصالحيها». قيّم هذا التصرف:', 'تذكّر: ﴿فأصلحوا بين أخويكم﴾.', 'تصرف خاطئ؛ ينبغي السعي للإصلاح بين المتخاصمين، والامتناع عن تأجيج الخصومة فيلحقها الإثم.', 1, 40, 21, false, ''),
('rv8.u2.l3.2', 'u2-l3', 'أيٌّ مما يأتي من أهم المقومات التي تُسهم في صناعة الإنسان وتكوين الشخصية القوية كما في حديث «المؤمن القوي»؟', 'الحديث يوجّه إلى الحرص والاستعانة بالله والرضا بالقدر.', 'من المقومات: التعاليم النافعة، والوصايا الجامعة، والتوكل على الله، والرضا بقدر الله تعالى، وهي تحوّل الإنسان إلى فرد نافع فاعل مؤثر.', 2, 41, 1, false, ''),
('rv8.u2.l3.3', 'u2-l3', 'المقصود بالقوة في قوله ﷺ: «المؤمن القوي خير وأحب إلى الله من المؤمن الضعيف»:', 'القوة هنا ليست نوعًا واحدًا.', 'المقصود القوة بجميع معانيها المادية والمعنوية: قوة الإيمان، والبدن، والعمل، والرأي، والعزيمة، والصبر، ففيها خير لنفسه وللآخرين.', 2, 41, 2, false, ''),
('rv8.u2.l3.4', 'u2-l3', '«الإسلام دين قوة وعزة ورفعة». ما الدليل على ذلك من القرآن؟', 'آية تأمر بإعداد القوة.', 'الإسلام يوجه المسلمين إلى الأخذ بأسباب القوة على مستوى الأفراد والدول، قال تعالى: ﴿وأعدوا لهم ما استطعتم من قوة﴾.', 1, 41, 3, false, ''),
('rv8.u2.l3.5', 'u2-l3', 'ما الذي يؤهّل القوي عن غيره؟', 'القوة تعني القدرة على التحمّل والإنجاز.', 'القوي مؤهل للقيام بالمسؤوليات والمهمات في مجاله أكثر من غيره.', 1, 41, 4, false, ''),
('rv8.u2.l3.6', 'u2-l3', 'دلّل بموقف من حياة الأنبياء على حسن توظيف القوة:', 'نبيٌّ سقى لامرأتين وهو غريب عن بلدهما.', 'وظّف موسى عليه السلام قوته في نصرة المستضعفين وتقديم العون، قال تعالى: ﴿قالت إحداهما يا أبت استأجره إن خير من استأجرت القوي الأمين﴾.', 2, 41, 5, false, ''),
('rv8.u2.l3.7a', 'u2-l3', 'ما المقصود بقوله ﷺ: «احرص على ما ينفعك»؟', '«ما ينفعك» في الدين والدنيا.', 'الحرص على توجيه طاقاته لما ينفعه في أمر دينه ودنياه، فلا ينشغل إلا بما هو نافع.', 1, 42, 6, false, ''),
('rv8.u2.l3.7b', 'u2-l3', 'لماذا أوصى النبي ﷺ بقوله: «واستعن بالله»؟', 'لا حول ولا قوة إلا بالله.', 'لا يمكن أن يقوم الإنسان وينهض بما هو بصدده من الأعباء والأعمال إلا بعون الله تعالى.', 1, 42, 7, false, ''),
('rv8.u2.l3.7c', 'u2-l3', 'ما المقصود بقوله ﷺ: «ولا تعجز»؟', 'كثيرًا ما يخطط الإنسان ثم تخور عزيمته وقت التنفيذ.', 'المثابرة وعدم التثاقل والتكاسل؛ فكثيرًا ما يخطط الإنسان ويضع البرامج، ولكن إذا جاء وقت التنفيذ خارت عزيمته.', 2, 42, 8, false, ''),
('rv8.u2.l3.8', 'u2-l3', 'ما عاقبة عدم الرضا بما قدّره الله تعالى بقول: «لو أني فعلت كان كذا وكذا»؟', 'قال ﷺ: «فإن لو تفتح عمل الشيطان».', 'عاقبة ذلك فتح باب الوساوس والندم والحسرة، وهي من عمل الشيطان، وعلى المسلم أن يكون راضيًا بما قدره الله.', 1, 42, 9, false, ''),
('rv8.u2.l3.9', 'u2-l3', 'أيٌّ مما يأتي من الأمور المترتبة على الرضا بقدر الله تعالى؟', 'الرضا يمنح الإنسان طاقة للمستقبل.', 'في الرضا بقدر الله تعالى شحذ للهمم، ودفع للنفس في مستقبل أمرها لما هو أحسن وأفضل، والسعي والمواصلة في العمل.', 1, 42, 10, false, ''),
('rv8.u2.l3.10', 'u2-l3', 'لماذا أكّد النبي ﷺ أن الخير موجود في المؤمن القوي والضعيف معًا بقوله: «وفي كلٍّ خير»؟', 'ما الصفة المشتركة بينهما في الحديث؟', 'الخير موجود فيهما لاشتراكهما في الإيمان، والدلالة: ألا يُتوهّم أن المؤمن الضعيف لا خير فيه.', 2, 42, 11, false, ''),
('rv8.u2.l3.12', 'u2-l3', 'لماذا فُضِّل المؤمن القوي على الضعيف وكان الأحب إلى الله تعالى؟', 'فكّر في من يستفيد من القوة.', 'المؤمن القوي نفعه متعدٍّ إلى غيره، أما الضعيف فنفعه قاصر على نفسه غالبًا، فقوة الفرد مصدر قوة لمجتمعه.', 2, 42, 12, false, ''),
('rv8.u2.l3.13b', 'u2-l3', 'القوة للمؤمن:', 'ينبغي للمؤمن أن يسخّر قوته فيما يجلب النفع والصلاح.', 'ينبغي للمؤمن أن يسخر قوته وطاقاته فيما يجلب النفع والصلاح لنفسه ومجتمعه، فالقوة للمؤمن وسيلة والإصلاح هدف وغاية، وليست القوة بالجبروت واستضعاف الخلق.', 2, 43, 13, false, ''),
('rv8.u2.l3.14', 'u2-l3', 'أيٌّ مما يأتي ليس من أسباب بناء الشخصية القوية؟', 'أسباب بناء الشخصية القوية: الإيمان، والعلم، والعمل، والالتزام، والصحة، والمال.', 'من أسباب بناء الشخصية القوية: الإيمان بالله والثقة به، والعلم والمعرفة، والعمل، والالتزام والانضباط، والصحة، والمال. أما الاعتماد الدائم على الآخرين فليس منها.', 1, 43, 14, false, ''),
('rv8.u2.l3.15', 'u2-l3', 'قال رسول الله ﷺ: «لو استقبلت من أمري ما استدبرت ما سقت الهدي...». ما حكم استخدام «لو» المستنتج من الحديث؟', 'النبي ﷺ نفسه استخدمها في هذا الحديث.', 'يجوز استخدام «لو» عند الرغبة في الاستزادة من الخير، أو في موضع تعليم الناس، أما موضع النهي فهو ما كان فيه معارضة لقدر الله تعالى.', 3, 43, 15, false, ''),
('rv8.u2.l3.17a', 'u2-l3', 'المؤمنون في الخيرية ومحبة الله تعالى لهم:', 'المؤمن القوي «أحب إلى الله» من الضعيف.', 'المؤمنون في الخيرية ومحبة الله لهم متفاوتون مختلفون، وإن كان في كلٍّ خير.', 2, 44, 16, false, ''),
('rv8.u2.l3.17b', 'u2-l3', 'إلقاء اللوم على الآخرين أو على الظروف عند الفشل يُعدّ:', 'قال ﷺ: «ولا تعجز».', 'إلقاء اللوم على الآخرين أو على الظروف عند الفشل يُعدّ عجزًا.', 1, 44, 17, false, ''),
('rv8.u2.l3.17c', 'u2-l3', 'قال تعالى عن المنافقين: ﴿لو كانوا عندنا ما ماتوا وما قتلوا﴾. ما حكم استخدام «لو» في هذا الموضع؟', 'هل في قولهم رضا بالقدر أم اعتراض عليه؟', 'استخدام «لو» هنا غير جائز؛ لأن فيه معارضة لقدر الله تعالى.', 2, 44, 18, false, ''),
('rv8.u2.l3.18', 'u2-l3', 'يقول عبد الله بن مسعود رضي الله عنه: «إني لأمقت الرجل أن أراه فارغًا، ليس في شيء من عمل الدنيا ولا عمل الآخرة». أين تجد هذا المعنى في حديث «المؤمن القوي»؟', 'المسلم لا يضيّع وقته فيما لا ينفع.', 'يتفق هذا المعنى مع قوله ﷺ: «احرص على ما ينفعك».', 2, 44, 19, false, ''),
('rv8.u2.l3.21', 'u2-l3', 'ما أثر إسلام شخصية قوية كعمر بن الخطاب رضي الله عنه في المسلمين؟', 'تذكّر: «قوة الفرد مصدر قوة لمجتمعه».', 'كان إسلام عمر فتحًا، وهجرته نصرًا، وإمارته رحمة، فقد أعطى إسلامه للإسلام العزة والمنعة.', 1, 44, 20, false, ''),
('rv8.u2.l4.1', 'u2-l4', 'ما السمة التي وُصفت بها الأمة الإسلامية في قوله تعالى: ﴿وكذلك جعلناكم أمة وسطا﴾؟', '«وسطًا».', 'وُصفت الأمة الإسلامية بالوسطية في كل شؤون الحياة.', 1, 45, 1, false, ''),
('rv8.u2.l4.2', 'u2-l4', 'ما أبرز ما تميّز به الدين الإسلامي؟', 'الذي سمّاه الله تعالى: ﴿اهدنا الصراط المستقيم﴾.', 'أبرز ما تميّز به الإسلام: الوسطية في كل شؤون الحياة في الاعتقاد والتصور، وفي التعبد والسلوك، وهو الذي سماه الله تعالى الصراط المستقيم.', 1, 45, 2, false, ''),
('rv8.u2.l4.3', 'u2-l4', 'كيف تعامل بعض الناس مع منهج الوسطية الذي جاء به الدين الإسلامي؟', 'الانحراف عن الوسط يكون في اتجاهين.', 'انحرف بعض الناس عن منهج الوسطية: إما بالإعراض والتفلت والتضييع، وإما بالغلو والتشدد بمجاوزة الحدود التي شرعها الله تعالى.', 2, 45, 3, false, ''),
('rv8.u2.l4.4', 'u2-l4', 'ما تعريف الغلو في الدين؟', 'الغلو مجاوزة الحدّ.', 'الغلو في الدين: هو تجاوز الحدود التي شرعها الله تعالى في الدين.', 1, 45, 4, false, ''),
('rv8.u2.l4.5', 'u2-l4', 'كم مرة وردت كلمة «الغلو» في القرآن الكريم؟ وفيمن وردت؟', 'منها قوله تعالى: ﴿قل يا أهل الكتاب لا تغلوا في دينكم﴾.', 'وردت كلمة الغلو مرتين في القرآن الكريم، في أهل الكتاب (النصارى منهم بالذات)، ومنها: ﴿قل يا أهل الكتاب لا تغلوا في دينكم غير الحق﴾ (المائدة: ٧٧).', 2, 45, 5, false, ''),
('rv8.u2.l4.6a', 'u2-l4', 'فيمَ كان غلوّ النصارى؟', 'تذكّر قوله تعالى: ﴿ورهبانية ابتدعوها﴾.', 'رفع النصارى عيسى عليه السلام من مقام النبوة إلى مقام الربوبية الذي لا يحق إلا لله وحده، وجاوزوا حدود الله عندما ابتدعوا الرهبانية فحرموا أنفسهم حقها في التمتع بطيبات الحياة.', 2, 45, 6, false, ''),
('rv8.u2.l4.6b', 'u2-l4', 'فيمَ كان غلوّ اليهود كما في قوله تعالى: ﴿ولتجدنهم أحرص الناس على حياة﴾؟', '«أحرص الناس على حياة».', 'جعل اليهود الحياة الدنيا هي الهدف الأسمى والغاية القصوى.', 2, 45, 7, false, ''),
('rv8.u2.l4.7', 'u2-l4', 'ما موقف الإسلام من الغلو؟', '﴿ما يريد الله ليجعل عليكم من حرج﴾.', 'رفض الإسلام الغلو وحذّر منه، ووجه إلى المنهج الوسط المعتدل الذي يعطي كل ذي حق حقه، فرفض الرهبانية وأباح التمتع بالطيبات، ودعا إلى توقير الرسل والصالحين دون رفع لمنزلتهم فوق المكانة التي وضعهم الله فيها.', 1, 46, 8, false, ''),
('rv8.u2.l4.8', 'u2-l4', 'دلّل على أن مشروعية الرخص جاءت لرفع الحرج عن الناس:', 'آية في سياق الصيام تتحدث عن اليسر.', 'قال تعالى: ﴿يريد الله بكم اليسر ولا يريد بكم العسر﴾ في فرضية الصيام، وقال ﷺ: «إن الدين يسر، ولن يشادّ الدين أحد إلا غلبه».', 2, 46, 9, false, ''),
('rv8.u2.l4.9', 'u2-l4', 'التقط ابن عباس للنبي ﷺ سبع حصيات صغار لرمي الجمرات، فقال ﷺ: «بأمثال هؤلاء فارموا... إياكم والغلو في الدين». ما دلالة الحديث؟', 'العمل يسير (رمي الحصى)، ومع ذلك جاء التحذير عامًّا.', 'أراد النبي ﷺ أن ينبه أمته أن النهي عن الغلو في الدين نهيٌ مطلق في جميع المسائل، وإن كان سببه خاصًّا؛ فهو نهي عن كل غلو في الدين سواء في الاعتقاد أم العبادات أم المعاملات.', 3, 46, 10, false, ''),
('rv8.u2.l4.10', 'u2-l4', 'ما السبب الرئيسي للغلو في الدين؟', 'السبب الرئيسي هو الأصل الذي تتفرع منه بقية الأسباب.', 'من أسباب الغلو: قصور الفهم، والتأويل الخاطئ للنصوص، وأخذ العلم من غير أهله، والتعصب، والتقليد دون تمحيص؛ والسبب الرئيسي: البعد عن هدي القرآن وسنة النبي ﷺ.', 2, 47, 11, false, ''),
('rv8.u2.l4.10b', 'u2-l4', 'أيٌّ مما يأتي من أسباب الغلو في الدين؟', 'مصدر العلم مهم في الفهم الصحيح.', 'من أسباب الغلو: أخذ العلم من غير أهله، ممن لا يعرف قواعد الدين ولا أصوله.', 1, 47, 12, false, ''),
('rv8.u2.l4.11a', 'u2-l4', 'في حديث الرهط الثلاثة الذين سألوا عن عبادة النبي ﷺ فتقالّوها، ما الأسلوب الذي اتبعه النبي ﷺ في تعليم أصحابه؟', 'قال ﷺ: «أنتم الذين قلتم كذا وكذا؟ ... فمن رغب عن سنتي فليس مني».', 'اتبع النبي ﷺ تصحيح الفهم الخاطئ بالحوار المفيد، ووجههم للاتباع لا الابتداع.', 2, 47, 13, false, ''),
('rv8.u2.l4.11b', 'u2-l4', 'ما سبب غلوّ الرهط الثلاثة الذين أرادوا قيام الليل كله وصيام الدهر وترك الزواج؟', 'كانت نيّتهم التقرب إلى الله، لكن الطريقة خاطئة.', 'سبب الغلو: الفهم الخاطئ بأن ذلك يقربهم إلى الله تعالى، والتوجيه النبوي: اتباع هديه ﷺ في الاعتدال في العبادة والتمتع بالطيبات وعدم تحريمها على النفس.', 2, 47, 14, false, ''),
('rv8.u2.l4.12', 'u2-l4', 'ما الأساليب التي توضح سماحة الإسلام وبعده عن الغلو في الدعوة في قوله تعالى: ﴿ادع إلى سبيل ربك بالحكمة والموعظة الحسنة وجادلهم بالتي هي أحسن﴾؟', 'الآية تذكر ثلاثة أساليب صراحة.', 'الأساليب: الحكمة، والموعظة الحسنة، والجدال بالحسنى.', 1, 47, 15, false, ''),
('rv8.u2.l4.13-1', 'u2-l4', 'ما مظهر الغلو الذي يُستنتج من قوله تعالى لموسى وهارون: ﴿فقولا له قولا لينا لعله يتذكر أو يخشى﴾؟', 'الآية تأمر باللين، فالغلو المقابل هو ...', 'تدل الآية على مظهر الغلو: الغلظة والشدة في الحوار مع المخالف في العقيدة والفكر، ويُتجنب بالحرص على اللين في الدعوة.', 2, 48, 16, false, ''),
('rv8.u2.l4.13-2', 'u2-l4', 'ما مظهر الغلو الذي يُستنتج من قوله تعالى: ﴿فلا تدعوا مع الله أحدا﴾؟', 'الدعاء لله وحده.', 'تدل الآية على مظهر الغلو: تقديس الصالحين والتوجه إليهم بالدعاء والاستغاثة بهم في الشدائد.', 2, 48, 17, false, ''),
('rv8.u2.l4.13-3', 'u2-l4', 'ما مظهر الغلو الذي يُستنتج من قوله تعالى: ﴿ولا تتبع الهوى فيضلك عن سبيل الله﴾؟', '«الهوى».', 'تدل الآية على مظهر الغلو: التعصب للرأي والهوى، ورفض الآراء المخالفة رغم موافقتها للحق.', 2, 48, 18, false, ''),
('rv8.u2.l4.13-4', 'u2-l4', 'ما مظهر الغلو الذي يُستنتج من قوله تعالى: ﴿قل من حرم زينة الله التي أخرج لعباده والطيبات من الرزق﴾؟', 'الآية تنكر تحريم الزينة والطيبات.', 'تدل الآية على مظهر الغلو: الاعتقاد أن تضييق العيش وخشونة اللبس وإهمال الهندام من التدين والورع.', 2, 48, 19, false, ''),
('rv8.u2.l4.14a', 'u2-l4', 'الالتزام بشعائر الدين، والمحافظة على حدود الله وامتثال أوامره:', 'الغلو مجاوزة الحدود، لا الالتزام بها.', 'الالتزام بشعائر الدين والمحافظة على حدود الله وامتثال أوامره لا يُعدّ غلوًّا.', 1, 48, 20, false, ''),
('rv8.u2.l4.14c', 'u2-l4', 'ما حكم الزيادة في عدد ركعات الصلاة المفروضة عن الحد المشروع بنية زيادة الأجر؟', 'العبادات توقيفية كما شرعها الله.', 'الزيادة في عدد ركعات الصلاة المفروضة عن الحد المشروع غير جائزة ولو بنية زيادة الأجر.', 1, 48, 21, false, ''),
('rv8.u2.l4.15a', 'u2-l4', 'يحاور غير المسلمين بغلظة وحدّة عبر وسائل التواصل الاجتماعي ليفرض رأيه عليهم. قيّم تصرّفه:', 'تذكّر: ﴿وجادلهم بالتي هي أحسن﴾.', 'ينبغي له أن يستغل منصات التواصل الاجتماعي في تمثيل الإسلام خير تمثيل، والدعوة إلى الله بالحسنى لا بالعنف والغلظة.', 1, 48, 22, false, ''),
('rv8.u2.l4.15b', 'u2-l4', 'يتشدّد في الأحكام الشرعية فيجعل المستحب واجبًا والمكروه حرامًا. قيّم تصرّفه:', 'من الذي يحدد الأحكام الشرعية؟', 'لا يجوز له أن يغير في الأحكام الشرعية، فهي أحكام توقيفية وفق ما شرعه الله تعالى.', 2, 48, 23, false, ''),
('rv8.u2.l4.15c', 'u2-l4', 'مريض يرفض الفطر في نهار رمضان مع توصية الطبيب الأمين له بضرورة تناول الطعام والدواء. قيّم تصرّفه:', 'الرخص جاءت لرفع الحرج.', 'لا ينبغي له ذلك، فالإسلام دين يسر، وقد رخّص له الفطر حفاظًا على حياته خاصة مع توصية الطبيب الأمين.', 1, 49, 24, false, ''),
('rv8.u2.l4.15d', 'u2-l4', 'فتاة تتساهل في اللباس الشرعي بدعوى البعد عن الغلو. ما الصواب؟', 'تذكّر: الالتزام بشعائر الدين لا يُعدّ غلوًّا.', 'لا يصح ذلك، فالالتزام بأوامر الله تعالى ليس من الغلو، والمرأة مأمورة شرعًا باللباس الساتر، وهي آثمة في التقصير والتهاون فيه.', 1, 49, 25, false, ''),
('rv8.u2.l5.1', 'u2-l5', 'ما مكانة العقل في الإسلام؟', 'لا يُكلَّف من فقد عقله.', 'جعل الإسلام العقل أساس التكليف، وآلة الفهم، ووسيلة الإدراك للتمييز بين الحق والباطل والصواب والخطأ والنفع والضرر، وأداة الاستكشاف والإبداع والاختراع.', 1, 50, 1, false, ''),
('rv8.u2.l5.2', 'u2-l5', 'كيف دعا الإسلام إلى تنمية العقل؟', '﴿إن في خلق السماوات والأرض ... لآيات لأولي الألباب﴾.', 'دعا الإسلام إلى تنمية العقل بالأمر بالقراءة والتأمل والتدبر.', 1, 50, 2, false, ''),
('rv8.u2.l5.3', 'u2-l5', 'حرّم الإسلام كل ما من شأنه تغييب العقل. أيٌّ مما يأتي مما حرّمه الإسلام لحفظ العقل؟', 'كل ما يذهب بالعقل أو يضرّه.', 'حرّم الإسلام الخمر ويلحق بها جميع المؤثرات العقلية كالمخدرات والتدخين، ونهى عن التقليد الأعمى، وحرّم السحر والخرافة والشعوذة.', 1, 50, 3, false, ''),
('rv8.u2.l5.4', 'u2-l5', 'لِمَ حدّد الشرع للعقل المجالات التي يخوض فيها؟', 'للعقل حدود في الإدراك.', 'حدّد الشرع للعقل مجالاته حفظًا له حتى لا يضل؛ فهو محدود الطاقات والملكات، فلا يستطيع أن يدرك كل الحقائق، وقد لا يعرف الحكمة من التشريع، لذلك وجهه بالاستسلام والتسليم للوحي في كثير من الأمور.', 2, 50, 4, false, ''),
('rv8.u2.l5.8', 'u2-l5', 'لماذا جعلت الشريعة الإسلامية حفظ العرض ضرورة مكمّلة لحفظ الدين والنفس؟', 'الأسرة أساس المجتمع.', 'حفظ العرض جزء من حفظ النفس والدين، فالاعتداء على العرض يؤدي إلى تهديد كيان الأسرة والمجتمع، ويعكر صفو العلاقات الاجتماعية.', 2, 51, 5, false, ''),
('rv8.u2.l5.9', 'u2-l5', 'لماذا نهى الإسلام عن الاقتراب من الزنى؟', 'يرتبط بمقصد حفظ العرض.', 'نهى الإسلام عن الاقتراب من الزنى لحماية العرض والنسب، وعدم اختلاط الأنساب، والحفاظ على الأسر والمجتمع من الفوضى والفساد.', 2, 51, 6, false, ''),
('rv8.u2.l5.10', 'u2-l5', 'أيٌّ مما يأتي من الضوابط التي وضعها الإسلام لحفظ العرض؟', 'أعراض الناس مصونة.', 'من ضوابط حفظ العرض: شرع الزواج وحرّم الزنا ودواعيه، وحرّم القذف ووضع عقوبات زاجرة لمن يتهم الناس في أعراضهم دون بينة.', 2, 51, 7, false, ''),
('rv8.u2.l5.11', 'u2-l5', 'أيٌّ مما يأتي من أهمية المال في الإسلام؟', 'المال وسيلة لا غاية.', 'عدّ الإسلام المال قوام الحياة، وركنًا من أركان الدين والدنيا، وسببًا لعيش صاحبه بعفة وكرامة، ويساعد في إقامة العبادات والأنشطة الاقتصادية، ووسيلة لتحقيق الاحتياجات الأساسية للفرد والأسرة.', 1, 51, 8, false, ''),
('rv8.u2.l5.13a', 'u2-l5', 'استنتج ضابط حفظ المال من قوله تعالى: ﴿هو الذي جعل لكم الأرض ذلولا فامشوا في مناكبها وكلوا من رزقه﴾:', '«فامشوا في مناكبها».', 'الآية تدل على الحث على الكسب الحلال.', 1, 52, 9, false, ''),
('rv8.u2.l5.13b', 'u2-l5', 'استنتج ضابط حفظ المال من قوله تعالى: ﴿والذين يكنزون الذهب والفضة ولا ينفقونها في سبيل الله فبشرهم بعذاب أليم﴾:', '«يكنزون».', 'الآية تدل على تحريم كنز الأموال.', 1, 52, 10, false, ''),
('rv8.u2.l5.13c', 'u2-l5', 'استنتج ضابط حفظ المال من قوله تعالى: ﴿يا أيها الذين آمنوا إذا تداينتم بدين إلى أجل مسمى فاكتبوه﴾:', '«فاكتبوه».', 'الآية تدل على وجوب التوثيق في المعاملات المالية بالكتابة والإشهاد والرهن.', 1, 52, 11, false, ''),
('rv8.u2.l5.13d', 'u2-l5', 'استنتج ضابط حفظ المال من قوله تعالى: ﴿يا أيها الذين آمنوا لا تأكلوا أموالكم بينكم بالباطل﴾:', '«بالباطل».', 'شرعت الأحكام لصيانة المال من الاعتداء بغير وجه حق، فحرمت الربا والسرقة والغش.', 2, 52, 12, false, ''),
('rv8.u2.l5.14a', 'u2-l5', 'لماذا حرّم الإسلام كنز الأموال؟', 'المال المكنوز لا يتحرك في السوق.', 'حرّم الإسلام كنز الأموال لأنه يمنع حركة الاقتصاد، ويفسد التوازن المالي والتجاري.', 2, 52, 13, false, ''),
('rv8.u2.l5.14b', 'u2-l5', 'لماذا أمر الإسلام بتوثيق الدَّين بالكتابة والإشهاد؟', 'التوثيق يحفظ الحقوق عند الاختلاف.', 'أمر الإسلام بتوثيق الدين بالكتابة والإشهاد لتجنب مواطن المنازعات والخصومات بين الأفراد.', 1, 52, 14, false, ''),
('rv8.u2.l5.16', 'u2-l5', 'كيف تُدحض مقولة: «المال وسخ الدنيا»؟', 'تذكّر أهمية المال في الإسلام.', 'المقولة غير صحيحة، فالمال وسيلة بيد الإنسان يستغله في الخير ومنفعة نفسه وأهله ومجتمعه، وبه يحفظ ماء وجهه عن ذل السؤال.', 1, 52, 15, false, ''),
('rv8.u2.l5.18a', 'u2-l5', 'ما التدبير الذي شرعه الإسلام لتنظيم العلاقة بين الذكر والأنثى في قوله تعالى: ﴿قل للمؤمنين يغضوا من أبصارهم﴾؟', '«يغضوا من أبصارهم».', 'أوجب الإسلام غض البصر.', 1, 53, 16, false, ''),
('rv8.u2.l5.18b', 'u2-l5', 'ما الذي حرّمه الإسلام في قول النبي ﷺ: «لا يخلونّ رجل بامرأة إلا مع ذي محرم»؟', '«لا يخلونّ».', 'حرّم الإسلام الخلوة المحرمة.', 1, 53, 17, false, ''),
('rv8.u2.l5.19-2', 'u2-l5', 'شخص يخوض في الغيبيات التي لم ترد نصوص شرعية بشأنها. قيّم تصرّفه:', 'تذكّر لماذا حدّد الشرع مجالات العقل.', 'لا ينبغي ذلك، فالعقل مجاله عالم الشهادة، فهو قاصر محدود، أما الغيبيات فيسلّم فيها بما ورد في القرآن والسنة، وذلك حفظ للعقل من التشتت والخوض فيما لا يستطيع إدراكه.', 2, 53, 18, false, ''),
('rv8.u2.l5.19-3', 'u2-l5', 'شخص تفاعل مع رسائل النصب والاحتيال التي أوهمته بفوزه بجوائز، فأدلى ببياناته البنكية. قيّم تصرّفه:', 'حفظ المال يشمل حمايته من الاحتيال.', 'ينبغي الحذر من طرق الاحتيال والنصب الإلكتروني، فهي من وسائل سرقة المال، وعليه حظر هذه الرسائل وعدم التفاعل معها وتحذير الناس منها.', 1, 53, 19, false, ''),
('rv8.u2.l5.20a', 'u2-l5', 'فتاة تتعرض لتهديد عبر الهاتف بنشر صورها. ما اسم هذه المشكلة؟', 'تهديد إلكتروني لإجبار الضحية على شيء.', 'المشكلة التي وقعت فيها الفتاة هي الابتزاز الإلكتروني.', 1, 54, 20, false, ''),
('rv8.u2.l5.20c', 'u2-l5', 'ما التصرف الأمثل عند التعرض للابتزاز الإلكتروني؟', 'لا تواجه المشكلة وحدك.', 'التصرف الأمثل: عدم الرضوخ لهذه التهديدات، وضرورة إبلاغ الأهل والمقربين ومصارحتهم، وإبلاغ الجهات المعنية.', 1, 54, 21, false, ''),
('rv8.u2.l5.21', 'u2-l5', 'بمَ تنصح من يندفع إلى تجربة السجائر الإلكترونية أو المخدرات بدافع الفضول؟', 'التجربة الأولى قد تكون بداية الإدمان.', 'أنصحه بالحذر منها والابتعاد عنها ولو على سبيل التجربة، فهي دمار وانتحار بطيء، تنتهي بالمرء إلى الإدمان.', 1, 54, 22, false, ''),
('rv8.u2.l6.1', 'u2-l6', 'ما أسباب حصار بني قريظة؟', 'تذكّر ما فعلوه في غزوة الأحزاب.', 'أسباب حصار بني قريظة: خيانتهم وغدرهم ونقضهم للعهد، وعداؤهم للمسلمين بتحالفهم مع قريش في غزوة الأحزاب.', 1, 55, 1, false, ''),
('rv8.u2.l6.2', 'u2-l6', 'علامَ يدلّ سرعة نزول جبريل عليه السلام على الرسول ﷺ عند الظهر يأمره بالتوجه إلى بني قريظة؟', 'السرعة تعكس خطورة الأمر.', 'يدل على عظم ما ارتكبه بنو قريظة من نقضهم للعهد، وفي ذلك إشارة إلى الحزم وعدم التهاون في التعامل مع الخيانة، وضرورة الاستعجال في مباغتة العدو قبل أن يعيد ترتيب أموره.', 2, 55, 2, false, ''),
('rv8.u2.l6.3', 'u2-l6', 'كيف وجّه النبي ﷺ المسلمين بعد نزول الوحي عليه بالتوجه إلى بني قريظة؟', 'الأمر مرتبط بصلاة العصر.', 'صدع النبي ﷺ بالأمر وشدّد على المسلمين أن يسارعوا في إنفاذه، وأمر أن يُؤذّن في الناس: «لا يصلّينّ أحد العصر إلا في بني قريظة».', 1, 55, 3, false, ''),
('rv8.u2.l6.3b', 'u2-l6', 'أدركت صلاة العصر بعض الصحابة في الطريق إلى بني قريظة، فصلاها بعضهم في الطريق وأخّرها بعضهم حتى وصلوا. ماذا فعل النبي ﷺ؟', 'كلا الفريقين اجتهد في فهم الأمر.', 'أقرّ النبي ﷺ الفريقين ولم يعتب على أحدهما، وفي ذلك دلالة على فتح باب الاجتهاد، وأدب الصحابة عند الاختلاف.', 2, 55, 4, false, ''),
('rv8.u2.l6.4', 'u2-l6', 'صِف الحالة النفسية لبني قريظة في أثناء الحصار:', 'تذكّر: «للهزيمة النفسية أثر كبير في الخسارة».', 'لما اشتد الحصار بدأ اليأس والخوف والرعب يتسلل إليهم، فبلغوا مرحلة التخبط سريعًا، مع أن حصونهم كانت منيعة، فهم يعلمون فداحة جرمهم ويترقبون القصاص.', 2, 55, 5, false, ''),
('rv8.u2.l6.5', 'u2-l6', 'كم ليلة حاصر المسلمون بني قريظة؟', 'أكثر من عشرين وأقل من ثلاثين.', 'حاصر المسلمون بني قريظة بضعًا وعشرين ليلة.', 2, 55, 6, false, ''),
('rv8.u2.l6.6a', 'u2-l6', 'لماذا لم تُسفر المشاورات الداخلية لبني قريظة عن حلّ لمأزقهم؟', 'اسم سيّدهم مذكور في الدرس.', 'تشاوروا داخليًّا لإيجاد حل لمأزقهم، إلا أن مشورة سيدهم كعب بن أسد لم تسفر عن رأي يرضيهم.', 2, 55, 7, false, ''),
('rv8.u2.l6.7a', 'u2-l6', 'لماذا طلب بنو قريظة من النبي ﷺ أن يرسل إليهم أبا لبابة؟', 'العلاقة القديمة تجعلهم يثقون برأيه.', 'طلبوه لأنه كان على علاقة قديمة بهم، فأرادوا استشارته في أمرهم: أينزلون على حكم محمد؟ فحذّرهم من عظم العقوبة التي ستحل بهم.', 2, 56, 8, false, ''),
('rv8.u2.l6.7b', 'u2-l6', 'لماذا طلب بنو قريظة أن يحكم فيهم سعد بن معاذ رضي الله عنه؟', 'سعد بن معاذ سيّد الأوس.', 'طلبوا تحكيم سعد بن معاذ لأنه كان بينهم وبين قبيلة الأوس حلف في الجاهلية، فظنوا أن هذه الصلة قد تنفعهم وأنه سيتساهل معهم.', 2, 56, 9, false, ''),
('rv8.u2.l6.8', 'u2-l6', 'ماذا قال النبي ﷺ معقّبًا على حكم سعد بن معاذ رضي الله عنه في بني قريظة؟', 'حكمٌ وافق حكم الله تعالى.', 'قال النبي ﷺ معقّبًا على حكم سعد: «قضيتَ بحكم الله».', 2, 56, 10, false, ''),
('rv8.u2.l6.9', 'u2-l6', 'أيٌّ مما يأتي من النتائج التي حققها المسلمون من معاقبة بني قريظة؟', 'فكّر في أثر ذلك على أمن المدينة.', 'من النتائج: استؤصلت بنو قريظة، وخلت المدينة من الوجود اليهودي الذي كان عنصرًا خطرًا، وانتهى حلم قريش بوجود حليف لهم داخل المدينة، وثبت أن المسلمين ذوو شوكة ومنعة.', 2, 56, 11, false, ''),
('rv8.u2.l6.10b', 'u2-l6', 'الصحابي الجليل الذي حكّمه النبي ﷺ في يهود بني قريظة هو:', 'سيّد الأوس الذي أُصيب في ذراعه يوم الأحزاب.', 'حكّم النبي ﷺ سعد بن معاذ رضي الله عنه في يهود بني قريظة.', 1, 57, 12, false, ''),
('rv8.u2.l6.11a', 'u2-l6', 'ما دلالة سرعة استجابة المسلمين لأمر الخروج إلى بني قريظة رغم تعبهم من حصار الأحزاب الذي استمر قرابة شهر؟', 'رغم التعب لم يتأخروا.', 'تدل على امتثال أمر الله تعالى ورسوله، والحزم وعدم التهاون مع الخونة، والاستعجال في مباغتة العدو قبل أن يعيد ترتيب أموره.', 1, 57, 13, false, ''),
('rv8.u2.l6.11c', 'u2-l6', 'ما دلالة قول رسول الله ﷺ للأنصار عند قدوم سعد بن معاذ رضي الله عنه: «قوموا إلى سيدكم»؟', '«سيّدكم» وصف تكريم.', 'يدل على تقدير النبي ﷺ لسعد رضي الله عنه، وإنزال الناس منازلهم، وإظهار مكانة أهل الفضل وإكبار عظيم القوم.', 1, 57, 14, false, ''),
('rv8.u2.l6.11d', 'u2-l6', 'ما دلالة موافقة حكم سعد بن معاذ رضي الله عنه لحكم الله ورسوله في بني قريظة؟', 'اختيار الرجل المناسب للحكم.', 'تدل على معرفة النبي ﷺ بإمكانات من حوله في اختيار أهل الكفاءة، وعدل سعد بن معاذ وإنصافه.', 2, 57, 15, false, ''),
('rv8.u2.l6.12', 'u2-l6', 'لماذا تجرّم جميع الدساتير والأعراف الدولية خيانة الوطن وتصفها بالخيانة العظمى، خاصة في زمن الحرب؟', 'تذكّر ما فعلته بنو قريظة وأثره على المدينة.', 'لما في ذلك من خطورة بالغة وتبعات على مستوى عالٍ، فهي اعتداء على الوجود السياسي للدولة، وتقويض وزعزعة لأمن الوطن واستقرار المجتمع.', 2, 58, 16, false, ''),
('rv8.u2.l7.1', 'u2-l7', 'كيف نظر الإسلام إلى تحمّل المسؤولية؟', 'تحمّل المسؤولية في الإسلام ليس أمرًا ثانويًّا.', 'أعطى الإسلام أهمية خاصة لتحمل المسؤولية، فأعلى من قيمتها، وأمر بها، وعدّ القيام بها واجبًا دينيًّا.', 1, 59, 1, false, ''),
('rv8.u2.l7.2', 'u2-l7', 'بمَ رُبطت المسؤولية في الإسلام؟', 'التكليف في أصله تحمّل مسؤوليات.', 'رُبطت المسؤولية بالعقل الذي هو مناط التكليف، وبالإرادة وحرية الاختيار، فالتكليف في أصله تحمل مسؤوليات.', 2, 59, 2, false, ''),
('rv8.u2.l7.3', 'u2-l7', 'كم مرة ورد لفظ «تحمّل المسؤولية» في القرآن الكريم؟', 'اللفظ نفسه غير موجود، لكن المعنى موجود بلفظ آخر.', 'لم يرد في القرآن بهذا اللفظ، ولكن وروده بمعناه كثير جدًّا، ومنها لفظ الأمانة.', 2, 59, 3, false, ''),
('rv8.u2.l7.4', 'u2-l7', 'ما المراد بالأمانة في قوله تعالى: ﴿إنا عرضنا الأمانة على السماوات والأرض والجبال فأبين أن يحملنها وأشفقن منها وحملها الإنسان﴾؟', 'عنوان الدرس.', 'المراد بالأمانة في الآية: تحمل المسؤولية.', 1, 59, 4, false, ''),
('rv8.u2.l7.5', 'u2-l7', 'ما معنى تحمّل المسؤولية؟', 'التبعة والالتزام.', 'تحمل المسؤولية: شعور المرء بتبعته في كل أمر يوكل إليه، وتحمّلها يكون بالالتزام بأدائها والعمل بالواجبات المترتبة عليه.', 1, 59, 5, false, ''),
('rv8.u2.l7.6', 'u2-l7', 'ما دلالة قوله ﷺ: «كلكم راعٍ وكلكم مسؤول عن رعيته...»؟', '«كلكم».', 'دليل على أن دائرة المسؤولية في الإسلام ممتدة واسعة، فلا يوجد شخص خالٍ من المسؤوليات، ولا يتصور أن المسؤولية لمن تقلد منصبًا فقط، فكلٌّ في مكانه مسؤول مهما كان موقعه.', 1, 59, 6, false, ''),
('rv8.u2.l7.8', 'u2-l7', 'ما معنى المسؤولية المجتمعية؟', 'المسؤولية تجاه المجتمع.', 'المسؤولية المجتمعية: مشاركة الفرد في المساهمة في تشكيل الواقع من حوله وتغييره، وهي الأكثر تأثيرًا على حركة التغيير الحضاري، لذلك على كل فرد أن يأخذ قسطًا منها.', 2, 60, 7, false, ''),
('rv8.u2.l7.9', 'u2-l7', 'ما مسؤولية الإنسان تجاه بيئته؟', 'البيئة أمانة.', 'مسؤولية الإنسان تجاه بيئته: المحافظة عليها، فلا يأتي بتصرف غير مسؤول يتسبب في الإضرار بها.', 1, 60, 8, false, ''),
('rv8.u2.l7.10', 'u2-l7', 'علامَ يدل تحمّل المسؤولية، وإلامَ يؤدي؟', 'قارن بين من يتحمل المسؤولية ومن يتخلّف عنها.', 'تحمل المسؤولية دلالة على النضج والوعي بأهمية المسؤولية، ويؤدي إلى النجاح والتفوق، أما تركها فدلالة على عدم النضج والتأهل الأخلاقي ويؤدي إلى الفشل والإخفاق.', 1, 60, 9, false, ''),
('rv8.u2.l7.12', 'u2-l7', 'تصرّف يوسف عليه السلام بما يمليه عليه حس المسؤولية تجاه الأزمة الاقتصادية في مصر. أيٌّ مما يأتي من التدابير التي اتخذها؟', 'خطة طويلة المدى للادخار.', 'وضع يوسف عليه السلام خطة اقتصادية تنفذ على مدى ١٥ عامًا، وحدد المشكلة وكيفية مواجهتها بالاستثمار والتوفير، وأمرهم بعدم الإسراف، وبيّن لهم أسلوب تخزين الحبوب في سنوات الخصب لسنوات الجدب والقحط.', 2, 60, 10, false, ''),
('rv8.u2.l7.12b', 'u2-l7', 'ما نتائج التدابير التي اتخذها يوسف عليه السلام في الأزمة الاقتصادية بمصر؟', 'التخطيط الجيد يحقق النجاة.', 'من النتائج: عزّز الثقة فيه، ودفع الجميع للتعاون معه، وإنقاذ مصر.', 1, 60, 11, false, ''),
('rv8.u2.l7.13', 'u2-l7', 'ما أنواع المسؤولية؟', 'ثلاثة أنواع: تجاه النفس، والمجتمع، والمحيط.', 'أنواع المسؤولية: فردية، ومجتمعية، واتجاه البيئة.', 1, 60, 12, false, ''),
('rv8.u2.l7.14', 'u2-l7', '«لا ينبغي النظر إلى المسؤولية على أنها تشريف فحسب، فالجانب التكليفي فيها أكبر». ما معنى ذلك؟', 'تشريف + تكليف، والتكليف أعظم.', 'المنصب والمسؤولية تشريف لأصحابها، ولكن على من ولي المنصب أن يدرك أن التكليف أكبر وأعظم، فعليه أن يبذل ما بوسعه للقيام بمتطلباته بما يرضي ربه وضميره، فهو محاسب على ذلك.', 2, 60, 13, false, ''),
('rv8.u2.l7.16-1', 'u2-l7', 'قول قوم موسى: ﴿فاذهب أنت وربك فقاتلا إنا هاهنا قاعدون﴾ يدل على:', '«إنا هاهنا قاعدون».', 'يدل قولهم على عدم تحمل المسؤولية.', 1, 61, 14, false, ''),
('rv8.u2.l7.16-3', 'u2-l7', 'قوله تعالى عن إسماعيل عليه السلام: ﴿وكان يأمر أهله بالصلاة والزكاة وكان عند ربه مرضيا﴾ يدل على:', 'اهتمامه بأهله.', 'تدل الآية على تحمل المسؤولية.', 1, 61, 15, false, ''),
('rv8.u2.l7.17-1', 'u2-l7', 'شخص لا يؤدي الصلاة إلا إذا ذكّره والداه. قيّم تصرّفه:', 'المسؤول لا ينتظر من يذكّره بواجباته.', 'تصرفه غير مسؤول.', 1, 62, 16, false, ''),
('rv8.u2.l7.17-3', 'u2-l7', 'فتاة تحرص على إغلاق أجهزة التكييف والإنارة قبل الخروج من المكان. قيّم تصرّفها:', 'المحافظة على الموارد.', 'تصرفها مسؤول.', 1, 62, 17, false, ''),
('rv8.u2.l7.18', 'u2-l7', 'فتاة لا تأخذ مسؤولياتها بجدّ، وعندما تُعاتَب تقول: «الأمر ليس بيدي، فالظروف والأشخاص المحيطون بي هم السبب». قيّم موقفها:', 'تذكّر: إلقاء اللوم على الآخرين عجز.', 'عذر غير مقبول، وهي حجة الضعيف الذي يلقي باللوم على الآخرين والظروف، فعليها أن تقوم بمسؤولياتها وتستقل بذاتها وتمسك زمام الأمور.', 1, 62, 18, false, ''),
('rv8.u3.l1.1a', 'u3-l1', 'السكون الموجود في بنية الكلمة الذي يبقى ملازمًا للحرف، مثل سكون السين في ﴿نستعين﴾، هو:', 'سكون لا يزول بالوصل.', 'السكون الأصلي: سكون موجود في بنية الكلمة يبقى ملازمًا للحرف، مثل سكون السين في ﴿نستعين﴾.', 1, 64, 1, false, ''),
('rv8.u3.l1.1b', 'u3-l1', 'السكون الذي يطرأ على الحرف الأخير في الكلمة عندما نقف عليها، مثل سكون النون في ﴿نستعين﴾ عند الوقف، هو:', '«يطرأ» عند الوقف.', 'السكون العارض: سكون يطرأ على الحرف الأخير في الكلمة عندما نقف عليها.', 1, 64, 2, false, ''),
('rv8.u3.l1.2', 'u3-l1', 'ما تعريف المد العارض للسكون؟', 'حرف مد + حرف أخير سُكّن للوقف.', 'المد العارض للسكون: هو أن يأتي حرف المد قبل آخر حرف في الكلمة وقد سُكّن للوقوف عليه.', 2, 64, 3, false, ''),
('rv8.u3.l1.3', 'u3-l1', 'ما حكم المد العارض للسكون؟ وما مقدار المد؟', 'الحكم «جائز» وله ثلاثة مقادير.', 'يُمدّ المد العارض للسكون جوازًا بمقدار حركتين أو أربع أو ست حركات.', 2, 64, 4, false, ''),
('rv8.u3.l1.4', 'u3-l1', 'ما نوع السكون في المد العارض للسكون؟', 'ماذا يحدث عند الوصل؟', 'السكون في المد العارض ليس أصليًّا، بل يزول عند وصل أواخر الآيات بالتي تليها، ويصبح مدًّا طبيعيًّا.', 2, 64, 5, false, ''),
('rv8.u3.l1.5', 'u3-l1', 'لماذا سُمّي المد العارض للسكون بهذا الاسم؟', 'الاسم مأخوذ من نوع السكون.', 'سمي بذلك لأن القارئ يقف على ما بعد حرف المد بسكون عارض.', 1, 64, 6, false, ''),
('rv8.u3.l1.6', 'u3-l1', 'يندرج تحت المد بسبب السكون العارض نوعان، هما:', 'كلاهما يحدث عند الوقف.', 'يندرج تحت المد بسبب السكون العارض نوعان: المد العارض للسكون، ومد اللين.', 1, 64, 7, false, ''),
('rv8.u3.l1.7a', 'u3-l1', 'ما الكلمة التي تضمنت المد العارض للسكون عند الوقف في قوله تعالى: ﴿قل أعوذ برب الناس﴾؟', 'المد العارض في آخر الآية عند الوقف.', 'في ﴿الناس﴾ مد عارض للسكون عند الوقف: الألف حرف مد، وبعدها السين سُكّنت للوقف.', 1, 64, 8, false, ''),
('rv8.u3.l1.8', 'u3-l1', 'ما تعريف مد اللين؟', 'حرفا اللين: الواو والياء الساكنتان بعد فتح.', 'مد اللين: هو أن تقع الواو أو الياء الساكنتان المفتوح ما قبلهما قبل آخر حرف في الكلمة التي نقف عليها.', 2, 65, 9, false, ''),
('rv8.u3.l1.9', 'u3-l1', 'ما حكم مد اللين؟ وما مقدار المد فيه؟', 'حكمه مثل حكم المد العارض للسكون.', 'يُمدّ مد اللين جوازًا بمقدار حركتين أو أربع أو ست حركات.', 2, 65, 10, false, ''),
('rv8.u3.l1.10', 'u3-l1', 'هل يثبت مد اللين عند الوصل؟', 'مد اللين سببه الوقف.', 'ينتفي مد اللين عند الوصل، بحيث يكون النطق بحرفيه بمقدار تحقق الحرف فقط.', 2, 65, 11, false, ''),
('rv8.u3.l1.11', 'u3-l1', 'أيّ كلمات سورة قريش فيها مد لين عند الوقف؟', 'ابحث عن واو أو ياء ساكنة قبلها فتح في أواخر الآيات.', 'مواضع مد اللين في سورة قريش: ﴿قريش﴾، ﴿والصيف﴾، ﴿البيت﴾، ﴿خوف﴾.', 2, 65, 12, false, ''),
('rv8.u3.l1.12-1', 'u3-l1', 'صنّف المد في كلمة ﴿الفائزون﴾ حال الوقف في قوله تعالى: ﴿إني جزيتهم اليوم بما صبروا أنهم هم الفائزون﴾:', 'الواو قبل النون الأخيرة مضموم ما قبلها.', 'في ﴿الفائزون﴾ حال الوقف مد عارض للسكون.', 2, 65, 13, false, ''),
('rv8.u3.l1.12-2', 'u3-l1', 'صنّف المد في كلمة ﴿كرتين﴾ حال الوقف في قوله تعالى: ﴿ثم ارجع البصر كرتين﴾:', 'الياء ساكنة وقبلها فتح.', 'في ﴿كرتين﴾ حال الوقف مد لين؛ الياء ساكنة مفتوح ما قبلها.', 2, 65, 14, false, ''),
('rv8.u3.l1.13a', 'u3-l1', 'يندرج المد العارض للسكون ومد اللين ضمن قسم المد:', 'المد الذي سببه سكون أو همز.', 'يندرج المد العارض للسكون ومد اللين ضمن قسم المد الفرعي.', 2, 65, 15, false, ''),
('rv8.u3.l1.13b', 'u3-l1', 'سبب المد العارض للسكون ومد اللين:', 'يحدث عند الوقف.', 'سبب المد العارض للسكون ومد اللين: السكون العارض.', 1, 66, 16, false, ''),
('rv8.u3.l1.13c', 'u3-l1', 'أحد الأمثلة القرآنية الآتية ليس به مد لين:', 'ابحث عن الكلمة الأخيرة التي ليس فيها واو أو ياء ساكنة بعد فتح.', 'في ﴿البيان﴾ الحرف قبل الأخير ألف، فهو مد عارض للسكون لا مد لين.', 3, 66, 17, false, ''),
('rv8.u3.l1.14', 'u3-l1', 'ما حكم المد في كلمة ﴿يتقون﴾ عند الوقف وعند الوصل في قوله تعالى: ﴿وللدار الآخرة خير للذين يتقون أفلا تعقلون﴾؟', 'السكون العارض يزول عند الوصل.', 'عند الوقف: مد عارض للسكون، وعند الوصل: مد طبيعي.', 3, 66, 18, false, ''),
('rv8.u3.l2.1', 'u3-l2', 'ما دلالة ابتداء كثير من السور القرآنية بالحروف المقطعة، كسورة مريم التي ابتدأت بـ ﴿كهيعص﴾؟', 'القرآن من الحروف نفسها التي يتكلمون بها.', 'في ابتداء السور بالحروف المقطعة تنبيه للسامعين، وتحدٍّ للجاحدين بأن يأتوا بمثل هذا القرآن الكريم.', 2, 67, 1, false, ''),
('rv8.u3.l2.2', 'u3-l2', 'ما المقصود بكفالة سيدنا زكريا عليه السلام لمريم ابنة عمران؟', 'الكفالة رعاية وقيام بالشؤون.', 'كان زكريا عليه السلام يقوم على رعايتها وشؤونها وما تحتاجه، فقد كان من أبناء عمومتها.', 1, 67, 2, false, ''),
('rv8.u3.l2.3', 'u3-l2', 'ما تأثير رؤية زكريا عليه السلام وجود الرزق عند مريم كلما دخل عليها المحراب؟', 'الذي رزق مريم بغير حساب قادر على أن يرزقه.', 'حرّك ذلك في نفسه الرغبة في الولد، وهو شيخ كبير السن وامرأته عاقر، فأخذ يدعو بيقين وثقة أن يرزقه الله الولد، وقد كان.', 2, 67, 3, false, ''),
('rv8.u3.l2.4', 'u3-l2', 'هل كان دعاء زكريا عليه السلام أن يرزقه الله الولد لإشباع غريزة الأبوة فقط؟', '﴿يرثني ويرث من آل يعقوب﴾.', 'طلب زكريا عليه السلام الولد نصرة للدين واستمراريته، فقد خاف أن يضيع قرابته أمانة الدين من بعده.', 2, 67, 4, false, ''),
('rv8.u3.l2.5', 'u3-l2', 'كيف كانت رحمة الله تعالى بعبده زكريا عليه السلام في هذه القصة؟', '﴿لم نجعل له من قبل سميا﴾.', 'استجاب الله تعالى له وبشّره بغلام اسمه يحيى لم يتسمَّ به أحد من قبله.', 1, 67, 5, false, ''),
('rv8.u3.l2.7', 'u3-l2', 'ما العلامة التي طلبها زكريا عليه السلام من ربه ليطمئن قلبه بما وُعد به؟', '﴿آيتك ألا تكلم الناس ثلاث ليال سويا﴾.', 'كانت العلامة ألا يكلم الناس ثلاث ليالٍ، فخرج على قومه من المحراب فأشار إليهم أن سبّحوا الله أول النهار وآخره؛ شكرًا على النعمة.', 2, 67, 6, false, ''),
('rv8.u3.l2.8', 'u3-l2', 'ما الأثر الذي تبعثه معرفتك بقصة زكريا ويحيى عليهما السلام في حياتك اليومية؟', 'رُزق الولد مع كبر السن وعقم الزوجة.', 'قصة زكريا ويحيى عليهما السلام تملأ النفس يقينًا بالقدرة الربانية، وتبين فضل الدعاء الخفي، حتى لا ييأس أحد من فضل الله ورحمته، فقدرته فوق الأسباب والمسببات.', 1, 68, 7, false, ''),
('rv8.u3.l2.9', 'u3-l2', '«الفكر السائد عند الناس في ذلك الوقت هو ربط النتائج بأسبابها فقط». ما الصواب؟', 'هل كان رزق زكريا بالولد خاضعًا للأسباب المعتادة؟', 'فكر خاطئ؛ لأن قدرته تعالى فوق الأسباب والمسببات ولا تتقيد بها.', 2, 68, 8, false, ''),
('rv8.u3.l2.11-1', 'u3-l2', 'ما أدب الدعاء في قول زكريا عليه السلام: ﴿قال رب إني وهن العظم مني واشتعل الرأس شيبا﴾؟', 'يصف ضعف حاله.', 'في الآية التوسل إلى الله بإظهار الضعف.', 1, 68, 9, false, ''),
('rv8.u3.l2.11-2', 'u3-l2', 'ما أدب الدعاء في قول زكريا عليه السلام: ﴿ولم أكن بدعائك رب شقيا﴾؟', 'يذكر أن الله لم يخيّب دعاءه من قبل.', 'في الآية الاعتراف بفضل الله تعالى.', 2, 68, 10, false, ''),
('rv8.u3.l2.11-3', 'u3-l2', 'ما أدب الدعاء في قول زكريا عليه السلام: ﴿وإني خفت الموالي من ورائي ... فهب لي من لدنك وليا يرثني ويرث من آل يعقوب﴾؟', 'يبيّن لماذا يطلب الولد.', 'في الآية إظهار الغرض النبيل من الدعاء.', 2, 68, 11, false, ''),
('rv8.u3.l2.12a', 'u3-l2', 'ما أهمية نعمة الولد الصالح؟', 'تذكّر طلب زكريا: ﴿واجعله رب رضيا﴾.', 'الولد الصالح قرة عين لوالديه، وعون لهما على متاعب الحياة، ويجرّ الحسنات إلى والديه بعد موتهما من خلال أعماله الخيرة ودعائه لهما.', 1, 68, 12, false, ''),
('rv8.u3.l2.12b', 'u3-l2', 'أيٌّ مما يأتي من صفات الولد الصالح كما يُفهم من الآيات؟', 'تذكّر صفات يحيى عليه السلام.', 'من صفات الولد الصالح: الفهم، ورجاحة العقل، والحنان، والرحمة، والطهارة من الصفات الذميمة، وطاعة الله واجتناب نواهيه.', 1, 69, 13, false, ''),
('rv8.u3.l2.13-1', 'u3-l2', 'ما دلالة قوله تعالى: ﴿فهب لي من لدنك وليا﴾؟', '«من لدنك» أي من عندك، بلا أسباب معتادة.', 'تدل الآية على اليقين بقدرة الله تعالى المطلقة.', 2, 69, 14, false, ''),
('rv8.u3.l2.13-3', 'u3-l2', 'ما دلالة قوله تعالى: ﴿يا يحيى خذ الكتاب بقوة﴾؟', '«بقوة».', 'تدل الآية على حمل أمانة العلم بحرص وجد وعزم.', 1, 69, 15, false, ''),
('rv8.u3.l2.14-1', 'u3-l2', 'ما الأمر الخارق للعادة في قوله تعالى: ﴿يا زكريا إنا نبشرك بغلام﴾؟', 'تذكّر حال زكريا وامرأته.', 'الأمر الخارق: خُلق يحيى من دون وجود أسباب الحمل، فالأب كبير في السن والأم عاقر.', 2, 69, 16, false, ''),
('rv8.u3.l2.14-2', 'u3-l2', 'ما الأمر الخارق للعادة في قوله تعالى: ﴿قال آيتك ألا تكلم الناس ثلاث ليال سويا﴾؟', '«سويًّا» أي سليمًا.', 'الأمر الخارق: عدم قدرة زكريا عليه السلام على الكلام مع وجود أسبابه من سلامة جوارحه وعدم وجود علة تمنعه من ذلك كالخرس.', 2, 69, 17, false, ''),
('rv8.u3.l2.14-3', 'u3-l2', 'ما الأمر الخارق للعادة في قوله تعالى عن يحيى: ﴿وآتيناه الحكم صبيا﴾؟', '«صبيًّا».', 'أعطي يحيى عليه السلام الحكم وهو صبي، والحكمة في الغالب تؤتى في الكبر.', 2, 69, 18, false, ''),
('rv8.u3.l3.2', 'u3-l3', 'ما موقف الإسلام من الغيبة؟', 'شبّه الله المغتاب بمن يأكل لحم أخيه ميتًا.', 'حرّم الإسلام الغيبة تحريمًا مغلّظًا، وعدّها من كبائر الذنوب.', 1, 70, 1, false, ''),
('rv8.u3.l3.3', 'u3-l3', 'بمَ شبّه الله تعالى من يغتاب الآخرين؟', '﴿أيحب أحدكم أن يأكل لحم أخيه ميتا فكرهتموه﴾.', 'شبّه الله تعالى المغتاب بمن يأكل لحم أخيه وهو ميت: ﴿ولا يغتب بعضكم بعضا أيحب أحدكم أن يأكل لحم أخيه ميتا فكرهتموه﴾.', 1, 70, 2, false, ''),
('rv8.u3.l3.5', 'u3-l3', 'ما الضابط المحدد للغيبة كما ذكره النبي ﷺ في الحديث الشريف؟', '«ذكرك أخاك بما يكره».', 'ضابط الغيبة: ذكر المسلم أخاه بما يكره في غيابه.', 1, 70, 3, false, ''),
('rv8.u3.l3.8', 'u3-l3', 'لماذا حُرّمت الغيبة؟', 'الأذى يقع على من اغتيب.', 'حُرّمت الغيبة لأنها تؤذي المسلم، فتمس كرامته وعرضه، وتكشف عن عيوبه أمام الآخرين.', 1, 70, 4, false, ''),
('rv8.u3.l3.9', 'u3-l3', 'هل تكون الغيبة باللسان فقط؟', 'كل ما يوصل معنى العيب عن الغائب.', 'الغيبة لا تكون بالتلفظ بالكلام فقط، بل تشمل الكتابة والإشارة والإيماء والهمز واللمز والاستماع والحركة والمحاكاة.', 1, 70, 5, false, ''),
('rv8.u3.l3.10', 'u3-l3', 'ماذا يُسمّى ذِكر المسلم أخاه بمنقصة ليست فيه كذبًا، سواء في حضرته أم في غيابه؟', 'قال ﷺ: «وإن لم يكن فيه فقد بهتّه».', 'ذكر المسلم أخاه بمنقصة ليست فيه كذبًا يسمى البهتان.', 1, 71, 6, false, ''),
('rv8.u3.l3.11', 'u3-l3', 'أيٌّ مما يأتي مثال على البهتان؟', 'البهتان افتراء بما ليس في الشخص.', 'البهتان كأن يقول فلان ظالم وهو ليس كذلك، فهو افتراء. أما الغيبة فكأن يذكر عيبًا موجودًا فيه وهو يكره ذكره.', 2, 71, 7, false, ''),
('rv8.u3.l3.13', 'u3-l3', 'أيٌّ مما يأتي من آثار الغيبة على المجتمع؟', 'الغيبة مرض اجتماعي.', 'من آثار الغيبة على المجتمع: تسبب العداوة والبغضاء والخصام، وهي مرض اجتماعي يقطع أواصر المحبة والألفة بين الناس.', 1, 71, 8, false, ''),
('rv8.u3.l3.13b', 'u3-l3', 'ما أثر الغيبة على المغتاب نفسه؟', 'من يغتاب الناس عندك يغتابك عندهم.', 'الغيبة تجعل المغتاب ذا مكانة دنيئة بين أفراد المجتمع، لا يحبه الناس ولا يثقون به ولا يرغبون في مجالسته.', 1, 71, 9, false, ''),
('rv8.u3.l3.14', 'u3-l3', 'قالت عائشة رضي الله عنها للنبي ﷺ عن صفية: «حسبك من صفية كذا وكذا» تعني قصيرة، فقال ﷺ: «لقد قلتِ كلمة لو مُزجت بماء البحر لمزجته». ما المقصود؟', 'تصوير لشدة قبح الغيبة ولو بكلمة واحدة.', 'أي لو خالطت ماء البحر لتغيّر بها طعمه وريحه لشدة نتانتها؛ وهذا موقف من حياة الرسول ﷺ في تحريم الغيبة.', 2, 71, 10, false, ''),
('rv8.u3.l3.16', 'u3-l3', 'ما دلالة ذكر لفظ «الأخ» في قوله تعالى: ﴿أن يأكل لحم أخيه﴾ وقوله ﷺ: «ذكرك أخاك بما يكره»؟', 'كيف يغتاب الإنسانُ أخاه؟', 'ذكر لفظ الأخ للتذكير بالسبب الباعث على ترك الغيبة وهو الأخوة، فعلى المسلم أن يترفع عن غيبة أخيه.', 2, 72, 11, false, ''),
('rv8.u3.l3.17', 'u3-l3', 'لماذا حذّر الإسلام من الجلوس في مجالس الغيبة؟', 'التعوّد على الشيء يجعله عادة.', 'حتى لا تكون سجية فيه، فيصعب عليه التخلص منها، فهي سبب في العداوة والخصام، والله تعالى يريد أن يكون المجتمع متماسكًا كالجسد الواحد.', 2, 72, 12, false, ''),
('rv8.u3.l3.19', 'u3-l3', 'إذا قيل لبعض الناس: لا تغتب فلانًا، ردّ: «أنا مستعد أن أقول هذا الكلام في وجوده». ما الصواب؟', 'هل يصبح الأذى أخفّ إذا قيل في الوجه؟', 'تصرفهم خاطئ؛ عليه أن يعلم عاقبة الغيبة، ثم ليعلم أن ذكر ذلك في وجود أخيه أشد إيذاءً لأخيه، وانتقاص المسلم في حضرته شتم وسب له، والمسلم مصون الكرامة في حضرته وغيابه.', 2, 72, 13, false, ''),
('rv8.u3.l3.20a', 'u3-l3', 'ردّ الصحابة رضي الله عنهم العلم لله والرسول ﷺ بقولهم: «الله ورسوله أعلم» دليلٌ على حسن ...... معهما.', 'لم يتقدّموا بالجواب.', 'رد الصحابة العلم لله والرسول ﷺ دليل على حسن التأدب معهما.', 1, 72, 14, false, ''),
('rv8.u3.l3.20b', 'u3-l3', 'مستمع الغيبة والمغتاب يشتركان في:', 'السكوت عن المنكر رضًا به.', 'مستمع الغيبة والمغتاب يشتركان في الإثم.', 1, 72, 15, false, ''),
('rv8.u3.l3.21-1', 'u3-l3', 'تلطّف في نصح زميله الذي يُكثر من ذكر مساوئ جاره والعيب عليه قائلًا: «هلّا اشتغلنا بعيوب أنفسنا». قيّم الموقف:', 'النصح بلطف.', 'تصرف صحيح من الناصح؛ لأن النصح بالحسنى مدعاة للإقلاع عن هذا الفعل.', 1, 73, 16, false, ''),
('rv8.u3.l3.21-3', 'u3-l3', 'شخص استمع إلى الغيبة ولم يشارك فيها. قيّم موقفه:', 'تذكّر: المستمع والمغتاب شريكان.', 'تصرف خاطئ؛ فهو وإن لم يشاركهم بلسانه، فقد شاركهم باستماعه.', 1, 73, 17, false, ''),
('rv8.u3.l3.21-4', 'u3-l3', 'تُرسل في أحد تطبيقات التواصل الاجتماعي ما يعيب زميلتها وهي غير موجودة في المجموعة، قاصدةً الاستماع بتعليقات المجموعة عليها. قيّم الموقف:', 'الغيبة تكون بالكتابة أيضًا.', 'تصرف خاطئ؛ ففي ذلك انتقاص وسخرية، وهو من الغيبة.', 1, 73, 18, false, ''),
('rv8.u3.l3.21-5', 'u3-l3', 'تواصل الأخصائي الاجتماعي مع ولي أمر طالب ليخبره عن سلوك ابنه في المدرسة. قيّم الموقف:', 'الغرض هنا الإصلاح لا العيب.', 'تصرف صحيح؛ ففيه تقويم لسلوك الطالب، وهو من الأمر بالمعروف والنهي عن المنكر.', 2, 73, 19, false, ''),
('rv8.u3.l3.23', 'u3-l3', 'في قوله ﷺ: «أتدرون ما الغيبة؟»، ما الأسلوب الذي اتبعه النبي ﷺ في تعليم أصحابه؟', 'بدأ بسؤال.', 'من منهج النبي ﷺ في تعليم أصحابه: طرح السؤال لإثارة الانتباه (أتدرون ما الغيبة؟)، والاستعطاف في الكلام (أخاك)، والكلام الجامع الموجز.', 1, 73, 20, false, ''),
('rv8.u3.l3.26', 'u3-l3', 'أيٌّ مما يأتي من المعينات التي تعين المسلم على ترك الغيبة؟', 'النفس إن لم تشغلها بالطاعة شغلتك بالمعصية.', 'من المعينات على ترك الغيبة: استشعار مراقبة الله تعالى، وإدراك عظم الإثم من الغيبة، واختيار الصحبة الصالحة، والاستثمار النافع للوقت، ووضع الإنسان نفسه مكان الشخص الذي اغتيب.', 1, 74, 21, false, ''),
('rv8.u3.l3.27', 'u3-l3', 'يفكر زميلك في أعمال يكفّر بها عن خطئه في حق صديقه الذي اغتابه. أيٌّ مما يأتي من هذه الأعمال؟', 'الذنب في حق الله وفي حق العبد.', 'من الأعمال: التوبة والاستغفار، والعزم على عدم العودة إلى هذا الذنب، والثناء عليه في المكان الذي اغتابه فيه والدعاء له، وطلب العفو والصفح ممن اغتابه.', 1, 75, 22, false, ''),
('rv8.u3.l4.1', 'u3-l4', 'كم مرة ذُكر اسم الله «المصوّر» في القرآن الكريم؟', 'في آخر سورة الحشر.', 'ذُكر اسم الله المصوّر في القرآن الكريم مرة واحدة: ﴿هو الله الخالق البارئ المصور له الأسماء الحسنى﴾.', 2, 76, 1, false, ''),
('rv8.u3.l4.3', 'u3-l4', 'ما أسماء الله الحسنى التي اقترن بها اسم الله «المصوّر» في قوله تعالى: ﴿هو الله الخالق البارئ المصور﴾؟', 'الاسمان قبله في الآية.', 'اقترن اسم الله المصور في هذه الآية باسمي الخالق والبارئ.', 1, 76, 2, false, ''),
('rv8.u3.l4.4', 'u3-l4', 'ما الفرق بين الخلق والبَرء؟', 'التقدير يسبق الإيجاد.', 'الخلق: هو تقدير وجود المخلوق، والبرء: إيجاده من العدم.', 3, 76, 3, false, ''),
('rv8.u3.l4.5', 'u3-l4', 'ماذا يعني اسم الله «المصوّر»؟', 'الصورة والهيئة.', 'المصوّر: هو الذي صوّر جميع المخلوقات ورتبها، فأعطى كلًّا منها صورة خاصة وهيئة منفردة تتميز على اختلافها وكثرتها.', 1, 76, 4, false, ''),
('rv8.u3.l4.6', 'u3-l4', 'هل يرى الإنسان كل إبداع الله تعالى في التصوير؟', 'تذكّر ما تكشفه المجاهر.', 'لا، فما يراه الإنسان الشكل الخارجي لجميع الكائنات، فهناك معجزات خفية في باطن كل ما خلق الله لا يمكن أن يراه الإنسان بالعين المجردة، وإنما يحتاج إلى مجاهر ومختبرات في كثير من الأحيان.', 2, 76, 5, false, ''),
('rv8.u3.l4.7', 'u3-l4', 'تشير الآية الكريمة: ﴿هو الذي يصوركم في الأرحام كيف يشاء﴾ إلى أن تصوير الإنسان يكون في:', 'الكلمة في الآية نفسها.', 'تشير الآية إلى أن تصوير الإنسان يكون في الأرحام.', 1, 76, 6, false, ''),
('rv8.u3.l4.8', 'u3-l4', 'قال تعالى: ﴿ومن آياته خلق السماوات والأرض واختلاف ألسنتكم وألوانكم﴾. كيف تتعامل مع هذا الاختلاف في ضوء إيمانك باسم الله المصور؟', 'الاختلاف تصوير الله الذي أراده بحكمته.', 'أعظّم الله تعالى على بديع تصويره، وأشكره على نعمة الخلق والتصوير، ولا أنتقص الآخرين، وأعامل الناس دون تفرقة عنصرية بسبب أشكالهم وألوانهم، وأحترم الاختلاف والتنوع.', 1, 76, 7, false, ''),
('rv8.u3.l4.10a', 'u3-l4', 'ما الأثر الإيماني لاسم الله المصوّر المستنبط من قوله تعالى: ﴿لقد خلقنا الإنسان في أحسن تقويم﴾؟', 'خُلقت في أحسن صورة.', 'الأثر الإيماني: الرضا بخلقة الله تعالى.', 1, 77, 8, false, ''),
('rv8.u3.l4.10b', 'u3-l4', 'ما الأثر الإيماني لاسم الله المصوّر المستنبط من قوله تعالى على لسان إبليس: ﴿ولآمرنهم فليغيرن خلق الله﴾؟', 'إبليس يأمر بتغيير خلق الله.', 'الأثر الإيماني: تجنب تغيير خلق الله.', 1, 77, 9, false, ''),
('rv8.u3.l4.10c', 'u3-l4', 'ما الأثر الإيماني لاسم الله المصوّر المستنبط من قوله تعالى: ﴿يا أيها الإنسان ما غرك بربك الكريم الذي خلقك فسواك فعدلك﴾؟', '«ما غرّك».', 'الأثر الإيماني: عدم الغرور.', 2, 77, 10, false, ''),
('rv8.u3.l4.10d', 'u3-l4', 'قال رجل للنبي ﷺ: إن الرجل يحب أن يكون ثوبه حسنًا ونعله حسنة، فقال ﷺ: «إن الله جميل يحب الجمال». ما الأثر الإيماني المستنبط؟', 'الثوب الحسن والنعل الحسنة.', 'الأثر الإيماني: الحرص على المظهر الحسن.', 1, 77, 11, false, ''),
('rv8.u3.l4.11a', 'u3-l4', 'متى تكون عمليات التجميل محرّمة؟', '﴿ولآمرنهم فليغيرن خلق الله﴾.', 'تكون عمليات التجميل محرمة إذا كان فيها تبديل لخلق الله بحيث يغير الإنسان ما فطره الله عليه، فإن ذلك من وحي الشيطان.', 2, 77, 12, false, ''),
('rv8.u3.l4.11b', 'u3-l4', 'متى تكون عمليات التجميل جائزة؟', 'الغرض علاج الضرر لا التبديل.', 'تكون جائزة إذا كانت لأجل إزالة تشوه وقع للإنسان يؤدي به إلى الضرر جسديًّا ونفسيًّا، فلا مانع من إزالة التشوهات من غير تبديل لخلق الله تعالى.', 2, 77, 13, false, ''),
('rv8.u3.l4.13', 'u3-l4', 'ما الهدي النبوي المستنبط من دعاء النبي ﷺ عند النظر إلى المرآة: «اللهم أحسنت خَلقي فأحسن خُلُقي»؟', 'خَلق وخُلق.', 'يعلمنا النبي ﷺ دعاءً لإتمام النعمة بأن يجمع الله له حسن الخلق مع حسن الخلقة.', 2, 78, 14, false, ''),
('rv8.u3.l4.13b', 'u3-l4', 'ما الهدي النبوي المستنبط من قوله ﷺ: «إذا ضرب أحدكم فليجتنب الوجه، ولا يقل: قبّح الله وجهك»؟', 'الوجه من صنعة الله.', 'الهدي: عدم تقبيح الوجه أو الخلقة؛ فالإنسان صنعة الله الذي خلقه وصوره وكرمه، وذم الصنعة إنما هو مذمة للصانع، ووجّه النبي ﷺ لاحترام النفس البشرية وخلقتها.', 2, 78, 15, false, ''),
('rv8.u3.l5.1', 'u3-l5', 'ما المقصود بـ «الحكم الشرعي التكليفي»؟', 'يبدأ التعريف بـ «خطاب الله تعالى».', 'الحكم الشرعي التكليفي: هو خطاب الله تعالى المتعلق بأفعال المكلفين اقتضاءً أو تخييرًا.', 2, 80, 1, false, ''),
('rv8.u3.l5.3', 'u3-l5', 'من هو المكلّف؟', 'ثلاثة شروط.', 'المكلّف: هو العاقل البالغ المختار، فيخرج بذلك المجنون والصبي والمكره.', 1, 80, 2, false, ''),
('rv8.u3.l5.4', 'u3-l5', 'ما الفرق بين الاقتضاء والتخيير في تعريف الحكم الشرعي؟', 'التخيير يعني أنك مخيّر.', 'الاقتضاء: هو الطلب، سواء طلب فعل أو طلب ترك، ويندرج تحته الواجب والمندوب والحرام والمكروه. أما التخيير: فهو ما يتساوى فيه الفعل وتركه، ويندرج تحته المباح.', 2, 80, 3, false, ''),
('rv8.u3.l5.6a', 'u3-l5', 'ما طلب الشارع فعله طلبًا جازمًا لازمًا، فيُثاب فاعله ويُعاقب تاركه، هو:', 'طلب فعل جازم.', 'الواجب أو الفرض: هو ما طلب الشارع فعله طلبًا جازمًا لازمًا، فيثاب فاعله ويعاقب تاركه، مثل: الصلوات الخمس وصيام رمضان.', 1, 81, 4, false, ''),
('rv8.u3.l5.6b', 'u3-l5', 'ما طلب الشارع فعله طلبًا غير لازم، فيُثاب فاعله ولا يُعاقب تاركه، مثل صيام الاثنين والخميس، هو:', 'طلب فعل غير جازم.', 'المندوب: هو ما طلب الشارع فعله طلبًا غير لازم، فيثاب فاعله ولا يعاقب تاركه.', 1, 81, 5, false, ''),
('rv8.u3.l5.6c', 'u3-l5', 'ما طلب الشارع تركه طلبًا غير لازم، فيُثاب تاركه ولا يُعاقب فاعله، مثل إغماض العينين في الصلاة، هو:', 'طلب ترك غير جازم.', 'المكروه: هو ما طلب الشارع تركه طلبًا غير لازم، فيثاب تاركه ولا يعاقب فاعله، مثل: إغماض العينين في الصلاة، وإفراد يوم الجمعة بالصيام.', 2, 81, 6, false, ''),
('rv8.u3.l5.6d', 'u3-l5', 'ما خيّر الشارع بين فعله وتركه، فلا يُثاب فاعله ولا يُعاقب تاركه إلا إذا اقترن بالنية، مثل السفر والبيع والشراء، هو:', 'تخيير.', 'المباح: هو ما خيّر الشارع بين فعله وتركه، فلا يثاب فاعله ولا يعاقب تاركه إلا إذا اقترن بالنية.', 1, 81, 7, false, ''),
('rv8.u3.l5.6e', 'u3-l5', 'السرقة والكذب من أمثلة:', 'ما طلب الشارع تركه طلبًا جازمًا.', 'المحرّم: هو ما طلب الشارع تركه طلبًا جازمًا لازمًا، فيثاب تاركه ويعاقب فاعله، مثل: السرقة والكذب.', 1, 81, 8, false, ''),
('rv8.u3.l5.7a', 'u3-l5', 'ما طلب الشارع فعله من كل مكلف، كالصلوات الخمس وصيام رمضان، يسمى:', 'واجب على كل فرد بعينه.', 'فرض العين: هو ما طلب الشارع فعله من كل مكلف، كالصلوات الخمس وصيام رمضان.', 1, 81, 9, false, ''),
('rv8.u3.l5.7b', 'u3-l5', 'ما إذا قام به البعض سقط عن الباقين، وإذا لم يقم به أحد أثموا جميعًا، كردّ السلام وصلاة الميت، يسمى:', 'يكفي أن يقوم به بعض الناس.', 'فرض الكفاية: هو ما إذا قام به البعض سقط عن الباقين، وإذا لم يقم به أحد أثموا جميعًا على تركه، كرد السلام وصلاة الميت.', 1, 81, 10, false, ''),
('rv8.u3.l5.8', 'u3-l5', 'لماذا حاجة المسلم إلى معرفة الأحكام الشرعية متجددة في كل زمان ومكان؟', 'الوقائع الجديدة.', 'لأنه مع مرور الزمان تستجد أحداث ووقائع لم تكن موجودة سابقًا، فلا بد من معرفة الأحكام الشرعية لها.', 2, 81, 11, false, ''),
('rv8.u3.l5.9-1', 'u3-l5', 'ما الحكم الشرعي المستنبط من قوله تعالى: ﴿يا أيها الذين آمنوا كتب عليكم الصيام﴾؟', 'كلمة «كُتب».', '«كُتب» من صيغ الوجوب، فالحكم: واجب (فرض).', 1, 82, 12, false, ''),
('rv8.u3.l5.9-2', 'u3-l5', 'ما الحكم الشرعي المستنبط من قوله تعالى: ﴿أحلت لكم بهيمة الأنعام﴾؟', 'كلمة «أُحلّت».', '«أُحلّت» من صيغ الإباحة، فالحكم: مباح.', 1, 82, 13, false, ''),
('rv8.u3.l5.9-3', 'u3-l5', 'ما الحكم الشرعي المستنبط من قوله تعالى: ﴿إن الذين يأكلون أموال اليتامى ظلما إنما يأكلون في بطونهم نارا وسيصلون سعيرا﴾؟', 'ترتّب على الفعل وعيد بالنار.', 'ترتّب الوعيد على الفعل من صيغ التحريم، فالحكم: محرّم.', 1, 82, 14, false, ''),
('rv8.u3.l5.9-4', 'u3-l5', 'ما الحكم الشرعي المستنبط من قوله ﷺ في الحديث القدسي: «وما يزال عبدي يتقرب إليّ بالنوافل حتى أحبه»؟', 'النوافل والقُرُبات.', '«النوافل» و«يتقرب» من صيغ الندب، فالحكم: مندوب.', 2, 82, 15, false, ''),
('rv8.u3.l5.9-5', 'u3-l5', 'ما الحكم الشرعي المستنبط من قوله ﷺ: «إن الله كره لكم ثلاثًا: قيل وقال، وإضاعة المال، وكثرة السؤال»؟', 'كلمة «كَرِه».', '«كَرِه» من صيغ الكراهة، فالحكم: مكروه.', 1, 82, 16, false, ''),
('rv8.u3.l5.10', 'u3-l5', 'لماذا كان ترك الفعل المكروه أولى من الإتيان به؟', 'الثواب في الترك، والخوف من التدرّج.', 'لأن المسلم يثاب على تركه، وحتى لا يعتاد على الإتيان بالمكروه فيتساهل في إتيان المحرم.', 2, 82, 17, false, ''),
('rv8.u3.l5.12a', 'u3-l5', 'يخرج من الخطاب التكليفي:', 'المكلّف عاقل بالغ مختار.', 'يخرج من الخطاب التكليفي المجنون؛ لأنه غير عاقل.', 1, 82, 18, false, ''),
('rv8.u3.l5.12b', 'u3-l5', 'الحكم الشرعي التكليفي المُلزِم فعلُه:', '«الملزم فعله» أي يجب فعله.', 'الحكم الملزم فعله هو فرض العين.', 1, 82, 19, false, ''),
('rv8.u3.l5.12d', 'u3-l5', 'الأصل في الأشياء:', 'ما لم يرد دليل بالمنع.', 'الأصل في الأشياء الإباحة.', 1, 83, 20, false, ''),
('rv8.u3.l5.13', 'u3-l5', 'قال ﷺ: «لولا أن أشق على أمتي لأمرتهم بالسواك مع كل صلاة». كيف تطبّق الحكم المستنبط؟', '«لولا أن أشق» تدل على أنه غير واجب.', 'أحافظ على نظافة فمي باستخدام السواك، وخاصة عند الصلاة، اقتداءً برسولي ﷺ، وهو أمر مندوب.', 2, 83, 21, false, ''),
('rv8.u3.l6.1', 'u3-l6', 'إلى أي قبيلة ينتمي خالد بن الوليد رضي الله عنه؟', 'من قبائل قريش التي كان من مسؤولياتها القبّة وقيادة الخيل.', 'ينتمي خالد إلى قبيلة بني مخزوم، إحدى القبائل التي تزعمت السيادة في قريش، وكان من مسؤولياتها إعلان الحرب والقيادة العسكرية للخيول.', 1, 84, 1, false, ''),
('rv8.u3.l6.2', 'u3-l6', 'لماذا عهد الوليد بن المغيرة لابنه خالد قيادة الخيل منذ صباه الباكر؟', 'رأى فيه علامات الفارس.', 'عهد إليه بقيادة الخيل لما توسّم فيه من مخايل الفروسية، فنشأ نشأة عسكرية.', 1, 84, 2, false, ''),
('rv8.u3.l6.3', 'u3-l6', 'ما موقف خالد بن الوليد من الإسلام قبل اعتناقه له؟', 'كان له دور في تحويل النصر إلى المشركين يوم أحد.', 'في البداية نفر منه كما نفر أبوه، وقاتل في صفوف المشركين، وتولى قيادة الميمنة يوم أحد، وشارك في غزوة الأحزاب، وفي الحديبية بعثته قريش للتصدي للنبي ﷺ.', 2, 84, 3, false, ''),
('rv8.u3.l6.5', 'u3-l6', 'لماذا امتنع خالد بن الوليد عن الهجوم على النبي ﷺ وأصحابه يوم الحديبية وهم يصلون صلاة الخوف؟', 'الفارس الشريف لا يغدر.', 'منعته رهبة الصلاة، ونخوة الفارس المحجم عن الغدر، وسرى في نفسه آنذاك أن لمحمد سرًّا وأن الرجل ممنوع.', 2, 84, 4, false, ''),
('rv8.u3.l6.6c', 'u3-l6', 'ماذا قال النبي ﷺ عن خالد في رسالة أخيه الوليد بن الوليد إليه؟', 'كان النبي ﷺ يسأل عنه.', 'أخبره أخوه أن الرسول ﷺ يسأل عنه قائلًا: «أين خالد؟ ما مثل خالد يجهل الإسلام، ولو جعل نكايته مع المسلمين على المشركين لكان خيرًا له، ولقدّمناه على غيره»، فجاءت الدعوة في أوانها وكان إسلامه هو الجواب.', 2, 85, 5, false, ''),
('rv8.u3.l6.6d', 'u3-l6', 'طلب خالد من النبي ﷺ أن يستغفر له عن ماضيه بعد إسلامه، فبمَ أجابه؟', 'الإسلام يمحو ما كان قبله.', 'أجابه النبي ﷺ أن الإسلام يجبّ ما قبله.', 1, 85, 6, false, ''),
('rv8.u3.l6.7', 'u3-l6', 'صحب خالد بن الوليد النبيَّ ﷺ مدة:', 'أسلم متأخرًا قبل فتح مكة.', 'صحب خالد بن الوليد النبي ﷺ مدة ثلاث سنوات.', 2, 85, 7, false, ''),
('rv8.u3.l6.8', 'u3-l6', 'أيّ الغزوات الآتية من أهم الغزوات التي شارك فيها خالد بن الوليد في عهد النبي ﷺ؟', 'بعد إسلامه وفي حياة النبي ﷺ.', 'من أهم الغزوات التي شارك فيها خالد في عهد النبي ﷺ: غزوة مؤتة، وغزوة حنين، وفتح مكة.', 2, 85, 8, false, ''),
('rv8.u3.l6.9', 'u3-l6', 'متى لقّب الرسول ﷺ خالد بن الوليد بـ «سيف الله»؟', 'معركة مع الروم.', 'لقّبه بسيف الله عند رجوعه بالجيش من معركة مؤتة التي كانت مع الروم.', 1, 85, 9, false, ''),
('rv8.u3.l6.10', 'u3-l6', 'لماذا رأى النبي ﷺ في انسحاب خالد من معركة مؤتة عبقرية فذّة؟', 'الانسحاب الناجح من أمام جيش أكبر.', 'لأنه استطاع وقف الخسائر، وحفظ أرواح المسلمين من جيش الروم في وقت كان فيه الانسحاب مستحيلًا.', 2, 86, 10, false, ''),
('rv8.u3.l6.11', 'u3-l6', 'ما دلالة تسمية خالد بن الوليد «سيف الله»؟', 'تشبيه بالسيف في الحق.', 'أي كالسيف أسلّه الله على الكافرين، فقد كان لا يخشى في الله لومة لائم، ويقاتل لرفع راية الإسلام، وفيه إشادة بمهارته ونبوغه وحنكته العسكرية؛ ولم يخض معركة تحت لواء الإسلام إلا وانتصر فيها.', 1, 86, 11, false, ''),
('rv8.u3.l6.13', 'u3-l6', 'أيٌّ مما يأتي من الإنجازات التي حققها خالد بن الوليد بعد عهد الرسول ﷺ؟', 'بعد وفاة النبي ﷺ.', 'من إنجازاته بعد عهد الرسول ﷺ: هزيمة المرتدين في عهد أبي بكر الصديق، وهزيمة الفرس والروم، والمشاركة في الفتوحات الكبرى التي بها تم صون الإسلام في جزيرة العرب.', 2, 86, 12, false, ''),
('rv8.u3.l6.14', 'u3-l6', 'ما الخطة العسكرية التي وضعها خالد بن الوليد لإنقاذ جيش المسلمين في معركة مؤتة؟', 'خطة لإيهام العدو بوصول مدد.', 'بدّل أماكن الجنود، فجعل الميمنة مكان الميسرة والعكس، والمقدمة مؤخرة والعكس، وأمر مجموعة من الجنود بالخروج ليلًا خلف الجبال ليعودوا فجرًا مثيرين للغبار رافعين أصواتهم بالتكبير والتهليل، فيظن الروم أن مددًا قد أتى للمسلمين.', 2, 86, 13, false, ''),
('rv8.u3.l6.17', 'u3-l6', 'لماذا لم يتبع جيش الروم المسلمين عندما انسحبوا في مؤتة؟', 'خطة خالد أوهمتهم بأن المسلمين ينوون الهجوم.', 'لأنهم لم يتوقعوا أن ذلك كان انسحابًا، فقد ظنوا أنه كمين صنعه خالد لهم.', 2, 86, 14, false, ''),
('rv8.u3.l6.18', 'u3-l6', 'أيٌّ مما يأتي من نتائج خطة خالد بن الوليد يوم مؤتة؟', 'الخطة حققت انسحابًا آمنًا.', 'من نتائج الخطة: أوقع الرعب في قلوب الروم، وأوهمهم أنه لا ينوي الانسحاب بل الهجوم، وانسحب جيش المسلمين في الوقت المناسب، ووقف الخسائر في جيش الإسلام والخروج بهم سالمين.', 1, 87, 15, false, ''),
('rv8.u3.l6.20', 'u3-l6', 'كيف كانت وفاة خالد بن الوليد رضي الله عنه؟', 'رغم كثرة معاركه.', 'لم يمت في ساحة المعركة، بل توفي على فراش المرض؛ وتلك حكمة الله تعالى، فلو قُتل في ساحة القتال لقيل: سقط سيف الله الذي سلّه على المشركين، وهذا سيترك أثرًا في نفوس المسلمين.', 1, 87, 16, false, ''),
('rv8.u3.l6.21', 'u3-l6', 'ما العبرة من وفاة خالد بن الوليد رضي الله عنه على فراش المرض مع كثرة مشاركته في المعارك؟', 'الأجل لا يتقدم ولا يتأخر.', 'الكل صائر إلى الموت، ولا ينجيه من ذلك شيء، وسواء جاهد أم لم يجاهد فإن له أجلًا محتومًا، فالله تعالى قدّر لكل إنسان ساعة ومكان وكيفية وفاته.', 1, 88, 17, false, ''),
('rv8.u3.l6.23', 'u3-l6', 'كان خالد رضي الله عنه يرى أن ثبات الجيش من أهم عوامل النصر. ماذا فعل في غزوة اليرموك ليعزّز ثبات الجنود؟', 'جعل وراء الجيش من يمنع الفرار.', 'قام بإعطاء أمر لأبي عبيدة بالرجوع إلى نهاية الجيش بعد أن كان في قلب المركز، والهدف من ذلك استحياء المنهزم ورجوعه إلى القتال عند رؤيته هناك، كما أمر النساء خلف الجيش بحثّ الرجال على الثبات.', 3, 88, 18, false, ''),
('rv8.u3.l6.24a', 'u3-l6', 'أين تجد معنى «الرجوع إلى الحق خير من التمادي في الباطل» في سيرة خالد بن الوليد؟', 'التحوّل في حياته.', 'على الرغم من نفرة خالد من الإسلام في بداية الأمر فإن هذا الأمر تبدّل، فقد راجع نفسه وأعاد النظر في مجريات الأحداث، فرجع إلى الحق وأسلم.', 1, 88, 19, false, ''),
('rv8.u3.l6.24b', 'u3-l6', 'أين تجد معنى «قوة تأثير الكلمة في النفس» في سيرة خالد بن الوليد؟', 'رسالة أخيه.', 'كان لكلمات الحوار الذي دار بين النبي ﷺ والوليد أخي خالد أثر كبير في فكر خالد وتأثّره وعودته إلى الحق.', 2, 88, 20, false, ''),
('rv8.u3.l7.2', 'u3-l7', 'ما المقصود بالأمن؟', 'ضدّه الخوف.', 'الأمن: الاطمئنان النفسي والاستقرار والسكينة التي يشعر بها الفرد والمجتمع، وضدها الخوف.', 1, 89, 1, false, ''),
('rv8.u3.l7.3', 'u3-l7', 'لماذا يُعدّ تحقق الأمن مطلبًا أساسيًّا وضرورة من ضروريات الحياة؟', 'بدون الأمن لا تقوم المصالح ولا الحضارات.', 'تحقق الأمن مطلب أساسي لأن مصالح العباد لا تتحقق إلا بوجوده، ولأنه يؤدي إلى الاطمئنان النفسي والاستقرار، ولأن الحضارات لا تزدهر إلا بانتشاره.', 1, 89, 2, false, ''),
('rv8.u3.l7.5', 'u3-l7', 'ماذا تستنتج من قوله تعالى: ﴿وضرب الله مثلا قرية كانت آمنة مطمئنة ... فكفرت بأنعم الله فأذاقها الله لباس الجوع والخوف﴾؟', 'تبدّل حال القرية بعد كفرها بالنعم.', 'دلت الآية على أنه كما كان الأمن من بعد الخوف مثوبة للمؤمنين، فالخوف بلاء عظيم، وكان عقابًا لبعض الأمم عندما كفرت.', 2, 89, 3, false, ''),
('rv8.u3.l7.6', 'u3-l7', 'ما دلالة تقديم طلب الأمن على طلب الرزق في دعاء إبراهيم عليه السلام: ﴿رب اجعل هذا بلدا آمنا وارزق أهله من الثمرات﴾؟', 'هل يستطيع الخائف أن يطلب رزقه أو يستمتع به؟', 'لأن الأمن إذا استتب وشاع بين الناس انطلقوا في اطمئنان لكسب رزقهم وتدبير أمور حياتهم، ولأنه لا يمكن التلذذ بالطعام وسائر أنواع الرزق مع الخوف والقلق.', 2, 90, 4, false, ''),
('rv8.u3.l7.7', 'u3-l7', 'ما أثر الأمن في مجتمع المدينة المنورة على الدعوة الإسلامية؟', 'الأمن أساس الاستقرار.', 'أصبحت المدينة المنورة بانتشار الأمن ملاذًا آمنًا للمسلمين، اجتمعت فيه نفوسهم، وتآلفت قلوبهم، فأقاموا شعائرهم مطمئنين، وأصبحوا قوة لا يستهان بها.', 1, 90, 5, false, ''),
('rv8.u3.l7.8a', 'u3-l7', 'بنى النبي ﷺ المسجد النبوي لتوحيد صفوف المسلمين. ما الأمن الذي حققه ذلك؟', 'المسجد مكان العبادة.', 'بنى النبي ﷺ المسجد النبوي لتوحيد صفوف المسلمين، حتى يأمن الناس في تأدية العبادات على أرواحهم.', 2, 90, 6, false, ''),
('rv8.u3.l7.8b', 'u3-l7', 'آخى النبي ﷺ بين المهاجرين والأنصار. ما نوع الأمن الذي حققه ذلك؟', 'المؤاخاة علاقة بين الناس.', 'آخى النبي ﷺ بين المهاجرين والأنصار لتحقيق الأمن الاجتماعي.', 1, 90, 7, false, ''),
('rv8.u3.l7.8c', 'u3-l7', 'أنشأ النبي ﷺ سوق المدينة. ما نوع الأمن الذي حققه ذلك؟', 'السوق للتجارة.', 'أنشأ النبي ﷺ سوق المدينة لتحقيق الأمن الاقتصادي.', 1, 90, 8, false, ''),
('rv8.u3.l7.8d', 'u3-l7', 'أصدر النبي ﷺ وثيقة المدينة المنورة التي نظّمت العلاقات بين جميع الطوائف. ما الذي حققته؟', 'وثيقة لتنظيم العلاقات.', 'أصدر النبي ﷺ وثيقة المدينة التي نظمت العلاقات بين جميع الطوائف لتحقيق الأمن السياسي والاجتماعي، وقد نص أحد بنودها صراحة على حق التمتع بالأمن لجميع ساكنيها إلا من أثم وظلم.', 2, 90, 9, false, ''),
('rv8.u3.l7.10', 'u3-l7', 'الأمن مبدأ في حياته ﷺ. كيف تجلّى ذلك يوم فتح مكة؟', 'فتح لأهل مكة باب الأمان واسعًا.', 'عندما عاد ﷺ إلى مكة فاتحًا لم يبادل أهلها ظلمًا بظلم، ولا إرهابًا بإرهاب، وإنما فتح لأهل مكة باب الأمان واسعًا، فأعلن: «من دخل دار أبي سفيان فهو آمن، ومن ألقى السلاح فهو آمن، ومن أغلق بابه فهو آمن»، فكانت النتيجة: دخل الناس في دين الله أفواجًا.', 2, 91, 10, false, ''),
('rv8.u3.l7.11', 'u3-l7', 'ماذا تستنتج من حديث النبي ﷺ: «من أصبح منكم آمنًا في سربه، معافى في جسده، عنده قوت يومه، فكأنما حيزت له الدنيا»؟', 'بدأ الحديث بالأمن.', 'نستنتج أن تحقق الأمن أول النعم التي يحوز بها الإنسان السعادة في الدنيا، بل جعلها ﷺ في الحديث بمنزلة من ملك الدنيا بأسرها.', 1, 91, 11, false, ''),
('rv8.u3.l7.14a', 'u3-l7', 'امتنّ الله تعالى على قريش في قوله: ﴿الذي أطعمهم من جوع وآمنهم من خوف﴾ بنعمتي:', '«أطعمهم» و«آمنهم».', 'امتن الله تعالى على قريش بنعمتي الإطعام والأمن.', 1, 91, 12, false, ''),
('rv8.u3.l7.16-1', 'u3-l7', 'ما التوجيه الذي يهدف إلى تحقيق الأمن في قوله تعالى: ﴿يا أيها الذين آمنوا أطيعوا الله وأطيعوا الرسول وأولي الأمر منكم﴾؟', '«أطيعوا».', 'تدل الآية على وجوب طاعة الله ورسوله وأولي الأمر.', 1, 92, 13, false, ''),
('rv8.u3.l7.16-2', 'u3-l7', 'ما التوجيه الذي يهدف إلى تحقيق الأمن في قوله تعالى: ﴿ولا تنازعوا فتفشلوا وتذهب ريحكم﴾؟', '«ولا تنازعوا».', 'تدل الآية على الوحدة والتلاحم ونبذ الخلاف.', 1, 92, 14, false, ''),
('rv8.u3.l7.16-4', 'u3-l7', 'ما التوجيه الذي يهدف إلى تحقيق الأمن في قوله ﷺ: «لا يحل لمسلم أن يروّع مسلمًا»؟', '«يروّع».', 'يدل الحديث على حرمة ترويع المسلم بأي صورة كانت.', 1, 92, 15, false, ''),
('rv8.u3.l7.16-5', 'u3-l7', 'ما التوجيه الذي يهدف إلى تحقيق الأمن في قوله ﷺ: «كل المسلم على المسلم حرام: دمه وماله وعرضه»؟', 'الدم والمال والعرض.', 'يدل الحديث على حرمة الاعتداء على النفس والمال والعرض.', 1, 92, 16, false, ''),
('rv8.u3.l7.17b', 'u3-l7', 'بوصفك طالبًا، أيٌّ مما يأتي يسهم في تحقيق الأمن؟', 'الأمن مسؤولية مشتركة.', 'من دور الطالب: تجنب كل ما يهدد الأمن الشخصي، وتجنب نشر معلومات تضر بمصالح الوطن، والحذر من أساليب الابتزاز الإلكتروني، والمشاركة في حفظ الأمن، وتجنب إثارة التوتر والصراع، واحترام الآخرين والتعايش معهم بسلام.', 1, 93, 17, false, ''),
('rv8.u3.l7.18', 'u3-l7', 'أيٌّ مما يأتي من ثمرات انتشار الأمن والاستقرار في الوطن؟', 'الأمن يعود بالخير على كل جوانب الحياة.', 'من ثمرات الأمن: حركة الناس في المجتمع آمنة ومطمئنة، والأطفال يعيشون بأمن وسلام، والتعايش السلمي، وتجارة نشطة واقتصاد نامٍ، وتنشط السياحة دون خوف وقلق.', 1, 93, 18, false, ''),
('rv8.u3.l7.19-1', 'u3-l7', 'استجاب لرسائل التحريض التي وردت له عبر إحدى وسائل التواصل. قيّم تصرّفه:', 'التحريض يهدد الأمن.', 'ينبغي الحذر من هذه الرسائل وعدم الاستجابة لها، وإبلاغ الجهات المختصة عنها.', 1, 93, 19, false, ''),
('rv8.u3.l7.19-2', 'u3-l7', 'قاد سيارته برعونة تعبيرًا عن فرحته بفوز فريقه المفضل، مما أخاف مستخدمي الطريق. قيّم تصرّفه:', 'تذكّر: «لا يحل لمسلم أن يروّع مسلمًا».', 'ضرورة الالتزام بقواعد المرور، وتجنب إيذاء الآخرين.', 1, 93, 20, false, ''),
('rv8.u3.l7.19-3', 'u3-l7', 'لجأ إلى أخذ حقه بيده دون الاحتكام إلى الجهات المختصة. قيّم تصرّفه:', 'أخذ الحق باليد يفتح باب الفوضى.', 'ينبغي اللجوء للجهات المسؤولة عن ذلك، وتجنب فتح باب الثأر.', 1, 93, 21, false, ''),
('rv8.u4.l1.1', 'u4-l1', 'لماذا سُمّيت السورة الكريمة بصيغة الإفراد (العنكبوت)؟', 'فكّر في طريقة عيش العنكبوت: وحدها أم في جماعة؟', 'سُمّيت السورة بصيغة الإفراد للإشارة إلى الحياة الفردية للعنكبوت.', 1, 95, 1, false, ''),
('rv8.u4.l1.2a', 'u4-l1', 'من الحِكَم في ضرب الله تعالى الأمثال للناس في القرآن الكريم:', 'المثل يجعل الفكرة الصعبة أسهل وأقرب.', 'من حكم ضرب الأمثال تقريب المعاني إلى الأفهام، ومناقشة الخصوم المعاندين المكابرين، وتمثيل المعقولات بالمحسوسات.', 1, 95, 2, false, ''),
('rv8.u4.l1.2b', 'u4-l1', 'كيف تزيد الأمثال القرآنية المعاني وضوحًا وبيانًا؟', 'الأمر الذي لا نراه يُشبَّه بشيء نراه ونلمسه.', 'من حكم ضرب الأمثال تمثيل المعقولات بالمحسوسات، فيزيدها وضوحًا وبيانًا.', 2, 95, 3, false, ''),
('rv8.u4.l1.3a', 'u4-l1', 'في قوله تعالى: ﴿مَثَلُ الَّذِينَ اتَّخَذُوا مِن دُونِ اللَّهِ أَوْلِيَاءَ كَمَثَلِ الْعَنكَبُوتِ اتَّخَذَتْ بَيْتًا﴾، بماذا شُبِّه أولياء الكفار؟', 'الكفار شُبّهوا بالعنكبوت، فبماذا شُبّه ما اتخذوه؟', 'شبّه الله الكفار بالعنكبوت، وأولياؤهم أشبهوا بيت العنكبوت في الوهن والضعف.', 1, 95, 4, false, ''),
('rv8.u4.l1.3b', 'u4-l1', 'ما وجه الشبه بين أولياء الكفار وبيت العنكبوت؟', 'بيت العنكبوت لا يحمي من فيه.', 'أولياء الكفار أشبهوا بيت العنكبوت في الوهن والضعف؛ فلم يُغنوا عنهم من الله شيئًا.', 1, 95, 5, false, ''),
('rv8.u4.l1.3c', 'u4-l1', 'لماذا عبّر القرآن عن العنكبوت بصيغة التأنيث ﴿اتَّخَذَتْ بَيْتًا﴾؟', 'من الذي يقوم بالبناء عند العنكبوت؟', 'عبّر القرآن بصيغة التأنيث لأن أنثى العنكبوت هي التي تبني البيت وتغزل خيوطه.', 1, 95, 6, false, ''),
('rv8.u4.l1.3d', 'u4-l1', 'أيٌّ مما يأتي من مظاهر ضعف بيت العنكبوت من الناحية المادية؟', 'الناحية المادية تتعلق بالحماية من الطقس والأخطار.', 'من الناحية المادية: لا يدفع حرًّا ولا بردًا ولا ريحًا عاصفة ولا مطرًا هاطلًا، ويزول بأضعف تحريك. أما الخيانة والغدر فمن الناحية المعنوية.', 2, 95, 7, false, ''),
('rv8.u4.l1.3d2', 'u4-l1', 'بيت العنكبوت هشّ معنويًّا أيضًا؛ فأيُّ العبارات الآتية تصف ذلك؟', 'المقصود العلاقات بين من يسكنون البيت لا جدرانه.', 'من الناحية المعنوية: بيت العنكبوت أبعد البيوت عن صفة البيت، روابطه الأسرية والاجتماعية هشّة، تنعدم فيه أواصر القربى وتسوده الخيانة والغدر.', 2, 96, 8, false, ''),
('rv8.u4.l1.3e', 'u4-l1', 'ما نوع التشبيه الوارد في آية العنكبوت؟', 'شُبّهت صورة كاملة بصورة كاملة.', 'التشبيه الوارد في الآية الكريمة تشبيه تمثيلي.', 2, 96, 9, false, ''),
('rv8.u4.l1.14', 'u4-l1', 'من الأدلة على أن بيت العنكبوت تسوده الخيانة والغدر والقسوة:', 'الخيانة تكون بين أفراد البيت أنفسهم.', 'من الأدلة: أنثى العنكبوت تقتل ذكرها وتأكله، والأبناء يقتل بعضهم بعضًا، والبيت مصيدة لكل من يفكر في زيارته.', 2, 96, 10, false, ''),
('rv8.u4.l1.15', 'u4-l1', 'ما دلالة قوله تعالى: ﴿مِن دُونِهِ﴾ في الآية: ﴿إِنَّ اللَّهَ يَعْلَمُ مَا يَدْعُونَ مِن دُونِهِ مِن شَيْءٍ﴾؟', 'كلمة «دون» تدل على المنزلة الأقل.', 'تدل على دنو مرتبتها ومكانتها، فهي لحقارتها وقلة الاعتداد بها لا تُسمّى شيئًا.', 2, 96, 11, false, ''),
('rv8.u4.l1.16', 'u4-l1', 'كيف ميّزت الآيات الكريمة بين المؤمن والكافر؟', 'أحدهما يعتمد على القوي الغالب، والآخر على العاجز.', 'المؤمن يعبد الله تعالى القوي العزيز الغالب للأصنام ولعابديها، والكافر يعبد أصنامًا لا تنفع ولا تضر، تتصف بالوهن والضعف.', 1, 96, 12, false, ''),
('rv8.u4.l1.17a', 'u4-l1', 'في قوله تعالى: ﴿خَلَقَ اللَّهُ السَّمَاوَاتِ وَالْأَرْضَ بِالْحَقِّ﴾، ما مظهر قدرة الله تعالى الوارد فيها؟', 'انظر إلى ما ذكرته الآية من مخلوقات عظيمة.', 'من مظاهر قدرة الله: خلق السماوات السبع على علوها وارتفاعها وحسنها، وخلق الأرض وما فيها بالحق.', 1, 96, 13, false, ''),
('rv8.u4.l1.17b', 'u4-l1', 'ما الحكمة من خلق الله تعالى السماوات والأرض؟', 'الخلق يدلّ العباد على من يستحق العبادة.', 'خلق الله السماوات والأرض ليقوم أمره وشرعه، ويُري عباده قدرته وحكمته، ما يدلّهم أنه معبودهم الحق.', 2, 96, 14, false, ''),
('rv8.u4.l1.17c', 'u4-l1', 'ما موقف المؤمنين من مظاهر قدرة الله عز وجل؟', 'تفتحت بصائرهم واهتزت مشاعرهم.', 'المؤمنون تفتحت بصائرهم واهتزت مشاعرهم، وأدركوا أن قوة الله وحدها هي القوة، وولاية الله هي الولاية، وما عداها ضئيل هزيل.', 2, 97, 15, false, ''),
('rv8.u4.l1.18', 'u4-l1', 'ما دلالة تشبيه الإنسان بالحيوان والحشرات في القرآن الكريم؟', 'التشبيه هنا للذم لا للمدح.', 'فيه تصغير لشأن المشركين وتحقير اعتقادهم، وذم وإذلال وتنزيل لمرتبتهم.', 2, 97, 16, false, ''),
('rv8.u4.l1.19', 'u4-l1', 'ما موقف المؤمن والكافر من ضرب الأمثال في القرآن الكريم؟', 'أحدهما يتعلم منها، والآخر يعيبها.', 'المؤمن ينتفع بالأمثال ويستفيد منها ويأخذ الدروس والعبر والعظات، والكافر يسخر منها ويستهزئ ويعيب ضرب الأمثال.', 1, 97, 17, false, ''),
('rv8.u4.l1.20', 'u4-l1', 'كيف ردّ القرآن الكريم على استهزاء الكافرين بضرب الأمثال؟', 'تذكّر قوله تعالى: ﴿إِنَّ اللَّهَ لَا يَسْتَحْيِي أَن يَضْرِبَ مَثَلًا...﴾.', 'ردّ الله عليهم بأنه سبحانه لا يستنكف من ضرب الأمثال بما هو أصغر وأحقر، قال تعالى: ﴿إِنَّ اللَّهَ لَا يَسْتَحْيِي أَن يَضْرِبَ مَثَلًا مَّا بَعُوضَةً فَمَا فَوْقَهَا﴾.', 2, 97, 18, false, ''),
('rv8.u4.l1.21', 'u4-l1', 'مدحت الآيات الكريمة:', '﴿وَمَا يَعْقِلُهَا إِلَّا الْعَالِمُونَ﴾.', 'المدح لمن يتدبر الأمثال؛ لأنه من أهل العلم والفهم والإدراك، والذم لمن يستهزئ بالأمثال.', 1, 97, 19, false, ''),
('rv8.u4.l1.22a', 'u4-l1', 'ما دلالة التأكيد بـ(إنّ) في قوله تعالى: ﴿وَإِنَّ أَوْهَنَ الْبُيُوتِ لَبَيْتُ الْعَنكَبُوتِ﴾؟', 'التأكيد هنا يقوّي معنى الضعف.', 'التأكيد بـ(إنّ) للدلالة على أن أولياء المشركين في أنزل مراتب الضعف.', 2, 97, 20, false, ''),
('rv8.u4.l1.22b', 'u4-l1', 'ما الأسلوب المستخدم في كلمة ﴿أَوْهَنَ﴾ في قوله تعالى: ﴿وَإِنَّ أَوْهَنَ الْبُيُوتِ﴾؟', 'الكلمة على وزن «أفعل» وتعني: الأشد ضعفًا.', '﴿أَوْهَنَ﴾ أفعل تفضيل أُضيف إلى الجمع ﴿الْبُيُوتِ﴾، وأُتي بخبر إنّ باللام ﴿لَبَيْتُ﴾.', 3, 97, 21, false, ''),
('rv8.u4.l1.23', 'u4-l1', 'ما أثر اعتماد المؤمنين على الله تعالى؟', 'من اعتمد على الله فقد اعتمد على ركن شديد.', 'من اعتمد على الله فقد اعتمد على ركن شديد؛ يدافع عنهم وينصرهم، ويجدون عنده العزة، ويهديهم إلى ما تستقيم به حياتهم.', 1, 98, 22, false, ''),
('rv8.u4.l1.23b', 'u4-l1', 'ما وجه الربط بين مثل الذباب ومثل الذي يبسط كفّيه إلى الماء، ومثل العنكبوت؟', 'الأمثلة الثلاثة تتحدث عن معبودات من دون الله.', 'الآيتان تؤكدان عجز وضعف وعدم نفع ما اتُّخذ من دون الله تعالى، كما في مثل العنكبوت.', 2, 98, 23, false, ''),
('rv8.u4.l1.24', 'u4-l1', 'في تشبيه المشركين بالعنكبوت، ما وجه الشبه؟', 'المشركون أساؤوا اختيار ما يعتمدون عليه.', 'المشبَّه: المشركون، والمشبَّه به: العنكبوت، ووجه الشبه: ضعف العقول وسوء التدبير والاختيار.', 2, 98, 24, false, ''),
('rv8.u4.l1.26', 'u4-l1', 'نبّهت آية العنكبوت إلى أهمية صلاح الأسرة؛ فكيف يمكن تجنّب وقوع الفساد فيها؟', 'الأساس المتين يحمي البيت.', 'يمكن تجنّب الفساد بأن تُؤسَّس الأسرة على العقيدة الصحيحة، وغرس المحبة بين أفرادها، وتغليب المصلحة العامة، وتقوية أواصر المحبة.', 1, 98, 25, false, ''),
('rv8.u4.l2.1a', 'u4-l2', 'مَن راوي حديث: «ما ملأ آدميٌّ وعاءً شرًّا من بطن»؟', 'اسمه في أول سطر من الحديث في الدرس.', 'الحديث عن المقدام بن معدي كرب قال: سمعت رسول الله ﷺ يقول: «ما ملأ آدميٌّ وعاءً شرًّا من بطن...».', 2, 99, 1, false, ''),
('rv8.u4.l2.1b', 'u4-l2', 'أكمل الحديث الشريف: «حَسْبُ الآدميِّ لُقيماتٌ يُقِمن صُلبَه، فإن غلبت الآدميَّ نفسُه فـ...»', 'قُسّمت المعدة ثلاثة أقسام متساوية.', 'قال ﷺ: «فإن غلبت الآدميَّ نفسُه، فثلثٌ للطعام، وثلثٌ للشراب، وثلثٌ للنَّفَس».', 1, 99, 2, false, ''),
('rv8.u4.l2.2', 'u4-l2', 'لماذا يحتاج الإنسان إلى الطعام والشراب؟', 'الطعام يمدّ الإنسان بالطاقة ليقوم بواجباته.', 'يحتاج الإنسان إلى الطعام لينمو ويعيش ويتحرك ويعمل، فهو يمدّه بالطاقة، وهو مأمور بالحفاظ على صحته ليتسنى له القيام بواجباته، فيعبد الله ويعمر الأرض.', 1, 99, 3, false, ''),
('rv8.u4.l2.3', 'u4-l2', 'كيف يتعامل الإنسان مع نعمة الطعام والشراب؟', 'هل نعيش لنأكل أم نأكل لنعيش؟', 'يتعامل معهما على أنهما من أعظم النعم الإلهية، وأنهما وسيلتان لحفظ الحياة لا غايتان لها.', 1, 99, 4, false, ''),
('rv8.u4.l2.4', 'u4-l2', 'ما التوجيه النبوي في تناول الإنسان للطعام والشراب؟', 'لا إفراط ولا حرمان.', 'التوجيه النبوي هو الوسطية والاعتدال؛ فيكتفي بلقيمات، وهي القدر الذي يُذهب الجوع ويحفظ القوة، من غير إفراط ولا حرمان.', 1, 99, 5, false, ''),
('rv8.u4.l2.5', 'u4-l2', 'أيٌّ مما يأتي من الأضرار المعنوية لامتلاء المعدة بالطعام؟', 'الأضرار المعنوية تتعلق بالعقل والنشاط لا بأعضاء الجسم.', 'من الأضرار المعنوية: تبلّد الذهن، والغفلة، والكسل، وكثرة النوم الذي تضيع معه العبادات. أما ضغط الدم وتشحم الكبد فأضرار مادية.', 2, 99, 6, false, ''),
('rv8.u4.l2.6', 'u4-l2', 'في قوله تعالى: ﴿وَالَّذِينَ كَفَرُوا يَتَمَتَّعُونَ وَيَأْكُلُونَ كَمَا تَأْكُلُ الْأَنْعَامُ﴾، ماذا عاب الله على الكفار؟', 'شبّههم الله بالأنعام في همّهم وغايتهم.', 'عاب الله تعالى على الكفار أنهم جعلوا جُلّ همّهم ومقصدهم التمتع بملذات الدنيا كالطعام، وشبّههم بالأنعام.', 2, 99, 7, false, ''),
('rv8.u4.l2.7', 'u4-l2', 'علّل: جاء التعبير النبوي بكلمة (لُقيمات).', 'صيغة «لُقيمات» تدل على الصِّغَر.', 'جاء التعبير بـ(لُقيمات) استحبابًا لتصغير ما يحمله الآكل من الطعام في يده.', 2, 100, 8, false, ''),
('rv8.u4.l2.8', 'u4-l2', 'اهتمام الحديث الشريف حتى بحجم اللقمة يدلّ على:', 'الإسلام يهذّب سلوك المسلم وسَمْته حتى على مائدة الطعام.', 'يدل التعبير بـ(لُقيمات) على عناية الإسلام وضبطه لأدق التفاصيل للارتقاء بسلوك المسلم وسَمْته وهو على موائد الطعام والشراب.', 2, 100, 9, false, ''),
('rv8.u4.l2.9', 'u4-l2', 'كيف يتوافق الحديث النبوي مع الطب الوقائي؟', 'الطب الوقائي يهتم بدفع المرض قبل وقوعه.', 'الطب الوقائي يُعنى بوضع القواعد الأولية لدفع الأمراض قبل وقوعها، وكذلك الحديث وضع قاعدة تنظم تناول الطعام والشراب وكمياته بما يحفظ الصحة ويجنّب الأمراض.', 2, 100, 10, false, ''),
('rv8.u4.l2.10', 'u4-l2', 'لماذا خصّ النبي ﷺ النَّفَس بالذكر في الحديث؟', 'فكّر في العضو المسؤول عن التنفس.', 'خصّ النبي ﷺ النَّفَس بالذكر لأن الرئة تحتاج إلى مساحة للتنفس، وامتلاء البطن يقلل من أدائها.', 2, 100, 11, false, ''),
('rv8.u4.l2.11', 'u4-l2', 'إذا احتاج الإنسان إلى الزيادة في الطعام فقسّمه أثلاثًا، فما المقياس الدقيق لتحديد الثلث؟', 'يختلف الناس في حاجاتهم.', 'ثلث لطعامه وثلث لشرابه وثلث لنفَسه، ولا يوجد مقياس دقيق لتحديد الثلث؛ يقدّر ذلك الإنسان بنفسه: القدر الذي يُذهب الجوع ويحفظ القوة من غير إفراط ولا تفريط.', 2, 100, 12, false, ''),
('rv8.u4.l2.12', 'u4-l2', 'ما المقصود بالمقولة: «المعدة بيت الداء، والحِمية رأس الدواء»؟', 'من أين تبدأ كثير من الأمراض؟', 'من أسباب الإصابة بالأمراض ملء المعدة بالأطعمة غير الصحية وعدم الاعتدال في الطعام والشراب، لذا يجب اتباع نظام غذائي معتدل للمحافظة على صحتنا.', 2, 100, 13, false, ''),
('rv8.u4.l2.13', 'u4-l2', 'كيف تُحسّن كلمة (لُقيمات) في الحديث النبوي عاداتك الغذائية؟', 'الكلمة تدل على القِلّة والصِّغَر.', 'أحرص على تعديل عاداتي الغذائية، فأصغّر لقمتي، وأكتفي من الطعام قدر حاجتي، وبما يحفظ صحتي دون إفراط ولا حرمان.', 1, 100, 14, false, ''),
('rv8.u4.l2.14', 'u4-l2', 'يلجأ بعضهم إلى العقاقير أو التدخل الجراحي خيارًا أول لحل مشكلة السمنة؛ ما توجيهك له؟', 'هذه الحلول لا تخلو من مضاعفات قد تعرّض حياته للخطر.', 'عليه الحذر وتجنب مثل هذه الحلول، واللجوء إليها كحل أخير إن لزم الأمر وبمشورة طبية موثوقة، وعليه أولًا الالتزام بالهدي النبوي في طعامه وشرابه.', 2, 101, 15, false, ''),
('rv8.u4.l2.15a', 'u4-l2', 'لجأ أحدهم إلى حِمية غذائية قاسية أثّرت في صحته؛ ما التصرف الصحيح؟', 'لا يعرّض نفسه للهلاك.', 'عليه الاعتدال في تطبيق الحمية، وعدم تعريض نفسه للهلاك، فيسأل المختصين قبل الشروع في نظام حميته.', 1, 101, 16, false, ''),
('rv8.u4.l2.15b', 'u4-l2', 'أثقل معدته عند الإفطار في رمضان فتكاسل عن الصلاة؛ ما التصرف الصحيح؟', 'تذكّر بماذا كان النبي ﷺ يبدأ إفطاره.', 'عليه أن يرأف بنفسه وألا يثقل معدته بالطعام، والالتزام بالهدي النبوي في الإفطار على تمرات وماء.', 1, 101, 17, false, ''),
('rv8.u4.l2.15c', 'u4-l2', 'تحرص على كمية الطعام لا على نوعه؛ ما التوجيه الصحيح لها؟', 'العبرة ليست بالكمية وحدها.', 'عليها الحرص على اختيار الأطعمة الصحية التي تقيها من الأمراض وتعزز مناعة بدنها؛ فليست العبرة بكمية الطعام، وإنما بنوع ما تأكله.', 1, 101, 18, false, ''),
('rv8.u4.l2.15d', 'u4-l2', 'أهملت غذاءها في فترة الاختبارات فأصيبت بهبوط في الضغط وفقر في الدم؛ ما التوجيه الصحيح؟', 'الجسم السليم يساعد على المذاكرة.', 'ينبغي عليها الاهتمام بتغذيتها وصحتها؛ فالدراسة ليست عذرًا لإهمال صحتها، بل الاهتمام بالتغذية من معينات المذاكرة الجيدة.', 1, 101, 19, false, ''),
('rv8.u4.l2.16', 'u4-l2', 'أيٌّ مما يأتي من أسباب مشكلة السمنة والزيادة المفرطة في الوزن؟', 'ثلاثة من الخيارات حلول للمشكلة لا أسباب لها.', 'من أسباب السمنة: الإفراط في تناول الطعام والشراب، وعدم ممارسة الرياضة، وتناول الوجبات السريعة، والنوم بعد الأكل مباشرة.', 1, 102, 20, false, ''),
('rv8.u4.l3.1', 'u4-l3', 'ما معنى اسم الله تعالى (الغني)؟', 'غناه تعالى كامل لا نقص فيه.', 'الغني هو الذي لا يحتاج إلى أحد في شيء، وكل أحد يحتاج إليه.', 1, 103, 1, false, ''),
('rv8.u4.l3.2', 'u4-l3', 'ما معنى أن صفة الغنى من صفات ذات الله سبحانه وتعالى؟', 'صفات الذات ملازمة لا تنفصل.', 'صفة الذات هي التي لا تنفك عن ذاته، ولا يمكن أن تزول، فغنى الله تعالى دائم، لا يطرأ عليه ما ينافيه من الذل والحاجة.', 2, 103, 2, false, ''),
('rv8.u4.l3.3', 'u4-l3', 'لماذا كان وصف الله تعالى بضدّ صفة الغنى من المستحيلات عليه؟', 'هل يجوز النقص أو العجز في حق الله؟', 'لأن الحاجة نقص، والمحتاج عاجز، وللمحتاج إليه فضل عليه، والنقص منفيّ عن الله تعالى، والعجز غير جائز في حقه، ولا يمكن أن يكون لأحد فضل عليه.', 2, 103, 3, false, ''),
('rv8.u4.l3.4', 'u4-l3', 'أيّ الآيات الآتية يُستشهد بها على اسم الله (الغني)؟', 'ابحث عن الآية التي ورد فيها الاسم صراحة.', 'قال تعالى: ﴿إِنَّ اللَّهَ هُوَ الْغَنِيُّ الْحَمِيدُ﴾.', 1, 103, 4, false, ''),
('rv8.u4.l3.5', 'u4-l3', 'اقترن اسم الله (الغني) في القرآن الكريم بأسماء أخرى؛ أيّ مجموعة تضم هذه الأسماء؟', 'منها: ﴿إِنَّ اللَّهَ هُوَ الْغَنِيُّ الْحَمِيدُ﴾.', 'اقترن اسم الغني بأسماء: الغني الحميد، الغني ذو الرحمة، غني كريم، غني حليم.', 2, 103, 5, false, ''),
('rv8.u4.l3.6', 'u4-l3', 'ما دلالة اقتران اسم الله (الغني) باسمه (الحميد)؟', 'الغني عن عباده هو أيضًا المحسن إليهم.', 'يدل على أنه مع غناه عن عباده وعدم حاجته إليهم، فإنه يعاملهم معاملة يحمدونه عليها، فهو يحسن إليهم.', 2, 103, 6, false, ''),
('rv8.u4.l3.7', 'u4-l3', 'وضّح العبارة: «من كمال غناه أنه لم يتخذ صاحبة ولا ولدًا ولا شريكًا ولا وليًّا».', 'الإنسان يحتاج إلى الأولاد ليتكثر بهم ويتقوى.', 'لأن الحاجة إلى الزوجة نقص، والله تعالى غير محتاج لغيره، والإنسان يحتاج إلى الأولاد ليتكثر بهم ويتقوى، والله تعالى ليس بحاجة إلى ذلك.', 2, 103, 7, false, ''),
('rv8.u4.l3.8', 'u4-l3', 'لماذا خلق الله تعالى الخلق؟', '﴿وَمَا خَلَقْتُ الْجِنَّ وَالْإِنسَ إِلَّا...﴾.', 'خلقهم لعبادته، لا ليستكثر بهم من قلة، ولا ليستقوي بهم من ضعف، ولا ليرزقوه، قال تعالى: ﴿وَمَا خَلَقْتُ الْجِنَّ وَالْإِنسَ إِلَّا لِيَعْبُدُونِ﴾.', 1, 103, 8, false, ''),
('rv8.u4.l3.10', 'u4-l3', 'هل ينتفع الله تعالى بعبادة خلقه، أو تضره معصيتهم؟', '﴿إِن تَكْفُرُوا أَنتُمْ وَمَن فِي الْأَرْضِ جَمِيعًا فَإِنَّ اللَّهَ لَغَنِيٌّ حَمِيدٌ﴾.', 'لا تنفعه عبادتهم ولا تضره معصيتهم، ولا يأبه لكفرهم، قال تعالى: ﴿إِن تَكْفُرُوا أَنتُمْ وَمَن فِي الْأَرْضِ جَمِيعًا فَإِنَّ اللَّهَ لَغَنِيٌّ حَمِيدٌ﴾.', 1, 104, 9, false, ''),
('rv8.u4.l3.11', 'u4-l3', 'من مظاهر غنى الله تعالى ما يبسطه لأهل الجنة من نعيم؛ كيف وُصف هذا النعيم؟', 'لا يمكن للإنسان أن يتخيله.', 'في الجنة من النعيم والتكريم للمؤمنين ما لا عين رأت، ولا أذن سمعت، ولا خطر على قلب بشر.', 1, 104, 10, false, ''),
('rv8.u4.l3.12', 'u4-l3', 'ما الذي يؤكده قوله تعالى: ﴿يَا أَيُّهَا النَّاسُ أَنتُمُ الْفُقَرَاءُ إِلَى اللَّهِ﴾؟', 'حتى الحاكم يحتاج إلى الأعوان والجنود.', 'الناس مهما كانوا أغنياء فهم بحاجة إلى بعضهم، ففقر المخلوق ذاتي، لا يمكن أن يكون معه الاستغناء التام من كل وجه؛ فالسلطان لا يقوم سلطانه إلا بالحاجة إلى الأعوان والأنصار والجنود.', 2, 104, 11, false, ''),
('rv8.u4.l3.13', 'u4-l3', 'ما معنى قوله تعالى: ﴿لِّيَتَّخِذَ بَعْضُهُم بَعْضًا سُخْرِيًّا﴾؟', 'الكلمة هنا من التسخير والخدمة لا من السخرية.', 'أي ليسخّر بعضهم بعضًا في الأعمال والمعاش، فهذا يقدم خدمة لهذا، وهذا يعود عليه بما في يديه من فضل.', 2, 104, 12, false, ''),
('rv8.u4.l3.14', 'u4-l3', 'ما المقصود بالعبارة: «فاستغناؤهم بالله لا عنه»؟', 'كلما زاد افتقار العبد إلى ربه زاد عزّه به.', 'المقصود أن أفقر الناس إلى الله تعالى أغناهم به، وأذلهم له أعزهم به، وأضعفهم بين يديه أقواهم به، فالغنى بالله مع الفقر إليه متلازمان.', 3, 104, 13, false, ''),
('rv8.u4.l3.15', 'u4-l3', 'فيمن نزل قوله تعالى: ﴿لَّقَدْ سَمِعَ اللَّهُ قَوْلَ الَّذِينَ قَالُوا إِنَّ اللَّهَ فَقِيرٌ وَنَحْنُ أَغْنِيَاءُ﴾؟', 'قالوا: لو كان غنيًّا ما استقرض أموالنا.', 'نزلت في اليهود حين نزل قوله تعالى: ﴿مَّن ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا﴾ فقالوا: إن الله فقير يستقرضنا ونحن أغنياء.', 2, 104, 14, false, ''),
('rv8.u4.l3.17a', 'u4-l3', 'ما أثر الإيمان باسم الله الغني المستنتج من قوله تعالى: ﴿قَوْلٌ مَّعْرُوفٌ وَمَغْفِرَةٌ خَيْرٌ مِّن صَدَقَةٍ يَتْبَعُهَا أَذًى﴾؟', 'الآية تتحدث عن طريقة إعطاء الصدقة.', 'تدل الآية على التلطف عند التصدق وتجنب المنّ والأذى، والله غني حليم.', 1, 105, 15, false, ''),
('rv8.u4.l3.17b', 'u4-l3', 'ما أثر الإيمان باسم الله الغني المستنتج من قوله تعالى: ﴿وَمَن شَكَرَ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِ وَمَن كَفَرَ فَإِنَّ رَبِّي غَنِيٌّ كَرِيمٌ﴾؟', 'الكلمة المفتاحية في أول الآية.', 'تدل الآية على شكر الله تعالى؛ فمن شكر فإنما يشكر لنفسه، والله غني كريم.', 1, 105, 16, false, ''),
('rv8.u4.l3.17c', 'u4-l3', 'ما أثر الإيمان باسم الله الغني المستنتج من قوله تعالى: ﴿فَمِنكُم مَّن يَبْخَلُ وَمَن يَبْخَلْ فَإِنَّمَا يَبْخَلُ عَن نَّفْسِهِ وَاللَّهُ الْغَنِيُّ وَأَنتُمُ الْفُقَرَاءُ﴾؟', 'الآية تدعو إلى الإنفاق في سبيل الله.', 'تدل الآية على ترك البخل والشح؛ فمن يبخل فإنما يبخل عن نفسه، والله الغني وأنتم الفقراء.', 1, 105, 17, false, ''),
('rv8.u4.l3.17d', 'u4-l3', 'شكا الناس للنبي ﷺ قحوط المطر، فدعا: «اللهم أنت الله لا إله إلا أنت الغني ونحن الفقراء، أنزل علينا الغيث». ما الأثر المستنتج؟', 'النبي ﷺ سأل ربه بهذا الاسم.', 'يدل الحديث على الدعاء والتوسل باسم الله الغني.', 1, 105, 18, false, ''),
('rv8.u4.l3.17e', 'u4-l3', 'ما أثر الإيمان باسم الله الغني المستنتج من قوله ﷺ: «مَن يستعفف يُعِفَّه الله، ومن يستغنِ يُغنِه الله»؟', 'يستعفف: يكفّ نفسه عن سؤال الناس.', 'يدل الحديث على الاستعفاف عمّا في أيدي الناس.', 1, 105, 19, false, ''),
('rv8.u4.l3.18a', 'u4-l3', 'صفة الغنى في حق الخلق مكتسبة، بينما هي في حق الله تعالى:', 'تذكّر معنى صفات الذات.', 'صفة الغنى في حق الخلق مكتسبة، بينما هي في حق الله تعالى ذاتية.', 1, 106, 20, false, ''),
('rv8.u4.l3.18b', 'u4-l3', 'قال تعالى: ﴿مَا عِندَكُمْ يَنفَدُ وَمَا عِندَ اللَّهِ بَاقٍ﴾؛ تشير الآية إلى أن غنى الله تعالى:', '﴿بَاقٍ﴾ عكس ﴿يَنفَدُ﴾.', 'تشير الآية إلى أن غنى الله تعالى دائم لا يفنى.', 1, 106, 21, false, ''),
('rv8.u4.l3.18c', 'u4-l3', 'قال تعالى: ﴿وَمَا بِكُم مِّن نِّعْمَةٍ فَمِنَ اللَّهِ﴾؛ توجه الآية إلى عدم اغترار الإنسان بما عنده، لأن المالك الحقيقي له هو:', 'من أين تأتي كل نعمة؟', 'توجه الآية إلى عدم اغترار الإنسان بما عنده؛ لأن المالك الحقيقي له هو الله تعالى.', 1, 106, 22, false, ''),
('rv8.u4.l3.18m1', 'u4-l3', 'أيّ التصرفات الآتية صحيح في ضوء الإيمان باسم الله الغني؟', 'المؤمن بالله الغني يلجأ إليه دائمًا.', 'تصرف صحيح؛ فالمؤمن بالله الغني يدعوه ويلجأ إليه دائمًا، كمن يقول: «اللهم اكفني بحلالك عن حرامك، وأغنني بفضلك عمّن سواك»، يسأله من واسع رزقه الحلال الطيب.', 1, 106, 23, false, ''),
('rv8.u4.l3.18m2', 'u4-l3', 'قالت: «لن أتصدق من أموالي، أخشى أن تنقص». بماذا تقيّم تصرفها؟', 'الله وعد المتصدق بالخلف.', 'تصرف خاطئ؛ فمن آمن بالله تعالى الغني لم يخشَ على ماله النقص من الصدقة، فالله أمر بها، ووعد بالخلف على المتصدق.', 1, 106, 24, false, ''),
('rv8.u4.l4.1', 'u4-l4', 'بماذا خصّ الله تعالى البيت الحرام؟', 'القلوب تشتاق إليه.', 'خصّ الله تعالى البيت الحرام بالتعظيم والتوقير وانجذاب القلوب إليه.', 1, 107, 1, false, ''),
('rv8.u4.l4.2', 'u4-l4', 'كيف كرّم الله تعالى البيت الحرام؟', '﴿فَاجْعَلْ أَفْئِدَةً مِّنَ النَّاسِ تَهْوِي إِلَيْهِمْ﴾.', 'كرّمه بأن جعل أفئدة الناس تهوي إليه، وتتعهده بالزيارة والعمارة من وقت إلى آخر.', 1, 107, 2, false, ''),
('rv8.u4.l4.3', 'u4-l4', 'ما معنى العمرة؟', 'الكلمة مأخوذة من الاعتمار، وهو الزيارة.', 'العمرة اسم مأخوذ من الاعتمار، وتعني الزيارة، أي زيارة بيت الله الحرام وعمارته بمناسك مخصوصة.', 1, 107, 3, false, ''),
('rv8.u4.l4.4', 'u4-l4', 'ما الدليل من القرآن الكريم على مشروعية العمرة؟', 'الآية تذكر العمرة بلفظها.', 'ثبتت مشروعية العمرة بالقرآن والسنة والإجماع، قال تعالى: ﴿وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ﴾، وثبت أنه ﷺ اعتمر عدة مرات.', 1, 107, 4, false, ''),
('rv8.u4.l4.5', 'u4-l4', 'كم مرة تجب العمرة على المسلم؟', 'مثل الحج في عدد مرات الوجوب.', 'العمرة واجبة على المسلم البالغ العاقل المستطيع مرة واحدة في العمر.', 1, 107, 5, false, ''),
('rv8.u4.l4.6', 'u4-l4', 'علّل: تُسمّى العمرة بالحج الأصغر.', 'ما الركن الذي لا يكون إلا في الحج؟', 'تسمى العمرة بالحج الأصغر تمييزًا لها عن الحج الأكبر الذي لا يتم إلا بالوقوف بعرفة.', 2, 107, 6, false, ''),
('rv8.u4.l4.8', 'u4-l4', 'هل للعمرة وقت معيّن؟', 'العمرة موسّعة بخلاف الحج المضيّق زمانيًّا.', 'العمرة موسّعة غير مقيدة بعدد أو زمن، فتصح في جميع أيام العام، ويستثنى من ذلك الأيام التي تؤدى فيها شعائر الحج للحاج، من اليوم التاسع إلى آخر أعمال الحج.', 2, 107, 7, false, ''),
('rv8.u4.l4.9a', 'u4-l4', 'أكمل قول النبي ﷺ: «العمرةُ إلى العمرةِ ...»', 'العمرة سبب في غفران الذنوب.', 'قال رسول الله ﷺ: «العمرة إلى العمرة كفّارة لما بينهما»، ففي تكرار العمرة فضل كبير.', 1, 107, 8, false, ''),
('rv8.u4.l4.9b', 'u4-l4', 'ما فضل العمرة في شهر رمضان؟', 'ثوابها يعدل ثواب عبادة أكبر منها.', 'العمرة سبب في غفران الذنوب، وعمرة رمضان تعدل حجة في الثواب.', 1, 107, 9, false, ''),
('rv8.u4.l4.10', 'u4-l4', 'ما الترتيب الصحيح لأعمال العمرة؟', 'يبدأ المعتمر بالدخول في النسك، وينتهي بالحلق أو التقصير.', 'أعمال العمرة: الإحرام، ثم الطواف، ثم السعي، ثم التحلل بالحلق أو التقصير.', 1, 108, 10, false, ''),
('rv8.u4.l4.11a', 'u4-l4', 'الإحرام هو الدخول في نسك العمرة، فبمَ ينعقد؟', 'يكون في القلب وعلى اللسان.', 'الإحرام هو الدخول في نسك العمرة، وينعقد بالنية والتلبية.', 1, 108, 11, false, ''),
('rv8.u4.l4.11b', 'u4-l4', 'ماذا يلبس المُحرِم في الإحرام؟', 'الإزار والرداء خاصان بأحدهما.', 'يتجرد الرجل من اللباس المعتاد، فيلبس إزارًا ورداءً، وتبقى المرأة بملابسها العادية.', 1, 108, 12, false, ''),
('rv8.u4.l4.12', 'u4-l4', 'أين يكون الإحرام للعمرة لمن يسافر بالطائرة؟', 'لا يجوز تجاوز الميقات دون إحرام.', 'يكون الإحرام في المواقيت المكانية، أو ما يحاذيها قبل مجاوزة الميقات إذا كان مسافرًا بالطائرة.', 2, 108, 13, false, ''),
('rv8.u4.l4.13a', 'u4-l4', 'ما ميقات أهل المدينة المنورة؟', 'يُعرف اليوم باسم «أبيار علي».', 'ذو الحليفة (أبيار علي) ميقات أهل المدينة المنورة.', 2, 108, 14, false, ''),
('rv8.u4.l4.13b', 'u4-l4', 'ميقات (يلملم) هو ميقات أهل:', 'يقع جنوب مكة.', 'يلملم ميقات أهل اليمن، وذات عرق ميقات أهل العراق، وقرن المنازل ميقات أهل نجد، والجحفة ميقات أهل الشام.', 2, 108, 15, false, ''),
('rv8.u4.l4.13c', 'u4-l4', 'ميقات (قرن المنازل) ويُعرف بالسيل الكبير، هو ميقات أهل:', 'ليس ميقات اليمن ولا الشام.', 'قرن المنازل (السيل الكبير) ميقات أهل نجد.', 3, 108, 16, false, ''),
('rv8.u4.l4.13d', 'u4-l4', 'كم عدد المواقيت المكانية للحج والعمرة التي حددها النبي ﷺ؟', 'تذكّر جدول المواقيت المكانية في الدرس.', 'المواقيت المكانية للحج والعمرة التي حددها النبي ﷺ خمسة.', 1, 110, 17, false, ''),
('rv8.u4.l4.14', 'u4-l4', 'متى يُحرم المعتمر؟', 'يسبق الإحرامَ صلاة.', 'يُحرم المعتمر بعد صلاة مكتوبة أو نافلة.', 1, 108, 18, false, ''),
('rv8.u4.l4.15', 'u4-l4', 'علّل: تسمية الإحرام بهذا الاسم.', 'الكلمة من «التحريم».', 'سُمّي الإحرام بهذا الاسم لأن المُحرِم يَحرُم عليه بعض ما كان مباحًا له قبل إحرامه.', 2, 108, 19, false, ''),
('rv8.u4.l4.16a', 'u4-l4', 'الطواف ركن العمرة الأعظم؛ من أين يبدأ وأين ينتهي؟', 'يُقبّله المعتمر أو يشير إليه في بداية كل شوط.', 'الطواف هو الدوران حول الكعبة المشرفة بدءًا من الحجر الأسود وانتهاءً به، سبعة أشواط، يجعل فيها المعتمر الكعبة عن يساره.', 1, 108, 20, false, ''),
('rv8.u4.l4.16b', 'u4-l4', 'أيّ مما يأتي يُشترط للطواف ولا يُشترط للسعي؟', 'يجوز أن يسعى المعتمر وهو على غير وضوء.', 'يُشترط للطواف الطهارة، أما السعي فلا تشترط فيه الطهارة من الحدث الأصغر والأكبر.', 2, 108, 21, false, ''),
('rv8.u4.l4.16c', 'u4-l4', 'كيف يطوف المعتمر حول الكعبة؟', 'عدد الأشواط في الطواف مثل عددها في السعي.', 'الطواف سبعة أشواط، يجعل فيها المعتمر الكعبة عن يساره، ويلهج بالذكر والدعاء.', 1, 108, 22, false, ''),
('rv8.u4.l4.17a', 'u4-l4', 'ما الاضطباع؟', 'يتعلق بطريقة لبس الرداء.', 'الاضطباع من سنن الطواف للرجل: أن يجعل المُحرِم الرداء تحت إبطه الأيمن، ويردّ طرفيه على كتفه الأيسر.', 2, 109, 23, false, ''),
('rv8.u4.l4.17b', 'u4-l4', 'ما الرَّمَل في الطواف؟', 'يكون في بداية الطواف لا في كل أشواطه.', 'الرَّمَل: مقاربة الخطى مع إسراع المشي، ويكون في الأشواط الثلاثة الأولى من الطواف فقط، وهو سنة للرجل.', 2, 109, 24, false, ''),
('rv8.u4.l4.18', 'u4-l4', 'السعي سبعة أشواط بين الصفا والمروة؛ من أين يبدأ وأين ينتهي؟', '﴿إِنَّ الصَّفَا وَالْمَرْوَةَ مِن شَعَائِرِ اللَّهِ﴾ — بدأت الآية بأحدهما.', 'السعي هو التردد سبعة أشواط بين الصفا والمروة، يبدأ من الصفا وينتهي بالمروة.', 1, 109, 25, false, ''),
('rv8.u4.l4.19', 'u4-l4', 'ما سنّة السعي؟', 'تكون في مسافة محددة، وهي خاصة بالرجال.', 'يُسنّ في السعي الهرولة بين العلمين الأخضرين للرجل في الأشواط كلها، وهي للرجال فقط، أما الاضطباع فيُسنّ في الطواف.', 2, 109, 26, false, ''),
('rv8.u4.l4.20', 'u4-l4', 'كيف تتحلل المرأة من عمرتها؟', 'الحلق خاص بالرجل.', 'يتحلل الرجل بالحلق أو التقصير، أما المرأة فتقصّر شيئًا يسيرًا بمقدار أنملة أو أنملتين، أي ما يعادل ٢-٣ سم.', 1, 109, 27, false, ''),
('rv8.u4.l4.21', 'u4-l4', 'ماذا يقرر الدرس في سفر المرأة لأداء العمرة؟', 'تحتاج إلى مرافق من محارمها.', 'يجب على المرأة ألا تسافر لأداء العمرة إلا بوجود محرم لها.', 1, 109, 28, true, 'حكم سفر المرأة للعمرة دون محرم منشور كما ورد في الكتيّب؛ يحتاج إلى تأكيد معلّم للصياغة (Task 05 review item).'),
('rv8.u4.l4.22', 'u4-l4', 'ما محظور الإحرام المستنتج من قوله تعالى: ﴿فَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِي الْحَجِّ﴾؟', 'الفسوق هو المعاصي.', 'يستنتج من الآية أن من محظورات الإحرام: الجدال، وارتكاب المعاصي.', 1, 109, 29, false, ''),
('rv8.u4.l4.23', 'u4-l4', 'ما محظور الإحرام المستنتج من قوله ﷺ: «لا يَنكِحُ المحرمُ ولا يُنكِحُ ولا يخطُب»؟', 'الحديث عن عقد النكاح.', 'يحرم على المحرم الزواج والخطبة لنفسه أو لغيره.', 2, 109, 30, false, ''),
('rv8.u4.l4.24', 'u4-l4', 'أيّ مما يأتي ليس من محظورات الإحرام؟', 'تذكّر ما لا يُشترط في السعي.', 'من محظورات الإحرام: التطيب، وتقليم الأظافر، ولبس المخيط وتغطية الرأس للرجل، وصيد البر، وحلق الشعر. أما السعي دون وضوء فجائز.', 2, 110, 31, false, ''),
('rv8.u4.l4.26a', 'u4-l4', 'ما الحكم الشرعي لمن أحرم بالعمرة من الحرم؟', 'الإحرام يكون من المواقيت المكانية.', 'الحكم: لا يجوز؛ فالإحرام يكون من المواقيت المكانية أو ما يحاذيها.', 2, 110, 32, false, ''),
('rv8.u4.l4.26b', 'u4-l4', 'ذهب صبيٌّ لأداء العمرة؛ ما الحكم الشرعي؟', 'العمرة لا تجب على الصبي، لكن هل تصح منه؟', 'الحكم: جائز.', 2, 110, 33, false, ''),
('rv8.u4.l4.27b', 'u4-l4', 'زادت في عدد أشواط الطواف طلبًا للأجر؛ ما تقييم تصرفها؟', 'العدد حدّده الشارع.', 'تصرف خاطئ؛ عليها الالتزام بعدد الأشواط المشروعة، لأن عدد الأشواط عبادة توقيفية حددها الشارع، ولا يمكن تجاوزها بالزيادة أو النقصان.', 1, 110, 34, false, ''),
('rv8.u4.l4.27c', 'u4-l4', 'يزاحم الناس ويدافعهم ليصل إلى الحجر الأسود؛ ما التصرف الصحيح؟', 'المسلم مأمور بأداء العبادات بسكينة ووقار.', 'تصرف خاطئ؛ ينبغي تجنب ذلك، لأن المسلم مأمور بأداء العبادات بسكينة ووقار، دون مزاحمة أو مدافعة، فإن تيسّر له تقبيل الحجر دون مدافعة فله ذلك، وإن لم يستطع يشير إليه مكبّرًا.', 1, 111, 35, false, ''),
('rv8.u4.l5.1', 'u4-l5', 'إلى أيّ البلاد ينتمي سلمان الفارسي رضي الله عنه؟', 'الجواب في لقبه.', 'ينتمي سلمان الفارسي رضي الله عنه إلى بلاد فارس.', 1, 112, 1, false, ''),
('rv8.u4.l5.2', 'u4-l5', 'ما الديانة التي كان يدين بها سلمان الفارسي رضي الله عنه قبل إسلامه؟', 'كُلّف بمهمة تتعلق بالنار.', 'كان سلمان الفارسي يدين بالمجوسية، وهي عبادة النار.', 1, 112, 2, false, ''),
('rv8.u4.l5.3', 'u4-l5', 'ما المهمة التي أُوكلت إلى سلمان الفارسي في قومه لمكانته؟', 'تتعلق بديانة قومه.', 'كُلّف بإشعال النار حتى لا تخبو ساعة في ليل أو نهار؛ وذلك لإخلاصه في المجوسية.', 1, 112, 3, false, ''),
('rv8.u4.l5.5', 'u4-l5', 'لماذا ارتحل سلمان الفارسي إلى بلاد الشام؟', 'مرّ في طريقه على كنيسة.', 'هرب من النار وبحثًا عن النور؛ مرّ على كنيسة لنصارى يتعبدون فأُعجب بهم، وسألهم: أين أصل هذا الدين؟ قالوا: بالشام، فذهب إلى بلاد الشام.', 2, 112, 4, false, ''),
('rv8.u4.l5.6', 'u4-l5', 'كيف استطاع سلمان الفارسي الوصول إلى بلاد الشام؟', 'رافق أتباع الدين الذي أُعجب به.', 'ذهب سلمان رضي الله عنه مع قافلة تجار نصارى إلى بلاد الشام.', 2, 112, 5, false, ''),
('rv8.u4.l5.8', 'u4-l5', 'ما مواصفات المدينة كما وصفها آخر رهبان نصراني التقاه سلمان الفارسي؟', 'الحَرّة أرض ذات حجارة سوداء.', 'وصفها الراهب بأنها بين حرّتين بينهما نخل، وهي يثرب.', 2, 112, 6, false, ''),
('rv8.u4.l5.9', 'u4-l5', 'كيف وصل سلمان الفارسي رضي الله عنه إلى يثرب؟', 'تعرّض للغدر في الطريق.', 'ذهب مع قافلة تجار عرب، لكنهم غدروا به، وباعوه إلى رجل يهودي في يثرب.', 2, 112, 7, false, ''),
('rv8.u4.l5.10', 'u4-l5', 'أيّ مما يأتي ليس من العلامات التي أراد سلمان الفارسي التأكد منها في النبي ﷺ؟', 'اقرأ الخيارات بعناية؛ أحدها عكس علامة صحيحة.', 'العلامات: يأكل الهدية، ولا يأكل الصدقة، وبين كتفيه خاتم النبوة. فقول «يأكل الصدقة» ليس من العلامات.', 2, 112, 8, false, ''),
('rv8.u4.l5.12', 'u4-l5', 'ما دلالة قول سلمان الفارسي رضي الله عنه: «أنا سلمان ابن الإسلام»؟', 'عرّف نفسه بدينه لا بنسبه.', 'يدل على حبه للدين الإسلامي، واعتزازه به، وشعوره بالولاء له.', 1, 113, 9, false, ''),
('rv8.u4.l5.13a', 'u4-l5', 'ما الدور الكبير الذي كان لسلمان الفارسي في غزوة الأحزاب؟', 'خطة حكيمة لم تكن مألوفة عند العرب.', 'أشار سلمان بحفر الخندق، فكان له دور كبير في غزوة الأحزاب، وكانت خطة حكيمة لم تكن مألوفة عند العرب.', 1, 113, 10, false, ''),
('rv8.u4.l5.13b', 'u4-l5', 'كيف خدم سلمان الفارسي المسلمين في فتح مدينة (إيوان)؟', 'كان يعرف لغة الفرس.', 'ترجم بين المسلمين والفرس حتى استسلمت مدينة (إيوان) دون إراقة الدماء.', 2, 113, 11, false, ''),
('rv8.u4.l5.14', 'u4-l5', 'ما الدليل على زهد سلمان الفارسي رضي الله عنه؟', 'كان أميرًا لكنه لم يأكل من مال الإمارة.', 'أصبح واليًا في بلاد الترف والبذخ (المدائن عاصمة الفرس) فكان زاهدًا، يتصدق بعطاء الإمارة، ويأكل من عمل يده، وهو الذي خرج طائعًا مختارًا من ثراء أبيه ونعمائه.', 2, 113, 12, false, ''),
('rv8.u4.l5.15b', 'u4-l5', 'آخى الرسول ﷺ بين سلمان الفارسي رضي الله عنه وبين:', 'صحابي كنيته «أبو ...».', 'آخى الرسول ﷺ بين سلمان الفارسي وبين أبي الدرداء رضي الله عنهما.', 2, 114, 13, false, ''),
('rv8.u4.l5.15c', 'u4-l5', 'أول غزوة شارك فيها سلمان الفارسي رضي الله عنه هي غزوة:', 'الغزوة التي أشار فيها بخطة جديدة.', 'أول غزوة شارك فيها سلمان الفارسي هي غزوة الأحزاب (الخندق).', 1, 114, 14, false, ''),
('rv8.u4.l5.15d', 'u4-l5', 'مَن خليفة المسلمين الذي عيّن سلمان الفارسي واليًا على المدائن؟', 'في عهده فُتحت بلاد فارس.', 'الخليفة الذي عيّن سلمان الفارسي واليًا على المدائن هو عمر بن الخطاب رضي الله عنه.', 2, 114, 15, false, ''),
('rv8.u4.l5.17a', 'u4-l5', 'في قوله تعالى: ﴿وَإِذَا قِيلَ لَهُمُ اتَّبِعُوا مَا أَنزَلَ اللَّهُ قَالُوا بَلْ نَتَّبِعُ مَا أَلْفَيْنَا عَلَيْهِ آبَاءَنَا﴾، ما الفعل الذي ذمّه الله تعالى؟', 'اتباع الآباء دون عقل أو هداية.', 'ذمّ الله تعالى في الآية التقليد الأعمى.', 1, 114, 16, false, ''),
('rv8.u4.l5.17b', 'u4-l5', 'كيف تجنّب سلمان الفارسي رضي الله عنه التقليد الأعمى؟', 'لم يتمسك بملة آبائه.', 'تجنّبه عندما ترك المجوسية بكل شجاعة وهي ملة آبائه، وسعى واجتهد في البحث عن الدين الحق.', 1, 114, 17, false, ''),
('rv8.u4.l5.17c', 'u4-l5', 'ما واجبنا تجاه العادات والتقاليد الموروثة المخالفة للشرع؟', 'المخالف للشرع لا يُتّبع ولو كان موروثًا.', 'واجبنا رفضها وتجنبها والحذر منها، وتعريف الناس ببطلانها ومخالفتها، والسعي لتصحيح فكر الناس تجاهها.', 1, 114, 18, false, ''),
('rv8.u4.l5.18', 'u4-l5', 'تحقّق سلمان الفارسي من علامات النبوة التي ذكرها له الراهب؛ ما المعنى الذي يشير إليه هذا الموقف؟', 'لم يكتفِ بما سمع حتى رأى بنفسه.', 'الموقف يشير إلى التثبت من صحة المعلومة؛ فأتثبت من صحة ما أسمعه أو ينقل إليّ من أخبار.', 1, 115, 19, false, ''),
('rv8.u4.l6.1', 'u4-l6', 'ماذا نعني باحترام الخصوصية؟', 'الخصوصية مساحة خاصة يُمنع اختراقها.', 'احترام الخصوصية: احترام حق الفرد في المحافظة على سرية معلوماته وعلاقاته الشخصية من أن يطّلع عليها أحد، فهي مساحة خاصة يُمنع اختراقها.', 1, 116, 1, false, ''),
('rv8.u4.l6.2', 'u4-l6', 'أيّ الآيات الآتية تكرّس شرعية الحق في الخصوصية؟', 'الآية تأمر بطلب الإذن قبل الدخول.', 'من الآيات: ﴿وَإِذَا بَلَغَ الْأَطْفَالُ مِنكُمُ الْحُلُمَ فَلْيَسْتَأْذِنُوا﴾، و﴿يَا أَيُّهَا الَّذِينَ آمَنُوا اجْتَنِبُوا كَثِيرًا مِّنَ الظَّنِّ... وَلَا تَجَسَّسُوا﴾.', 1, 116, 2, false, ''),
('rv8.u4.l6.4', 'u4-l6', 'أيّ مما يأتي من أسباب تدخّل البعض في خصوصيات الآخرين؟', 'ثلاثة من الخيارات سلوكيات صحيحة.', 'من أسباب التدخل في خصوصيات الآخرين: فضول النفس، وقلة الوعي، وغياب ثقافة احترام الخصوصية، والخلط بين الحرية والخصوصية، والرغبة في إيذاء الآخرين، وغياب الاهتمامات المفيدة.', 1, 116, 3, false, ''),
('rv8.u4.l6.5', 'u4-l6', 'كيف يحترم الإنسان خصوصية الآخرين؟', 'يكفّ نفسه عن الأسئلة والتفتيش.', 'يحترم خصوصيتهم بألا يتطفل عليهم بالأسئلة الشخصية، ولا يسيء الظن بهم، ولا يتتبع أخبار الناس وأسرارهم، ولا يفتش أغراضهم.', 1, 116, 4, false, ''),
('rv8.u4.l6.6', 'u4-l6', 'كيف يوصل سوء الظن إلى التدخل في خصوصيات الآخرين؟', 'نهى الإسلام عن سوء الظن ثم أتبعه بالنهي عن أمر آخر.', 'قد يقود سوء الظن إلى التجسس على الآخرين، لذلك نهى الإسلام عن سوء الظن وأتبعه بالنهي عن التجسس.', 2, 117, 5, false, ''),
('rv8.u4.l6.7', 'u4-l6', 'علّل: كره الإسلام سؤال الناس عن خصوصياتهم.', 'ليس من واجب الآخر الإجابة عن كل سؤال.', 'لما في ذلك من إحراج لهم، فهناك بعض الأسئلة ليس من واجب الآخر الإجابة عنها، ولأن ذلك من علامات حسن إسلام المرء؛ قال ﷺ: «من حسن إسلام المرء تركه ما لا يعنيه».', 2, 117, 6, false, ''),
('rv8.u4.l6.8', 'u4-l6', 'أيّ مما يأتي من التوجيهات الإسلامية في احترام الخصوصية؟', 'ثلاثة من الخيارات منهيّ عنها.', 'من التوجيهات الإسلامية: الاستئذان، وتجنب التجسس، وعدم التدخل في شؤون الآخرين، واحترام وجهات النظر المختلفة، وعدم تتبع العورات، وعدم سؤال الناس عن خصوصياتهم.', 1, 117, 7, false, ''),
('rv8.u4.l6.9', 'u4-l6', 'ماذا تستنتج من قوله ﷺ: «من حُسن إسلام المرء تركُه ما لا يعنيه»؟', 'من يحشر أنفه في خصوصيات الآخرين يسيء إلى إسلامه.', 'ترك المسلم ما لا يعنيه من أمور الآخرين الشخصية وعدم التدخل في شؤونهم مؤشر على حسن إسلامه، ومن يحشر أنفه في خصوصيات الآخرين فهو ممن يسيء إلى إسلامه، ومن احترم الخصوصية ستره الله يوم القيامة.', 1, 117, 8, false, ''),
('rv8.u4.l6.11', 'u4-l6', 'ماذا تستنتج من قوله ﷺ: «إن الله كره لكم قيل وقال، وكثرة السؤال، وإضاعة المال»؟', '«كثرة السؤال» مكروهة.', 'إن الإسلام كره سؤال الناس عن خصوصياتهم لما فيه من إحراج لهم، لذلك ينبغي أن نعرف متى نسأل، وماذا نسأل، وما لا نسأل.', 2, 117, 9, false, ''),
('rv8.u4.l6.12', 'u4-l6', 'إلى أيّ أنواع الخصوصية تنتمي «سرية البيانات المرضية»؟', 'تتعلق بالمرض.', 'أنواع الخصوصية: الأمور المادية (الوثائق والمراسلات والأجهزة)، والأمور الأسرية (أهل بيته وأبناؤه وأقاربه)، والأمور الصحية (سرية بياناته المرضية وصون حرمته عند موته).', 1, 118, 10, false, ''),
('rv8.u4.l6.13', 'u4-l6', 'علّل: يُعدّ صون حرمة الإنسان عند الموت من الخصوصية الشخصية.', 'الميت لا يستطيع الدفاع عن نفسه.', 'لأنه في وضع عاجز فيه عن حماية نفسه وصيانتها.', 2, 118, 11, false, ''),
('rv8.u4.l6.14', 'u4-l6', 'علّل: أمر النبي ﷺ بالستر وغض الطرف وتجنب الفضح والتشهير.', 'التشهير قد يضرّ صاحبه ضررًا كبيرًا.', 'أمر النبي ﷺ بالستر حتى لا يكون الشخص سببًا في نشر السوء عن أخيه، فيعرّض حياته للخطر.', 2, 118, 12, false, ''),
('rv8.u4.l6.15', 'u4-l6', '«احترام الخصوصية واجب ديني واجتماعي»؛ بيّن ذلك.', 'فكّر في أثره على حياة الناس الهادئة الآمنة.', 'احترام الخصوصية واجب ديني واجتماعي لما له من أثر إيجابي في تنظيم العلاقات بين الناس، ورسم الحدود لها، لينعموا بحياة طيبة هادئة آمنين على حياتهم الخاصة من عيون المتلصصين.', 2, 118, 13, false, ''),
('rv8.u4.l6.16a', 'u4-l6', 'أعطاه زميله هاتفه ليشاهد صور تخرجه، فاستغل ذلك في مشاهدة ألبوم الصور والرسائل والمحادثات. ما تقييم تصرفه؟', 'الإذن كان لصور التخرج فقط.', 'تصرفه خاطئ؛ عليه احترام خصوصية الآخرين، وعدم الاطلاع على الأمور الشخصية.', 1, 118, 14, false, ''),
('rv8.u4.l6.16b', 'u4-l6', 'تراقب جارتها من النافذة وتحاصرها بالأسئلة كلما خرجت أو جاءها زوار. ما تقييم تصرفها؟', 'هل يرضى أحد أن يُراقَب؟', 'تصرفها خاطئ؛ عليها احترام خصوصية الآخرين، وعدم الاطلاع على الأمور الشخصية، ومثل هذا التدخل فيه إيذاء وإحراج للآخرين.', 1, 118, 15, false, ''),
('rv8.u4.l6.16c', 'u4-l6', 'صوّرت تفاصيل زفاف إحدى زميلاتها بكاميرا هاتفها رغم التنبيه بحظر التصوير. ما تقييم تصرفها؟', 'ما لا يرضاه الإنسان لنفسه لا يرضاه لغيره.', 'أخطأت عندما فعلت ذلك؛ فما لا يرضاه الإنسان لنفسه لا يرضاه لغيره، فتصوير هذه الحفلات دون إذن أصحابها ونشرها فيه انتهاك لحرمات وخصوصيات الآخرين.', 1, 119, 16, false, ''),
('rv8.u4.l6.17', 'u4-l6', 'أيّ مما يأتي من العواقب القانونية لتصوير الآخرين دون إذن؟', 'العواقب القانونية تتعلق بالمحاكم والعقوبات.', 'من العواقب المعنوية: كشف ستر الآخرين وتعريضهم للإحراج والتشهير بهم، ومن العواقب القانونية: تعريض الشخص للمساءلة القانونية، وقد تصل العقوبة للسجن والغرامة.', 2, 119, 17, false, ''),
('rv8.u4.l6.18', 'u4-l6', 'قال رسول الله ﷺ: «المستشار مؤتمن»؛ كيف تتحقق الخصوصية في هذا التوجيه؟', 'المستشار مؤتمن على الأسرار.', 'لا يجوز كشف أسرار من استشاره وما استشاره فيه، فهو مؤتمن على ذلك.', 1, 119, 18, false, ''),
('rv8.u4.l6.19', 'u4-l6', 'كيف تحافظ الطبيبة على خصوصيات الآخرين في عملها؟', 'المرضى يأتمنونها على أسرارهم.', 'تحافظ الطبيبة على خصوصيات الآخرين بحفظ أسرار المرضى وتجنب الكشف عنها.', 1, 119, 19, false, ''),
('rv8.u4.l6.20a', 'u4-l6', 'دخلت مطبخ جارتها وفتحت الثلاجة دون أن تستأذن لتتبع أحوال معيشتهم. ما تقويم الخطأ؟', 'للبيوت حرمة.', 'عليها تجنب ذلك؛ لأن البيوت لها حرمتها.', 1, 120, 20, false, ''),
('rv8.u4.l6.20b', 'u4-l6', 'التقط صورة لحادث سير مروري ونشرها عبر وسائل التواصل الاجتماعي. ما تقويم الخطأ؟', 'فكّر في المصاب وأسرته.', 'عليه تجنب ذلك لما له من تأثير سلبي على الشخص وأسرته، ويعرّض الشخص للمساءلة.', 1, 120, 21, false, ''),
('rv8.u4.l6.21', 'u4-l6', 'ما نصيحتك لمن ينشر خصوصياته على وسائل التواصل الاجتماعي من أجل الشهرة وكسب المال؟', 'قد يصل ذلك إلى خدش الحياء وانتقاص المروءة.', 'ينبغي له حفظ خصوصياته وتجنب عرضها، فلا يجعل حياته الشخصية مطيّة للشهرة وكسب المال بصورة تصل أحيانًا إلى خدش الحياء وانتقاص المروءة.', 1, 120, 22, false, '');
